var M = [
{"k":"أَب","c":"آباء","m":"(ج) آباء: والِد، ﴿إنَّ أَبي يَدْعُوكَ لِيَجْزِيَكَ أَجْرَ ما سَقَيْتَ لَنا﴾، ﴿واتَّبَعْتُ مِلَّةَ آبائي﴾. وهُوَ من الأَسْماءِ الخَمْسَةِ الَّتي تُرْفَعُ بالواو، وتُنْصَبُ بالأَلِف، وتُجَرُّ بالياء. “جاءَ أبوكَ- رأيت أباكَ- سَلَّمْتُ على أبيكَ”.","t":"والِد. وهُوَ من الأَسْماءِ الخَمْسَةِ الَّتي تُرْفَعُ بالواو، وتُنْصَبُ بالأَلِف، وتُجَرُّ بالياء.","o":["﴿إنَّ أَبي يَدْعُوكَ لِيَجْزِيَكَ أَجْرَ ما سَقَيْتَ لَنا﴾","﴿واتَّبَعْتُ مِلَّةَ آبائي﴾","جاءَ أبوكَ- رأيت أباكَ- سَلَّمْتُ على أبيكَ"],"b":["﴿واتَّبَعْتُ مِلَّةَ آبائي﴾","آبائي"],"tr":"baba","ttr":"Baba. Merfu iken vav, mansub iken elif, mecrur iken ya ile çekimlenen 'beş isim'dendir.","otr":["Babam, bizim için (hayvanlarımızı) suladığının karşılığını vermek üzere seni çağırıyor.","Atalarımın dinine uydum.","Baban geldi - babanı gördüm - babana selam verdim."],"r":null,"s":1,"y":[["جمع","آباء"]]},
{"k":"أَباحَ","c":"","m":"يُبيحُ إِباحَةً: (١) أحَلَّ، أجازَ. “أَباحَ اللهُ البَيْعَ”. (٢) أَظْهَرَ ونَشَرَ، “أَباحَ السِّرَّ”.","t":"(١) أحَلَّ، أجازَ. (٢) أَظْهَرَ ونَشَرَ.","o":["أَباحَ اللهُ البَيْعَ","أَباحَ السِّرَّ"],"b":["أَباحَ اللهُ البَيْعَ","أَباحَ"],"tr":"helal kılmak, izin vermek","ttr":"(1) Helal kıldı, caiz gördü. (2) Açığa vurdu, yaydı.","otr":["Allah alışverişi helal kıldı.","Sırrı açığa vurdu."],"r":null,"s":1,"f":"يُبيحُ إِباحَةً"},
{"k":"إِباحَة","c":"","m":"مَصْدَرُ أَباحَ؛ في الفِقْهِ: حُكْمٌ يَقْتَضي التَّخْييرَ بَيْنَ الفِعْلِ والتَّرْك. “حُكْمُ التَّرويحِ عَنِ النَّفْسِ الإِباحَةُ”.","t":"مَصْدَرُ أَباحَ؛ في الفِقْهِ: حُكْمٌ يَقْتَضي التَّخْييرَ بَيْنَ الفِعْلِ والتَّرْك.","o":["حُكْمُ التَّرويحِ عَنِ النَّفْسِ الإِباحَةُ"],"b":["حُكْمُ التَّرويحِ عَنِ النَّفْسِ الإِباحَةُ","الإِباحَةُ"],"tr":"mubahlık, serbestlik","ttr":"Ebâha fiilinin mastarı; fıkıhta: yapmak ile terk etmek arasında serbest bırakmayı gerektiren hüküm.","otr":["Eğlenip dinlenmenin hükmü mubahlıktır."],"r":null,"s":1},
{"k":"أَبادَ","c":"","m":"يُبيدُ إِبادَةً: أَهْلَكَ، أَبادَ الجَيْشُ العَدُوَّ. أَبادَتِ الحُروبُ آلافَ النّاسِ: قَتَلَتْهُم وأَهْلَكَتْهُم.","t":"أَهْلَكَ.","o":["أَبادَ الجَيْشُ العَدُوَّ","أَبادَتِ الحُروبُ آلافَ النّاسِ: قَتَلَتْهُم وأَهْلَكَتْهُم"],"b":["أَبادَ الجَيْشُ العَدُوَّ","أَبادَ"],"tr":"yok etmek, imha etmek","ttr":"Helak etti, yok etti.","otr":["Ordu düşmanı yok etti.","Savaşlar binlerce insanı yok etti: onları öldürdü ve helak etti."],"r":null,"s":1,"f":"يُبيدُ إِبادَةً"},
{"k":"أَبْجَدِيَّة","c":"","m":"حُروفُ اللُّغَةِ العَرَبِيَّةِ مُرَتَّبَةً كَالتّالي: أبجد هوز حطي كلمن سعفص قرشت ثخذ ضظغ. وَهٰذا التَّرْتيبُ غَيْرُ التَّرْتيبِ الأَلِفْبائي. انظر أَلِفْباء.","t":"حُروفُ اللُّغَةِ العَرَبِيَّةِ مُرَتَّبَةً كَالتّالي: أبجد هوز حطي كلمن سعفص قرشت ثخذ ضظغ. وَهٰذا التَّرْتيبُ غَيْرُ التَّرْتيبِ الأَلِفْبائي.","o":[],"b":null,"tr":"ebced (alfabe sırası)","ttr":"Arap dilinin harflerinin şu sırayla dizilmesi: ebced hevvez huttî kelemen sa'fas kareşet sehaz dazağ. Bu sıralama elifbâ sıralamasından farklıdır. Bkz. elifbâ.","otr":[],"r":null,"s":1},
{"k":"أَبْحَرَ","c":"","m":"يُبْحِرُ إِبْحاراً، أَبْحَرَتِ السَّفينَةُ: سارَتْ في البَحْرِ، أَبْحَرَ الشَّخْصُ؛ رَكِبَ البَحْرَ أَوْ سافَرَ بَحْراً.","t":"أَبْحَرَتِ السَّفينَةُ: سارَتْ في البَحْرِ، أَبْحَرَ الشَّخْصُ؛ رَكِبَ البَحْرَ أَوْ سافَرَ بَحْراً.","o":["أَبْحَرَتِ السَّفينَةُ","أَبْحَرَ الشَّخْصُ"],"b":["أَبْحَرَتِ السَّفينَةُ: سارَتْ في البَحْرِ","أَبْحَرَتِ"],"tr":"denize açılmak","ttr":"Gemi denize açıldı: denizde yol aldı; kişi denize açıldı: denize bindi ya da deniz yoluyla yolculuk etti.","otr":["Gemi denize açıldı.","Kişi denize açıldı."],"r":null,"s":1,"f":"يُبْحِرُ إِبْحاراً"},
{"k":"أَبَداً","c":"","m":"ظَرْفُ زَمانٍ لِلْمُسْتَقْبَلِ يَدُلُّ عَلى الاسْتِمْرارِ: دائماً ﴿خالِدينَ فيها أَبَداً﴾، “لا أَفْعَلُ ذٰلِكَ أَبَدَ الآبِدينَ”.","t":"ظَرْفُ زَمانٍ لِلْمُسْتَقْبَلِ يَدُلُّ عَلى الاسْتِمْرارِ: دائماً.","o":["﴿خالِدينَ فيها أَبَداً﴾","لا أَفْعَلُ ذٰلِكَ أَبَدَ الآبِدينَ"],"b":["﴿خالِدينَ فيها أَبَداً﴾","أَبَداً"],"tr":"ebediyen, asla","ttr":"Devamlılık bildiren, gelecek için kullanılan zaman zarfı: daima.","otr":["Orada ebedî olarak kalıcılardır.","Bunu ebediyen asla yapmam."],"r":null,"s":1},
{"k":"أَبْدَعَ","c":"","m":"يُبْدِعُ إِبْداعاً؛ اخْتَرَعَ وابْتَكَرَ وخَلَقَ. “أَبْدَعَ اللهُ الكَوْنَ، فَأَحْسَنَ خَلْقَهُ”.","t":"اخْتَرَعَ وابْتَكَرَ وخَلَقَ.","o":["أَبْدَعَ اللهُ الكَوْنَ، فَأَحْسَنَ خَلْقَهُ"],"b":["أَبْدَعَ اللهُ الكَوْنَ، فَأَحْسَنَ خَلْقَهُ","أَبْدَعَ"],"tr":"yoktan yaratmak, icat etmek","ttr":"İcat etti, benzersiz bir şey ortaya koydu ve yarattı.","otr":["Allah evreni eşsiz biçimde yarattı ve yaratılışını en güzel kıldı."],"r":null,"s":1,"y":[["مصدر","إِبْداع"]],"f":"يُبْدِعُ إِبْداعاً"},
{"k":"أَبْدَى","c":"","m":"يُبْدي إِبْداءً؛ أَبْدى رَأْيَهُ: أَظْهَرَهُ، أَبْدى رَغْبَتَهُ: أَظْهَرَها. ﴿إِنْ تُبْدُوا الصَّدَقاتِ فَنِعِمّا هِيَ﴾.","t":"أَظْهَرَ.","o":["أَبْدى رَأْيَهُ: أَظْهَرَهُ","أَبْدى رَغْبَتَهُ: أَظْهَرَها","﴿إِنْ تُبْدُوا الصَّدَقاتِ فَنِعِمّا هِيَ﴾"],"b":["أَبْدى رَأْيَهُ","أَبْدى"],"tr":"açığa vurmak, göstermek","ttr":"Görüşünü ortaya koydu: açığa vurdu; isteğini belirtti: açığa vurdu.","otr":["Görüşünü açıkladı.","İsteğini belli etti.","Sadakaları açıktan verirseniz o ne güzeldir."],"r":null,"s":1,"f":"يُبْدي إِبْداءً"},
{"k":"إِبْرَة","c":"إِبَر","m":"(ج) إِبَر: أَداةٌ يُخاطُ بِها، أَحَدُ طَرَفَيْها مُحَدَّدٌ والآخَرُ مَثْقوبٌ. وإِبْرَةُ النَّحْلَةِ والعَقْرَبِ: شَوْكَةٌ في مُؤَخَّرِ جِسْمَيْهِما، تَلْسَعانِ بِها.","t":"(١) أَداةٌ يُخاطُ بِها، أَحَدُ طَرَفَيْها مُحَدَّدٌ والآخَرُ مَثْقوبٌ. (٢) إِبْرَةُ النَّحْلَةِ والعَقْرَبِ: شَوْكَةٌ في مُؤَخَّرِ جِسْمَيْهِما، تَلْسَعانِ بِها.","o":["إِبْرَةُ النَّحْلَةِ والعَقْرَبِ"],"b":["إِبْرَةُ النَّحْلَةِ والعَقْرَبِ: شَوْكَةٌ في مُؤَخَّرِ جِسْمَيْهِما","إِبْرَةُ"],"tr":"iğne","ttr":"(1) Dikiş dikilen, bir ucu sivri öbür ucu delikli alet. (2) Arının ve akrebin iğnesi: gövdelerinin arka ucunda bulunan, sokmaya yarayan diken.","otr":["Arının ve akrebin iğnesi"],"r":"p01_1","s":1,"y":[["جمع","إِبَر"]]},
{"k":"أَبْرَدَ","c":"","m":"يُبْرِدُ إِبْراداً: جَعَلَ الشَّيْءَ الحارَّ بارِداً، أَبْرَدْتُ الطَّعامَ: صَيَّرْتُهُ بارِداً.","t":"جَعَلَ الشَّيْءَ الحارَّ بارِداً.","o":["أَبْرَدْتُ الطَّعامَ: صَيَّرْتُهُ بارِداً"],"b":["أَبْرَدْتُ الطَّعامَ","أَبْرَدْتُ"],"tr":"soğutmak","ttr":"Sıcak şeyi soğuk hâle getirdi.","otr":["Yemeği soğuttum: onu soğuk hâle getirdim."],"r":null,"s":1,"f":"يُبْرِدُ إِبْراداً"},
{"k":"أَبْرَزَ","c":"","m":"يُبْرِزُ إِبْرازاً؛ أَبْرَزَ الشَّيْءَ: أَظْهَرَهُ وبَيَّنَهُ، أَبْرَزَ الكاتِبُ فِكْرَتَهُ: أَوْضَحَها.","t":"أَبْرَزَ الشَّيْءَ: أَظْهَرَهُ وبَيَّنَهُ.","o":["أَبْرَزَ الكاتِبُ فِكْرَتَهُ: أَوْضَحَها"],"b":["أَبْرَزَ الكاتِبُ فِكْرَتَهُ","أَبْرَزَ"],"tr":"ortaya koymak, öne çıkarmak","ttr":"Bir şeyi ortaya çıkardı ve açıkça gösterdi.","otr":["Yazar fikrini ortaya koydu: onu açıkladı."],"r":"p01_2","s":1,"f":"يُبْرِزُ إِبْرازاً"},
{"k":"أَبْرَص","c":"","m":"مُصابٌ بِداءِ البَرَصِ، وهُوَ بَياضٌ يَظْهَرُ في الجَسَدِ، ﴿وأُبْرِئُ الأَكْمَهَ والأَبْرَصَ﴾.","t":"مُصابٌ بِداءِ البَرَصِ، وهُوَ بَياضٌ يَظْهَرُ في الجَسَدِ.","o":["﴿وأُبْرِئُ الأَكْمَهَ والأَبْرَصَ﴾"],"b":["﴿وأُبْرِئُ الأَكْمَهَ والأَبْرَصَ﴾","والأَبْرَصَ"],"tr":"alaca hastalıklı","ttr":"Baras (alaca) hastalığına yakalanmış kimse; baras, bedende beliren beyaz lekelerdir.","otr":["Doğuştan körü ve alacalıyı iyileştiririm."],"r":"p02_1","s":2},
{"k":"إِبْريق","c":"أَباريق","m":"(ج) أَباريق: وِعاءٌ مِنَ المَعْدَنِ أَوِ البلاسْتيك يُصَبُّ مِنْهُ الماءُ مِثْلُ: إِبْريقِ الماءِ وإِبْريقِ الشّاي.","t":"وِعاءٌ مِنَ المَعْدَنِ أَوِ البلاسْتيك يُصَبُّ مِنْهُ الماءُ.","o":["إِبْريقِ الماءِ","إِبْريقِ الشّاي"],"b":["مِثْلُ: إِبْريقِ الماءِ وإِبْريقِ الشّاي","وإِبْريقِ"],"tr":"ibrik, demlik","ttr":"Madenden ya da plastikten yapılmış, içinden su dökülen kap.","otr":["su ibriği","çaydanlık (çay ibriği)"],"r":"p02_2","s":2,"y":[["جمع","أَباريق"]]},
{"k":"أَبْصَرَ","c":"","m":"يُبْصِرُ إِبْصاراً: رَأَى، “أَبْصَرْتُ الرَّجُلَ في الطَّريقِ”، ﴿فَمَنْ أَبْصَرَ فَلِنَفْسِهِ﴾.","t":"رَأَى.","o":["أَبْصَرْتُ الرَّجُلَ في الطَّريقِ","﴿فَمَنْ أَبْصَرَ فَلِنَفْسِهِ﴾"],"b":["أَبْصَرْتُ الرَّجُلَ في الطَّريقِ","أَبْصَرْتُ"],"tr":"görmek","ttr":"Gördü.","otr":["Adamı yolda gördüm.","Kim (gerçeği) görürse kendi lehinedir."],"r":null,"s":2,"f":"يُبْصِرُ إِبْصاراً"},
{"k":"إِبِط","c":"آباط","m":"(ج) آباط: باطِنُ الكَتِفِ (المَنْكِب)، “مِنْ سُنَنِ الفِطْرَةِ نَتْفُ الإِبِطِ”.","t":"باطِنُ الكَتِفِ (المَنْكِب).","o":["مِنْ سُنَنِ الفِطْرَةِ نَتْفُ الإِبِطِ"],"b":["مِنْ سُنَنِ الفِطْرَةِ نَتْفُ الإِبِطِ","الإِبِطِ"],"tr":"koltuk altı","ttr":"Omuzun iç (alt) tarafı.","otr":["Koltuk altı kıllarını yolmak fıtrat sünnetlerindendir."],"r":"p02_3","s":2},
{"k":"أَبْطَأَ","c":"","m":"يُبْطِئُ إِبْطاءً: تَمَهَّلَ، تَأَخَّرَ؛ خِلافُ أَسْرَعَ، “أَبْطَأَ الطّالِبُ في الإِجابَةِ”.","t":"تَمَهَّلَ، تَأَخَّرَ؛ خِلافُ أَسْرَعَ.","o":["أَبْطَأَ الطّالِبُ في الإِجابَةِ"],"b":["أَبْطَأَ الطّالِبُ في الإِجابَةِ","أَبْطَأَ"],"tr":"ağır davranmak, gecikmek","ttr":"Ağırdan aldı, gecikti; acele etmenin zıddı.","otr":["Öğrenci cevap vermekte gecikti."],"r":null,"s":2,"f":"يُبْطِئُ إِبْطاءً"},
{"k":"أَبْعَدُ","c":"","m":"خِلافُ أَقْرَب. “البَيْتُ أَبْعَدُ مِنَ المَسْجِدِ، وأَقْرَبُ إِلى مَكانِ العَمَلِ”.","t":"خِلافُ أَقْرَب.","o":["البَيْتُ أَبْعَدُ مِنَ المَسْجِدِ، وأَقْرَبُ إِلى مَكانِ العَمَلِ"],"b":["البَيْتُ أَبْعَدُ مِنَ المَسْجِدِ","أَبْعَدُ"],"tr":"daha uzak","ttr":"'Daha yakın'ın zıddı.","otr":["Ev camiden daha uzak, iş yerine daha yakın."],"r":null,"s":2},
{"k":"أَبْغَضُ","c":"","m":"خِلافُ أَحَبُّ، جاءَ في الحَديثِ: (أَبْغَضُ الرِّجالِ إِلى اللهِ الأَلَدُّ الخَصِمُ).","t":"خِلافُ أَحَبُّ.","o":["أَبْغَضُ الرِّجالِ إِلى اللهِ الأَلَدُّ الخَصِمُ"],"b":["أَبْغَضُ الرِّجالِ إِلى اللهِ الأَلَدُّ الخَصِمُ","أَبْغَضُ"],"tr":"en sevimsiz, en nefret edilen","ttr":"'En sevimli'nin zıddı.","otr":["Allah katında insanların en sevimsizi, inatçı ve kavgacı olandır. (hadis)"],"r":null,"s":2},
{"k":"أَبْقَى","c":"","m":"يُبْقي إِبْقاءً (١) حَفِظَ: “أَبْقى عَلَى الشَّيْءِ”. (٢) تَرَكَ: “أَبْقى شَعْبَهُ عَلَى جَهْلِهِ”.","t":"(١) حَفِظَ. (٢) تَرَكَ.","o":["أَبْقى عَلَى الشَّيْءِ","أَبْقى شَعْبَهُ عَلَى جَهْلِهِ"],"b":["أَبْقى شَعْبَهُ عَلَى جَهْلِهِ","أَبْقى"],"tr":"korumak, bırakmak","ttr":"(1) Korudu, muhafaza etti. (2) Bıraktı, (olduğu gibi) terk etti.","otr":["Şeyi korudu.","Halkını cehaleti içinde bıraktı."],"r":null,"s":2,"y":[["مصدر","إِبْقاء"]]},
{"k":"إِبِل","c":"","m":"جِمال. واحِدُها: جَمَلٌ أَوْ بَعيرٌ. ﴿أَفَلا يَنْظُرُونَ إِلَى الأبِلِ كَيْفَ خُلِقَتْ﴾، وفي المَثَلِ: “ما هٰكَذا يا سَعْدُ تُورَدُ الإِبِلُ”. يُضْرَبُ لِمَن يَتَكَلَّفُ أَمْراً لا يُحْسِنُهُ.","t":"جِمال. واحِدُها: جَمَلٌ أَوْ بَعيرٌ.","o":["﴿أَفَلا يَنْظُرُونَ إِلَى الأبِلِ كَيْفَ خُلِقَتْ﴾","ما هٰكَذا يا سَعْدُ تُورَدُ الإِبِلُ"],"b":["ما هٰكَذا يا سَعْدُ تُورَدُ الإِبِلُ","الإِبِلُ"],"tr":"develer","ttr":"Develer. Tekili: cemel ya da ba'îr (deve).","otr":["Develere bakmazlar mı, nasıl yaratılmışlar?","Ey Sa'd, develer suya böyle götürülmez! (Bir işi beceremediği hâlde üstlenen kimse için söylenen atasözü.)"],"r":"p02_4","s":2},
{"k":"إِبْليس","c":"أَبالِسَة، أَباليس","m":"(ج) أَبالِسَة وأَباليس: كَبيرُ الشَّياطين، قالَ تَعالَى: ﴿إِلا إِبْليسَ كانَ مِنَ الجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِ﴾.","t":"كَبيرُ الشَّياطين.","o":["﴿إِلا إِبْليسَ كانَ مِنَ الجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِ﴾"],"b":["﴿إِلا إِبْليسَ كانَ مِنَ الجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِ﴾","إِبْليسَ"],"tr":"İblis, şeytan","ttr":"Şeytanların büyüğü.","otr":["Yalnız İblis (secde etmedi); o cinlerdendi ve Rabbinin emrinden dışarı çıktı."],"r":null,"s":2,"y":[["جمع","أَبالِسَة"]]},
{"k":"أُبُوَّة","c":"","m":"عَلاقَةُ القَرابَةِ مِنْ جِهَةِ الأَبِ، تُقابِلُها أُمومَة، رابِطَةُ الأُبُوَّةِ: ما يَرْبِطُ الوالِدَ بِأَبْنائِهِ.","t":"عَلاقَةُ القَرابَةِ مِنْ جِهَةِ الأَبِ، تُقابِلُها أُمومَة.","o":["رابِطَةُ الأُبُوَّةِ: ما يَرْبِطُ الوالِدَ بِأَبْنائِهِ"],"b":["رابِطَةُ الأُبُوَّةِ: ما يَرْبِطُ الوالِدَ بِأَبْنائِهِ","الأُبُوَّةِ"],"tr":"babalık","ttr":"Baba tarafından olan akrabalık bağı; karşılığı annelik.","otr":["Babalık bağı: babayı çocuklarına bağlayan şey."],"r":null,"s":2},
{"k":"أَبَى","c":"","m":"يَأْبَى إِباءً؛ (١): كَرِهَ الشَّيْءَ ورَفَضَهُ، “أَبى الطِّفْلُ تَناوُلَ الدَّواءِ”. (٢) أَصَرَّ عَلَى فِعْلِهِ، ﴿ويَأْبَى اللهُ إِلا أَنْ يُتِمَّ نُورَهُ﴾.","t":"(١) كَرِهَ الشَّيْءَ ورَفَضَهُ. (٢) أَصَرَّ عَلَى فِعْلِهِ.","o":["أَبى الطِّفْلُ تَناوُلَ الدَّواءِ","﴿ويَأْبَى اللهُ إِلا أَنْ يُتِمَّ نُورَهُ﴾"],"b":["أَبى الطِّفْلُ تَناوُلَ الدَّواءِ","أَبى"],"tr":"reddetmek, kabul etmemek","ttr":"(1) Bir şeyden hoşlanmadı ve onu reddetti. (2) Yapmakta ısrar etti.","otr":["Çocuk ilacı içmeyi reddetti.","Allah ise nurunu tamamlamaktan başkasını kabul etmez."],"r":null,"s":2,"f":"يَأْبَى إِباءً"},
{"k":"أَبْيَض","c":"","m":"(مُؤ) بَيْضاء: خِلافُ أَسْوَد، المُتَّصِفُ بِالبَياضِ، “أَبْيَضُ كَاللَّبَنِ، وأَبْيَضُ كَالثَّلْجِ”.","t":"خِلافُ أَسْوَد، المُتَّصِفُ بِالبَياضِ.","o":["أَبْيَضُ كَاللَّبَنِ، وأَبْيَضُ كَالثَّلْجِ"],"b":["أَبْيَضُ كَالثَّلْجِ","أَبْيَضُ"],"tr":"beyaz","ttr":"Siyahın zıddı; beyazlık niteliğine sahip olan. Müennesi: beyzâ'.","otr":["Süt gibi beyaz, kar gibi beyaz."],"r":"p02_5","s":2},
{"k":"آتٍ","c":"","m":"(مُؤ) آتِيَة: (١) مَنْ يَأْتي أَوْ يَحْضُر. (٢) مُقْبِل أو واقِع، ﴿إِنَّ ما تُوعَدُونَ لَآتٍ﴾.","t":"(١) مَنْ يَأْتي أَوْ يَحْضُر. (٢) مُقْبِل أو واقِع.","o":["﴿إِنَّ ما تُوعَدُونَ لَآتٍ﴾"],"b":["﴿إِنَّ ما تُوعَدُونَ لَآتٍ﴾","لَآتٍ"],"tr":"gelen, gelecek olan","ttr":"(1) Gelen ya da hazır bulunan kimse. (2) Yaklaşan ya da mutlaka gerçekleşecek olan. Müennesi: âtiye.","otr":["Size vaat edilen şey mutlaka gelecektir."],"r":null,"s":2},
{"k":"أَتْقَنَ","c":"","m":"يُتْقِنُ إِتْقاناً: أَحْكَمَ، أَجادَ، “لابُدَّ لِلطَّبيبِ أَنْ يُتْقِنَ عَمَلَهُ”، “أَكْمَلَ العامِلُ عَمَلَهُ بِسُرْعَةٍ وإِتْقان”، ﴿صُنْعَ اللهِ الَّذي أَتْقَنَ كُلَّ شَيْءٍ﴾.","t":"أَحْكَمَ، أَجادَ.","o":["لابُدَّ لِلطَّبيبِ أَنْ يُتْقِنَ عَمَلَهُ","أَكْمَلَ العامِلُ عَمَلَهُ بِسُرْعَةٍ وإِتْقان","﴿صُنْعَ اللهِ الَّذي أَتْقَنَ كُلَّ شَيْءٍ﴾"],"b":["لابُدَّ لِلطَّبيبِ أَنْ يُتْقِنَ عَمَلَهُ","يُتْقِنَ"],"tr":"sağlam yapmak, ustalıkla yapmak","ttr":"Sağlam ve kusursuz yaptı, iyi yaptı.","otr":["Doktorun işini ustalıkla yapması şarttır.","İşçi işini hızla ve ustalıkla tamamladı.","Her şeyi sağlam ve yerli yerinde yapan Allah'ın sanatı."],"r":null,"s":2,"y":[["مصدر","إِتْقان"]],"f":"يُتْقِنُ إِتْقاناً"},
{"k":"أَتْقَى","c":"","m":"أَكْثَرُ تَقْوى، وأَكْثَرُ خَوْفاً وخَشْيَةً؛ والتَّقْوى: الخَوْفُ والخَشْيَةُ مِنَ اللهِ، ﴿إِنَّ أَكْرَمَكُمْ عِنْدَ اللهِ أَتْقاكُمْ﴾.","t":"أَكْثَرُ تَقْوى، وأَكْثَرُ خَوْفاً وخَشْيَةً؛ والتَّقْوى: الخَوْفُ والخَشْيَةُ مِنَ اللهِ.","o":["﴿إِنَّ أَكْرَمَكُمْ عِنْدَ اللهِ أَتْقاكُمْ﴾"],"b":["﴿إِنَّ أَكْرَمَكُمْ عِنْدَ اللهِ أَتْقاكُمْ﴾","أَتْقاكُمْ"],"tr":"en takvalı, daha muttaki","ttr":"Takvası daha çok olan, (Allah'tan) daha çok korkan ve çekinen; takva: Allah'tan korkmak ve çekinmektir.","otr":["Allah katında en değerliniz, takvaca en ileri olanınızdır."],"r":null,"s":2},
{"k":"أَتَى","c":"","m":"يَأْتي إِتْياناً: (١) جاءَ، خِلافُ ذَهَبَ، أَوْ رَجَعَ، “أَتى الطُّلّابُ مُبَكِّرينَ”، ﴿أَتى أَمْرُ اللهِ فَلا تَسْتَعْجِلُوهُ﴾. (٢) أَتى بِالشَّيْءِ: جاءَ بِهِ، أَحْضَرَهُ وجَلَبَهُ، “أَتى بِفِكْرَةٍ جَديدَةٍ”، ﴿فَأْتُوا بِسُورَةٍ مِنْ مِثْلِهِ﴾.","t":"(١) جاءَ، خِلافُ ذَهَبَ، أَوْ رَجَعَ. (٢) أَتى بِالشَّيْءِ: جاءَ بِهِ، أَحْضَرَهُ وجَلَبَهُ.","o":["أَتى الطُّلّابُ مُبَكِّرينَ","﴿أَتى أَمْرُ اللهِ فَلا تَسْتَعْجِلُوهُ﴾","أَتى بِفِكْرَةٍ جَديدَةٍ","﴿فَأْتُوا بِسُورَةٍ مِنْ مِثْلِهِ﴾"],"b":["أَتى الطُّلّابُ مُبَكِّرينَ","أَتى"],"tr":"gelmek","ttr":"(1) Geldi (gitmenin zıddı) ya da döndü. (2) Bir şeyi getirdi: onu getirdi, hazır etti.","otr":["Öğrenciler erkenden geldi.","Allah'ın emri geldi, artık onu acele istemeyin.","Yeni bir fikir getirdi (ortaya attı).","Onun benzeri bir sure getirin."],"r":"p02_6","s":2,"f":"يَأْتي إِتْياناً"},
{"k":"أَثابَ","c":"","m":"يُثيبُ إِثابَةً: كافَأَ وجازَى، ﴿فَأَثابَهُمُ اللهُ بِما قالُوا جَنّاتٍ تَجْري مِنْ تَحْتِها الأَنْهارُ﴾.","t":"كافَأَ وجازَى.","o":["﴿فَأَثابَهُمُ اللهُ بِما قالُوا جَنّاتٍ تَجْري مِنْ تَحْتِها الأَنْهارُ﴾"],"b":["﴿فَأَثابَهُمُ اللهُ بِما قالُوا جَنّاتٍ تَجْري مِنْ تَحْتِها الأَنْهارُ﴾","فَأَثابَهُمُ"],"tr":"mükâfatlandırmak","ttr":"Karşılığını verdi, ödüllendirdi.","otr":["Söyledikleri sözden dolayı Allah onları altından ırmaklar akan cennetlerle mükâfatlandırdı."],"r":null,"s":2,"f":"يُثيبُ إِثابَةً"},
{"k":"أَحْزَنَ","c":"","m":"يُحْزِنُ إِحْزاناً: أَغَمَّ، وجَعَلَهُ حَزيناً، “أَحْزَنَني نَبَأُ وَفاةِ صَديقي”، ﴿قالَ إِنّي لَيَحْزُنُني أَنْ تَذْهَبُوا بِهِ﴾.","t":"أَغَمَّ، وجَعَلَهُ حَزيناً","o":["أَحْزَنَني نَبَأُ وَفاةِ صَديقي","﴿قالَ إِنّي لَيَحْزُنُني أَنْ تَذْهَبُوا بِهِ﴾"],"b":["أَحْزَنَني نَبَأُ وَفاةِ صَديقي","أَحْزَنَني"],"tr":"üzmek, hüzünlendirmek","ttr":"Kederlendirdi, onu hüzünlü kıldı.","otr":["Arkadaşımın ölüm haberi beni üzdü.","(Yakup) dedi ki: Onu götürmeniz beni gerçekten üzer."],"r":null,"s":6,"f":"يُحْزِنُ إِحْزاناً"},
{"k":"أَحَسَّ","c":"","m":"يُحِسُّ إِحْساساً: (١) شَعَرَ، “أَحَسَّ بِقيمَةِ الوَقْتِ”. (٢) عَلِمَ، ﴿فَلَمّا أَحَسَّ عيسى مِنْهُمُ الْكُفْرَ﴾.","t":"(١) شَعَرَ. (٢) عَلِمَ.","o":["أَحَسَّ بِقيمَةِ الوَقْتِ","﴿فَلَمّا أَحَسَّ عيسى مِنْهُمُ الْكُفْرَ﴾"],"b":["أَحَسَّ بِقيمَةِ الوَقْتِ","أَحَسَّ"],"tr":"hissetmek, sezmek","ttr":"(1) Hissetti. (2) Bildi, farkına vardı.","otr":["Zamanın değerini hissetti.","İsa onlardan inkârı sezince..."],"r":null,"s":6,"f":"يُحِسُّ إِحْساساً"},
{"k":"إِحْسان","c":"","m":"مَصْدَرُ أَحْسَنَ: فِعْلُ ما هُوَ خَيْرٌ لِلآخَرينَ فَضْلاً، خِلافُ الإِساءَةِ، ﴿هَلْ جَزاءُ الإِحْسانِ إِلّا الإِحْسانُ﴾.","t":"مَصْدَرُ أَحْسَنَ: فِعْلُ ما هُوَ خَيْرٌ لِلآخَرينَ فَضْلاً، خِلافُ الإِساءَةِ","o":["﴿هَلْ جَزاءُ الإِحْسانِ إِلّا الإِحْسانُ﴾"],"b":["هَلْ جَزاءُ الإِحْسانِ إِلّا الإِحْسانُ","الإِحْسانِ"],"tr":"iyilik, ihsan","ttr":"Ahsene fiilinin mastarı: başkalarına karşılıksız olarak iyi olanı yapmak; kötülüğün zıddı.","otr":["İyiliğin karşılığı ancak iyilik değil midir?"],"r":"p06_1","s":6},
{"k":"أَحْسَنَ","c":"","m":"يُحْسِنُ إِحْساناً: (١) قامَ بِعَمَلٍ حَسَنٍ ﴿وَأَحْسِنْ كَما أَحْسَنَ اللَّهُ إِلَيْكَ﴾. (٢) أَتْقَنَ وأَجادَ، وفي الحَديثِ: (أَدَّبَني رَبّي فَأَحْسَنَ تَأْديبي).","t":"(١) قامَ بِعَمَلٍ حَسَنٍ. (٢) أَتْقَنَ وأَجادَ.","o":["﴿وَأَحْسِنْ كَما أَحْسَنَ اللَّهُ إِلَيْكَ﴾","أَدَّبَني رَبّي فَأَحْسَنَ تَأْديبي"],"b":["وَأَحْسِنْ كَما أَحْسَنَ اللَّهُ إِلَيْكَ","أَحْسَنَ"],"tr":"iyilik yapmak; iyi yapmak","ttr":"(1) Güzel bir iş yaptı. (2) Sağlam ve güzel yaptı.","otr":["Allah sana iyilik ettiği gibi sen de iyilik et.","Hadiste: Rabbim beni terbiye etti ve terbiyemi en güzel şekilde yaptı."],"r":null,"s":6,"f":"يُحْسِنُ إِحْساناً"},
{"k":"أَحْشَمَ","c":"","m":"يُحْشِمُ إِحْشاماً: (١) أَخْجَلَ، “مَدَحَهُ أَمامَ النّاسِ فَأَحْشَمَهُ”. (٢) أَغْضَبَ، “أَحْشَمَهُ وآذاهُ فَضَرَبَهُ”.","t":"(١) أَخْجَلَ. (٢) أَغْضَبَ.","o":["مَدَحَهُ أَمامَ النّاسِ فَأَحْشَمَهُ","أَحْشَمَهُ وآذاهُ فَضَرَبَهُ"],"b":["مَدَحَهُ أَمامَ النّاسِ فَأَحْشَمَهُ","فَأَحْشَمَهُ"],"tr":"utandırmak; kızdırmak","ttr":"(1) Utandırdı. (2) Kızdırdı.","otr":["Onu insanların önünde övdü ve utandırdı.","Onu kızdırdı ve ona eziyet etti, o da onu dövdü."],"r":null,"s":6,"f":"يُحْشِمُ إِحْشاماً"},
{"k":"أَحْصى","c":"","m":"يُحْصي إِحْصاءً: عَدَّ وأَحاطَ، ﴿لَقَدْ أَحْصاهُمْ وَعَدَّهُمْ عَدّاً﴾.","t":"عَدَّ وأَحاطَ","o":["﴿لَقَدْ أَحْصاهُمْ وَعَدَّهُمْ عَدّاً﴾"],"b":["لَقَدْ أَحْصاهُمْ وَعَدَّهُمْ عَدّاً","أَحْصاهُمْ"],"tr":"saymak, sayıp kuşatmak","ttr":"Saydı ve tamamını kuşattı.","otr":["Andolsun ki O, onları kuşatmış ve tek tek saymıştır."],"r":null,"s":6,"y":[["مصدر","إِحْصاء"]],"f":"يُحْصي إِحْصاءً"},
{"k":"أَحْضَرَ","c":"","m":"يُحْضِرُ إِحْضاراً: أَتى بِالشَّيْءِ، “أَحْضَرَ الرَّجُلُ السَّجّادَةَ”.","t":"أَتى بِالشَّيْءِ","o":["أَحْضَرَ الرَّجُلُ السَّجّادَةَ"],"b":["أَحْضَرَ الرَّجُلُ السَّجّادَةَ","أَحْضَرَ"],"tr":"getirmek, hazır etmek","ttr":"Bir şeyi getirdi.","otr":["Adam seccadeyi getirdi."],"r":null,"s":6,"f":"يُحْضِرُ إِحْضاراً"},
{"k":"أَحَقُّ","c":"","m":"أَكْثَرُ أَحَقِّيَةً، أَوْجَبُ، أَوْلى، ﴿وَتَخْشى النّاسَ وَاللَّهُ أَحَقُّ أَنْ تَخْشاهُ﴾.","t":"أَكْثَرُ أَحَقِّيَةً، أَوْجَبُ، أَوْلى","o":["﴿وَتَخْشى النّاسَ وَاللَّهُ أَحَقُّ أَنْ تَخْشاهُ﴾"],"b":["وَتَخْشى النّاسَ وَاللَّهُ أَحَقُّ أَنْ تَخْشاهُ","أَحَقُّ"],"tr":"daha layık, daha haklı","ttr":"Hak etmeye daha çok layık, daha gerekli, daha uygun.","otr":["İnsanlardan korkuyorsun; oysa Allah, kendisinden korkmana daha layıktır."],"r":null,"s":6},
{"k":"أَحْكَمَ","c":"","m":"يُحْكِمُ إِحْكاماً؛ أَحْكَمَ الشَّيْءَ: أَتْقَنَهُ وَضَبَطَهُ، “تَأَكَّدْ مِنْ إِحْكامِ إِغْلاقِ البابِ”.","t":"أَحْكَمَ الشَّيْءَ: أَتْقَنَهُ وَضَبَطَهُ","o":["تَأَكَّدْ مِنْ إِحْكامِ إِغْلاقِ البابِ"],"b":["تَأَكَّدْ مِنْ إِحْكامِ إِغْلاقِ البابِ","إِحْكامِ"],"tr":"sağlamlaştırmak","ttr":"Bir şeyi sağlam ve düzgün yaptı, sıkıca ayarladı.","otr":["Kapının sıkıca kapandığından emin ol."],"r":null,"s":6,"y":[["مصدر","إِحْكام"]],"f":"يُحْكِمُ إِحْكاماً"},
{"k":"أَحَلَّ","c":"","m":"(١) يُحِلُّ إِحْلالاً؛ أَحَلَّ بِالمَكانِ: أَنْزَلَ فيهِ، ﴿الَّذي أَحَلَّنا دارَ الْمُقامَةِ﴾. (٢) أَحَلَّ يُحِلُّ تَحْليلاً: أَباحَ؛ خِلافُ حَرَّمَ، ﴿وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبا﴾. (٣) أَحَلَّ مِنْ إِحْرامِهِ: خَرَجَ مِنْهُ.","t":"(١) أَحَلَّ بِالمَكانِ: أَنْزَلَ فيهِ. (٢) أَباحَ؛ خِلافُ حَرَّمَ. (٣) أَحَلَّ مِنْ إِحْرامِهِ: خَرَجَ مِنْهُ.","o":["﴿الَّذي أَحَلَّنا دارَ الْمُقامَةِ﴾","﴿وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبا﴾"],"b":["وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبا","وَأَحَلَّ"],"tr":"yerleştirmek; helal kılmak","ttr":"(1) Bir yere yerleştirdi, indirdi. (2) Mubah kıldı; haram kılmanın zıddı. (3) İhramdan çıktı.","otr":["Bizi (lütfuyla) kalınacak yurda yerleştiren O'dur.","Allah alışverişi helal, faizi haram kılmıştır."],"r":null,"s":6},
{"k":"أَحْلى","c":"","m":"أَكْثَرُ حَلاوَةً: خِلافُ أَمَرَّ، “العَسَلُ أَحْلى مِنَ المَوْزِ”.","t":"أَكْثَرُ حَلاوَةً: خِلافُ أَمَرَّ","o":["العَسَلُ أَحْلى مِنَ المَوْزِ"],"b":["العَسَلُ أَحْلى مِنَ المَوْزِ","أَحْلى"],"tr":"daha tatlı","ttr":"Daha tatlı; daha acının zıddı.","otr":["Bal muzdan daha tatlıdır."],"r":null,"s":6},
{"k":"أَحْمَر","c":"","m":"(مُؤ) حَمْراء: الأَحْمَرُ ما كانَ لَوْنُهُ كَلَوْنِ الدَّمِ.","t":"الأَحْمَرُ ما كانَ لَوْنُهُ كَلَوْنِ الدَّمِ","o":[],"b":null,"tr":"kırmızı","ttr":"(Müennesi: hamrâ) Kırmızı, rengi kan rengi gibi olan şeydir.","otr":[],"r":"p06_2","s":6},
{"k":"أَحْمَق","c":"حَمْقى","m":"(ج) حَمْقى؛ قَليلُ العَقْلِ، “اِنْدَفَعَ كَالأَحْمَقِ يُحَطِّمُ كُلَّ ما حَوْلَهُ”.","t":"قَليلُ العَقْلِ","o":["اِنْدَفَعَ كَالأَحْمَقِ يُحَطِّمُ كُلَّ ما حَوْلَهُ"],"b":["اِنْدَفَعَ كَالأَحْمَقِ يُحَطِّمُ كُلَّ ما حَوْلَهُ","كَالأَحْمَقِ"],"tr":"ahmak, akılsız","ttr":"Aklı az olan.","otr":["Bir ahmak gibi atılıp etrafındaki her şeyi kırdı."],"r":null,"s":6},
{"k":"أَحْمى","c":"","m":"يُحْمي إِحْماءً: سَخَّنَ، زادَ حَرارَتَهُ، “أَحْمى الحَدّادُ الحَديدَ في النّارِ”، ﴿يَوْمَ يُحْمى عَلَيْها في نارِ جَهَنَّمَ﴾.","t":"سَخَّنَ، زادَ حَرارَتَهُ","o":["أَحْمى الحَدّادُ الحَديدَ في النّارِ","﴿يَوْمَ يُحْمى عَلَيْها في نارِ جَهَنَّمَ﴾"],"b":["أَحْمى الحَدّادُ الحَديدَ في النّارِ","أَحْمى"],"tr":"kızdırmak, ısıtmak","ttr":"Isıttı, sıcaklığını artırdı.","otr":["Demirci demiri ateşte kızdırdı.","O gün bunlar cehennem ateşinde kızdırılır."],"r":"p06_3","s":6,"f":"يُحْمي إِحْماءً"},
{"k":"أَحْيا","c":"","m":"يُحْيي إِحْياءً: (١) أَخْرَجَ النَّباتَ، ﴿فَأَحْيَيْنا بِهِ الأَرْضَ بَعْدَ مَوْتِها﴾. (٢) جَعَلَهُ حَيّاً، ﴿لا إِلٰهَ إِلّا هُوَ يُحْيي وَيُميتُ﴾.","t":"(١) أَخْرَجَ النَّباتَ. (٢) جَعَلَهُ حَيّاً.","o":["﴿فَأَحْيَيْنا بِهِ الأَرْضَ بَعْدَ مَوْتِها﴾","﴿لا إِلٰهَ إِلّا هُوَ يُحْيي وَيُميتُ﴾"],"b":["لا إِلٰهَ إِلّا هُوَ يُحْيي وَيُميتُ","يُحْيي"],"tr":"diriltmek, canlandırmak","ttr":"(1) Bitkiyi çıkardı. (2) Onu diri kıldı.","otr":["Onunla toprağı ölümünden sonra dirilttik.","O'ndan başka ilah yoktur; diriltir ve öldürür."],"r":null,"s":6,"f":"يُحْيي إِحْياءً"},
{"k":"أَخ","c":"إِخْوان، إِخْوَة","m":"(ج) إِخْوان وإِخْوَة، (مُؤ) أُخْت: ابْنُ الأُمِّ وَالأَبِ أَوْ أَحَدِهِما.","t":"ابْنُ الأُمِّ وَالأَبِ أَوْ أَحَدِهِما","o":[],"b":null,"tr":"erkek kardeş","ttr":"Anne ve babanın ya da bunlardan birinin oğlu.","otr":[],"r":null,"s":6,"y":[["مذكر","أُخْت"],["جمع","إِخْوان"],["جمع","إِخْوَة"]]},
{"k":"إِخاء","c":"","m":"مَصْدَرُ آخى: المَوَدَّةُ وَالصَّداقَةُ، “كانَتْ بَيْنَهُما عَلاقَةُ إِخاءٍ قَوِيَّةٌ”.","t":"مَصْدَرُ آخى: المَوَدَّةُ وَالصَّداقَةُ","o":["كانَتْ بَيْنَهُما عَلاقَةُ إِخاءٍ قَوِيَّةٌ"],"b":["كانَتْ بَيْنَهُما عَلاقَةُ إِخاءٍ قَوِيَّةٌ","إِخاءٍ"],"tr":"kardeşlik","ttr":"Âhâ fiilinin mastarı: sevgi ve dostluk.","otr":["Aralarında güçlü bir kardeşlik bağı vardı."],"r":null,"s":6},
{"k":"أَخافَ","c":"","m":"يُخيفُ إِخافَةً؛ أَخافَ الأَسَدُ الصَّيّادَ: جَعَلَهُ يَخافُ، أَوْ أَشْعَرَ الشَّخْصَ بِنَوْعٍ مِنَ الاضْطِرابِ، “قَصَصُ الجِنِّ وَالشَّياطينِ أَخافَتِ الصِّغارَ”.","t":"جَعَلَهُ يَخافُ، أَوْ أَشْعَرَ الشَّخْصَ بِنَوْعٍ مِنَ الاضْطِرابِ","o":["أَخافَ الأَسَدُ الصَّيّادَ","قَصَصُ الجِنِّ وَالشَّياطينِ أَخافَتِ الصِّغارَ"],"b":["قَصَصُ الجِنِّ وَالشَّياطينِ أَخافَتِ الصِّغارَ","أَخافَتِ"],"tr":"korkutmak","ttr":"Onu korkuttu ya da kişide bir tür tedirginlik uyandırdı.","otr":["Aslan avcıyı korkuttu.","Cin ve şeytan hikâyeleri küçükleri korkuttu."],"r":null,"s":7,"f":"يُخيفُ إِخافَةً"},
{"k":"أَخْبَرَ","c":"","m":"يُخْبِرُ إِخْباراً: أَعْلَمَ وَعَرَّفَ، “أَخْبَرْتُهُ بِما حَدَثَ مِنْ مُشْكِلاتٍ”.","t":"أَعْلَمَ وَعَرَّفَ","o":["أَخْبَرْتُهُ بِما حَدَثَ مِنْ مُشْكِلاتٍ"],"b":["أَخْبَرْتُهُ بِما حَدَثَ مِنْ مُشْكِلاتٍ","أَخْبَرْتُهُ"],"tr":"haber vermek, bildirmek","ttr":"Bildirdi ve tanıttı.","otr":["Ona olan sorunları haber verdim."],"r":null,"s":7,"f":"يُخْبِرُ إِخْباراً"},
{"k":"أُخْدود","c":"أَخاديد","m":"(ج) أَخاديد؛ شَقٌّ عَميقٌ مُسْتَطيلٌ في الأَرْضِ، ﴿قُتِلَ أَصْحابُ الأُخْدودِ﴾.","t":"شَقٌّ عَميقٌ مُسْتَطيلٌ في الأَرْضِ","o":["﴿قُتِلَ أَصْحابُ الأُخْدودِ﴾"],"b":["قُتِلَ أَصْحابُ الأُخْدودِ","الأُخْدودِ"],"tr":"hendek, derin yarık","ttr":"Yerde uzunlamasına derin yarık.","otr":["Hendek sahipleri kahrolsun!"],"r":"p07_1","s":7,"y":[["جمع","أَخاديد"]]},
{"k":"آخِذٌ","c":"","m":"(١) مُسْتَمِرٌّ، “الأَسْعارُ آخِذَةٌ في الارْتِفاعِ”. (٢) لائِمٌ أَوْ عاتِبٌ، “قالَ المُعَلِّمُ لِتِلْميذِهِ: أَنا آخِذٌ عَلَيْكَ كَثْرَةَ الغِيابِ”.","t":"(١) مُسْتَمِرٌّ. (٢) لائِمٌ أَوْ عاتِبٌ.","o":["الأَسْعارُ آخِذَةٌ في الارْتِفاعِ","قالَ المُعَلِّمُ لِتِلْميذِهِ: أَنا آخِذٌ عَلَيْكَ كَثْرَةَ الغِيابِ"],"b":["الأَسْعارُ آخِذَةٌ في الارْتِفاعِ","آخِذَةٌ"],"tr":"sürmekte olan; kınayan","ttr":"(1) Devam eden, süren. (2) Kınayan ya da sitem eden.","otr":["Fiyatlar yükselmeye devam ediyor.","Öğretmen öğrencisine dedi ki: Çok devamsızlık yapmanı sana kusur sayıyorum."],"r":null,"s":7},
{"k":"أَخَذَ","c":"","m":"يَأْخُذُ أَخْذاً: (١) حَصَلَ عَلى، وَقَبَضَ وَتَناوَلَ، ﴿خُذِ الْكِتابَ بِقُوَّةٍ﴾. (٢) تَلَقّى، “أَخَذَ عَنْهُ العِلْمَ، وَأَخَذَ عَنْ أَبيهِ عِلْمَ التَّفْسيرِ...”.","t":"(١) حَصَلَ عَلى، وَقَبَضَ وَتَناوَلَ. (٢) تَلَقّى.","o":["﴿خُذِ الْكِتابَ بِقُوَّةٍ﴾","أَخَذَ عَنْهُ العِلْمَ، وَأَخَذَ عَنْ أَبيهِ عِلْمَ التَّفْسيرِ..."],"b":["أَخَذَ عَنْ أَبيهِ عِلْمَ التَّفْسيرِ","أَخَذَ"],"tr":"almak","ttr":"(1) Elde etti, tuttu, aldı. (2) (İlmi birinden) aldı, öğrendi.","otr":["Kitaba sıkıca sarıl.","İlmi ondan aldı; tefsir ilmini babasından öğrendi..."],"r":"p07_2","s":7,"f":"يَأْخُذُ أَخْذاً"},
{"k":"آخِر","c":"","m":"(١) خِلافُ الأَوَّلِ رُتْبَةً أَوْ زَمَناً، “كانَ يَجْلِسُ في آخِرِ الصَّفِّ”. (٢) حَديثٌ أَوْ أَحْدَثُ، “هٰذا آخِرُ إِصْدارٍ مِنَ المَجَلَّةِ”. (٣) اليَوْمُ الآخِرُ: يَوْمُ القِيامَةِ.","t":"(١) خِلافُ الأَوَّلِ رُتْبَةً أَوْ زَمَناً. (٢) حَديثٌ أَوْ أَحْدَثُ. (٣) اليَوْمُ الآخِرُ: يَوْمُ القِيامَةِ.","o":["كانَ يَجْلِسُ في آخِرِ الصَّفِّ","هٰذا آخِرُ إِصْدارٍ مِنَ المَجَلَّةِ"],"b":["كانَ يَجْلِسُ في آخِرِ الصَّفِّ","آخِرِ"],"tr":"son, sonuncu","ttr":"(1) Sıra ya da zaman bakımından birincinin zıddı. (2) Yeni ya da en yeni. (3) Ahiret günü: kıyamet günü.","otr":["Sıranın en sonunda otururdu.","Bu, derginin en son sayısıdır."],"r":"p07_3","s":7,"y":[["مذكر","أُخْرى"]]},
{"k":"آخَر","c":"","m":"(مُؤ) أُخْرى: (١) أَحَدُ شَيْئَيْنِ، “أَراكَ في وَقْتٍ آخَرَ”، ﴿فَلا تَدْعُ مَعَ اللَّهِ إِلٰهاً آخَرَ﴾، ﴿وَأَمّا الآخَرُ فَيُصْلَبُ﴾.","t":"أَحَدُ شَيْئَيْنِ","o":["أَراكَ في وَقْتٍ آخَرَ","﴿فَلا تَدْعُ مَعَ اللَّهِ إِلٰهاً آخَرَ﴾","﴿وَأَمّا الآخَرُ فَيُصْلَبُ﴾"],"b":["أَراكَ في وَقْتٍ آخَرَ","آخَرَ"],"tr":"diğer, başka","ttr":"(Müennesi: uhrâ) İki şeyden biri, öteki.","otr":["Seni başka bir zaman görürüm.","Allah ile beraber başka bir ilaha yalvarma.","Diğerine gelince, o asılır."],"r":null,"s":7},
{"k":"أَخَّرَ","c":"","m":"يُؤَخِّرُ تَأْخيراً؛ أَخَّرَ الشَّيْءَ: أَبْطَأَ بِهِ عَنْ وَقْتِهِ، خِلافُ قَدَّمَ، ﴿يُنَبَّأُ الإِنْسانُ يَوْمَئِذٍ بِما قَدَّمَ وَأَخَّرَ﴾.","t":"أَخَّرَ الشَّيْءَ: أَبْطَأَ بِهِ عَنْ وَقْتِهِ، خِلافُ قَدَّمَ","o":["﴿يُنَبَّأُ الإِنْسانُ يَوْمَئِذٍ بِما قَدَّمَ وَأَخَّرَ﴾"],"b":["يُنَبَّأُ الإِنْسانُ يَوْمَئِذٍ بِما قَدَّمَ وَأَخَّرَ","وَأَخَّرَ"],"tr":"ertelemek, geciktirmek","ttr":"Bir şeyi vaktinden geciktirdi; öne almanın zıddı.","otr":["O gün insana, önden gönderdiği ve geri bıraktığı şeyler haber verilir."],"r":null,"s":7,"f":"يُؤَخِّرُ تَأْخيراً"},
{"k":"أَخْرَجَ","c":"","m":"يُخْرِجُ إِخْراجاً: (١) أَظْهَرَ وَأَبْرَزَ؛ خِلافُ أَدْخَلَ، “أَخْرَجَ الأَوْراقَ مِنَ الحَقيبَةِ”. ﴿إِذا أَخْرَجَ يَدَهُ لَمْ يَكَدْ يَراها﴾. (٢) أَخْرَجَ: طَرَدَ بِالقُوَّةِ، “أَخْرَجَ المُجاهِدونَ الأَعْداءَ مِنَ البِلادِ”، ﴿وَأَخْرِجُوهُمْ مِنْ حَيْثُ أَخْرَجُوكُمْ﴾.","t":"(١) أَظْهَرَ وَأَبْرَزَ؛ خِلافُ أَدْخَلَ. (٢) طَرَدَ بِالقُوَّةِ.","o":["أَخْرَجَ الأَوْراقَ مِنَ الحَقيبَةِ","﴿إِذا أَخْرَجَ يَدَهُ لَمْ يَكَدْ يَراها﴾","أَخْرَجَ المُجاهِدونَ الأَعْداءَ مِنَ البِلادِ","﴿وَأَخْرِجُوهُمْ مِنْ حَيْثُ أَخْرَجُوكُمْ﴾"],"b":["أَخْرَجَ الأَوْراقَ مِنَ الحَقيبَةِ","أَخْرَجَ"],"tr":"çıkarmak","ttr":"(1) Ortaya çıkardı, gösterdi; içeri sokmanın zıddı. (2) Zorla kovdu.","otr":["Kâğıtları çantadan çıkardı.","Elini çıkardığında neredeyse onu göremez.","Mücahitler düşmanları ülkeden çıkardı.","Sizi çıkardıkları yerden siz de onları çıkarın."],"r":"p07_4","s":7,"y":[["مصدر","إِخْراج"]],"f":"يُخْرِجُ إِخْراجاً"},
{"k":"آخِرَة","c":"","m":"الآخِرَةُ: الحَياةُ بَعْدَ المَوْتِ، ﴿وَلَلْآخِرَةُ خَيْرٌ لَكَ مِنَ الأُولى﴾.","t":"الحَياةُ بَعْدَ المَوْتِ","o":["﴿وَلَلْآخِرَةُ خَيْرٌ لَكَ مِنَ الأُولى﴾"],"b":["وَلَلْآخِرَةُ خَيْرٌ لَكَ مِنَ الأُولى","وَلَلْآخِرَةُ"],"tr":"ahiret","ttr":"Ölümden sonraki hayat.","otr":["Ahiret senin için dünyadan daha hayırlıdır."],"r":null,"s":7},
{"k":"أَخْرَس","c":"خُرْس","m":"(ج) خُرْس، (مُؤ) خَرْساء: الشَّخْصُ الَّذي لا يَسْتَطيعُ الكَلامَ خِلْقَةً (أَبْكَم)، “الأُمُّ خَرْساءُ، وَالبِنْتُ فَصيحَةٌ”.","t":"الشَّخْصُ الَّذي لا يَسْتَطيعُ الكَلامَ خِلْقَةً (أَبْكَم)","o":["الأُمُّ خَرْساءُ، وَالبِنْتُ فَصيحَةٌ"],"b":["الأُمُّ خَرْساءُ، وَالبِنْتُ فَصيحَةٌ","خَرْساءُ"],"tr":"dilsiz","ttr":"Doğuştan konuşamayan kişi (dilsiz).","otr":["Anne dilsiz, kızı ise dili düzgün (fasih)."],"r":null,"s":7},
{"k":"أَخْضَر","c":"خُضْر","m":"(مُؤ) خَضْراء، (ج) خُضْر: لَوْنٌ كَلَوْنِ أَوْراقِ الشَّجَرِ وَالحَشائِشِ، ﴿الَّذي جَعَلَ لَكُمْ مِنَ الشَّجَرِ الأَخْضَرِ ناراً فَإِذا أَنْتُمْ مِنْهُ توقِدونَ﴾.","t":"لَوْنٌ كَلَوْنِ أَوْراقِ الشَّجَرِ وَالحَشائِشِ","o":["﴿الَّذي جَعَلَ لَكُمْ مِنَ الشَّجَرِ الأَخْضَرِ ناراً فَإِذا أَنْتُمْ مِنْهُ توقِدونَ﴾"],"b":["الَّذي جَعَلَ لَكُمْ مِنَ الشَّجَرِ الأَخْضَرِ ناراً","الأَخْضَرِ"],"tr":"yeşil","ttr":"Ağaç yaprakları ve otların rengi gibi bir renk.","otr":["O, size yeşil ağaçtan ateş çıkarandır; siz de ondan (ateş) yakarsınız."],"r":"p07_5","s":7},
{"k":"أَخْطَأَ","c":"","m":"يُخْطِئُ خَطَأً؛ لَمْ يُصِبْ، تَجاوَزَ، “أَخْطَأَ التَّقْديرَ”، (ما أَخْطَأَكَ لَمْ يَكُنْ لِيُصيبَكَ، وَما أَصابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ).","t":"لَمْ يُصِبْ، تَجاوَزَ","o":["أَخْطَأَ التَّقْديرَ","ما أَخْطَأَكَ لَمْ يَكُنْ لِيُصيبَكَ، وَما أَصابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ"],"b":["أَخْطَأَ التَّقْديرَ","أَخْطَأَ"],"tr":"hata etmek, yanılmak","ttr":"İsabet etmedi, isabet ettiremedi; aştı.","otr":["Tahminde yanıldı.","Sana isabet etmeyen şey zaten sana isabet edecek değildi; sana isabet eden de seni ıskalayacak değildi."],"r":"p07_6","s":7,"f":"يُخْطِئُ خَطَأً"},
{"k":"أَخْفى","c":"","m":"يُخْفي إِخْفاءً؛ أَخْفى الشَّيْءَ: سَتَرَهُ وَخَبَّأَهُ، حَتّى لا يَراهُ أَحَدٌ، (وَرَجُلٌ تَصَدَّقَ بِصَدَقَةٍ فَأَخْفاها؛ حَتّى لا تَعْلَمَ شِمالُهُ ما تُنْفِقُ يَمينُهُ).","t":"أَخْفى الشَّيْءَ: سَتَرَهُ وَخَبَّأَهُ، حَتّى لا يَراهُ أَحَدٌ","o":["وَرَجُلٌ تَصَدَّقَ بِصَدَقَةٍ فَأَخْفاها؛ حَتّى لا تَعْلَمَ شِمالُهُ ما تُنْفِقُ يَمينُهُ"],"b":["وَرَجُلٌ تَصَدَّقَ بِصَدَقَةٍ فَأَخْفاها","فَأَخْفاها"],"tr":"gizlemek, saklamak","ttr":"Bir şeyi kimse görmesin diye örttü ve sakladı.","otr":["Ve bir sadaka verip onu, sağ elinin verdiğini sol eli bilmeyecek kadar gizleyen adam (hadis)."],"r":null,"s":7,"y":[["مصدر","إِخْفاء"]],"f":"يُخْفي إِخْفاءً"},
{"k":"أَخَلَّ","c":"","m":"يُخِلُّ إِخْلالاً؛ بِالشَّيْءِ: لَمْ يَقُمْ بِهِ عَلى الوَجْهِ الصَّحيحِ، وَقَصَّرَ فيهِ، “أَخَلَّ بِعَمَلِهِ”.","t":"أَخَلَّ بِالشَّيْءِ: لَمْ يَقُمْ بِهِ عَلى الوَجْهِ الصَّحيحِ، وَقَصَّرَ فيهِ","o":["أَخَلَّ بِعَمَلِهِ"],"b":["أَخَلَّ بِعَمَلِهِ","أَخَلَّ"],"tr":"ihlal etmek, aksatmak","ttr":"Bir işi gereği gibi yapmadı ve onda kusur etti.","otr":["İşini aksattı."],"r":null,"s":7,"f":"يُخِلُّ إِخْلالاً"},
{"k":"إِخْلاص","c":"","m":"مَصْدَرُ أَخْلَصَ: (١) الوَفاءُ وَالأَمانَةُ، “أَدّى عَمَلَهُ بِإِخْلاصٍ”. (٢) سورَةُ الإِخْلاصِ: ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾. (٣) كَلِمَةُ الإِخْلاصِ: كَلِمَةُ التَّوْحيدِ، (لا إِلٰهَ إِلّا اللهُ، مُحَمَّدٌ رَسولُ اللهِ).","t":"مَصْدَرُ أَخْلَصَ: (١) الوَفاءُ وَالأَمانَةُ. (٢) سورَةُ الإِخْلاصِ. (٣) كَلِمَةُ الإِخْلاصِ: كَلِمَةُ التَّوْحيدِ.","o":["أَدّى عَمَلَهُ بِإِخْلاصٍ","﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾","لا إِلٰهَ إِلّا اللهُ، مُحَمَّدٌ رَسولُ اللهِ"],"b":["أَدّى عَمَلَهُ بِإِخْلاصٍ","بِإِخْلاصٍ"],"tr":"samimiyet, ihlas","ttr":"Ahlasa fiilinin mastarı: (1) Vefa ve güvenilirlik. (2) İhlas suresi. (3) İhlas kelimesi: tevhid kelimesi.","otr":["İşini ihlasla (içtenlikle) yaptı.","De ki: O Allah birdir.","Allah'tan başka ilah yoktur, Muhammed Allah'ın elçisidir."],"r":null,"s":8},
{"k":"أُخُوَّة","c":"","m":"(١) الرّابِطَةُ بَيْنَ الأَخِ وَأَخيهِ، “لَمْ يُراعِ قابيلُ الأُخُوَّةَ الَّتي تَرْبِطُهُ بِهابيلَ”. (٢) العَلاقَةُ المَبْنِيَّةُ عَلى المَوَدَّةِ وَالحُبِّ وَالتَّعاوُنِ، “تَجْمَعُ بَيْنَ المُسْلِمينَ عَلى اخْتِلافِ أَوْطانِهِمْ أُخُوَّةُ الدّينِ”.","t":"(١) الرّابِطَةُ بَيْنَ الأَخِ وَأَخيهِ. (٢) العَلاقَةُ المَبْنِيَّةُ عَلى المَوَدَّةِ وَالحُبِّ وَالتَّعاوُنِ.","o":["لَمْ يُراعِ قابيلُ الأُخُوَّةَ الَّتي تَرْبِطُهُ بِهابيلَ","تَجْمَعُ بَيْنَ المُسْلِمينَ عَلى اخْتِلافِ أَوْطانِهِمْ أُخُوَّةُ الدّينِ"],"b":["تَجْمَعُ بَيْنَ المُسْلِمينَ عَلى اخْتِلافِ أَوْطانِهِمْ أُخُوَّةُ الدّينِ","أُخُوَّةُ"],"tr":"kardeşlik","ttr":"(1) Kardeş ile kardeşi arasındaki bağ. (2) Sevgi, muhabbet ve yardımlaşmaya dayanan ilişki.","otr":["Kabil, onu Habil'e bağlayan kardeşliği gözetmedi.","Vatanları farklı olsa da Müslümanları din kardeşliği bir araya getirir."],"r":null,"s":8},
{"k":"آخى","c":"","m":"يُؤاخي مُؤاخاةً؛ آخى بَيْنَ اثْنَيْنِ: جَعَلَهُما كَالأَخَوَيْنِ، “آخى الرَّسولُ بَيْنَ المُهاجِرينَ وَالأَنْصارِ”.","t":"آخى بَيْنَ اثْنَيْنِ: جَعَلَهُما كَالأَخَوَيْنِ","o":["آخى الرَّسولُ بَيْنَ المُهاجِرينَ وَالأَنْصارِ"],"b":["آخى الرَّسولُ بَيْنَ المُهاجِرينَ وَالأَنْصارِ","آخى"],"tr":"kardeş yapmak","ttr":"İki kişiyi kardeş gibi kıldı.","otr":["Peygamber, Muhacirlerle Ensar'ı kardeş yaptı."],"r":null,"s":8,"f":"يُؤاخي مُؤاخاةً"},
{"k":"أَخير","c":"","m":"خِلافُ الأَوَّلِ، وَأَخيراً: (١) في النِّهايَةِ أَوْ في الخِتامِ، “بَعْدَ وُصولِ جَميعِ الطُّلّابِ جاءَ مُحَمَّدٌ أَخيراً”. (٢) حَديثاً، “صَدَرَتْ طَبْعَةٌ أَخيراً مِنَ الكِتابِ”.","t":"خِلافُ الأَوَّلِ؛ وَأَخيراً: (١) في النِّهايَةِ أَوْ في الخِتامِ. (٢) حَديثاً.","o":["بَعْدَ وُصولِ جَميعِ الطُّلّابِ جاءَ مُحَمَّدٌ أَخيراً","صَدَرَتْ طَبْعَةٌ أَخيراً مِنَ الكِتابِ"],"b":["بَعْدَ وُصولِ جَميعِ الطُّلّابِ جاءَ مُحَمَّدٌ أَخيراً","أَخيراً"],"tr":"son; sonunda","ttr":"Birincinin zıddı. Ahîran: (1) Sonunda, en son. (2) Son zamanlarda, yakın zamanda.","otr":["Bütün öğrenciler geldikten sonra Muhammed en son geldi.","Kitabın yeni bir baskısı yakın zamanda çıktı."],"r":"p08_1","s":8},
{"k":"أَداة","c":"أَدَوات","m":"(ج) أَدَوات: (١) آلَةٌ يُسْتَعانُ بِها في عَمَلِ شَيْءٍ ما، “القَلَمُ أَداةٌ مِنْ أَدَواتِ الكِتابَةِ”. (٢) أَدَواتٌ مَنْزِلِيَّةٌ: ما يَكونُ في البَيْتِ مِنْ آلاتٍ وَأَجْهِزَةٍ، مِثْل: الثَّلّاجَة وَالمِكْنَسَة وَالفُرْن ...إلخ. (٣) الأَدَواتُ النَّحْوِيَّةُ: كَلِماتٌ تُؤَدّي وَظيفَةً نَحْوِيَّةً مُعَيَّنَةً، أَوْ تُسْتَعْمَلُ لِلرَّبْطِ بَيْنَ الكَلامِ، مِثْل: (ال) أَداة التَّعْريف، (لا) أَداة لِلنَّفْي.","t":"(١) آلَةٌ يُسْتَعانُ بِها في عَمَلِ شَيْءٍ ما. (٢) أَدَواتٌ مَنْزِلِيَّةٌ: ما يَكونُ في البَيْتِ مِنْ آلاتٍ وَأَجْهِزَةٍ. (٣) الأَدَواتُ النَّحْوِيَّةُ: كَلِماتٌ تُؤَدّي وَظيفَةً نَحْوِيَّةً مُعَيَّنَةً، أَوْ تُسْتَعْمَلُ لِلرَّبْطِ بَيْنَ الكَلامِ.","o":["القَلَمُ أَداةٌ مِنْ أَدَواتِ الكِتابَةِ","الثَّلّاجَة وَالمِكْنَسَة وَالفُرْن","(ال) أَداة التَّعْريف، (لا) أَداة لِلنَّفْي"],"b":["القَلَمُ أَداةٌ مِنْ أَدَواتِ الكِتابَةِ","أَداةٌ"],"tr":"alet, araç; edat","ttr":"(1) Bir işi yaparken yardım alınan alet. (2) Ev eşyaları: evde bulunan alet ve cihazlar. (3) Dilbilgisi edatları: belirli bir dilbilgisi işlevi gören ya da sözü birbirine bağlamak için kullanılan kelimeler.","otr":["Kalem, yazı araçlarından biridir.","Buzdolabı, süpürge, fırın vb.","(el) belirlilik edatı, (lâ) olumsuzluk edatı."],"r":null,"s":8},
{"k":"أَدارَ","c":"","m":"يُديرُ إِدارَةً: (١) أَدارَ الشَّرِكَةَ: دَبَّرَ شُؤونَها، وَعَمِلَ مُديراً لَها. (٢) أَدارَ المُحَرِّكَ: جَعَلَهُ يَدورُ وَيَعْمَلُ.","t":"(١) أَدارَ الشَّرِكَةَ: دَبَّرَ شُؤونَها، وَعَمِلَ مُديراً لَها. (٢) أَدارَ المُحَرِّكَ: جَعَلَهُ يَدورُ وَيَعْمَلُ.","o":["أَدارَ الشَّرِكَةَ","أَدارَ المُحَرِّكَ"],"b":["أَدارَ المُحَرِّكَ","أَدارَ"],"tr":"yönetmek; çalıştırmak","ttr":"(1) Şirketi yönetti: işlerini düzenledi ve ona müdürlük yaptı. (2) Motoru çalıştırdı: onu döndürüp işletti.","otr":["Şirketi yönetti.","Motoru çalıştırdı."],"r":null,"s":8,"f":"يُديرُ إِدارَةً"},
{"k":"إِدارَة","c":"","m":"مَرْكَزٌ أَوْ مَكانُ التَّحَكُّمِ وَالتَّوْجيهِ، “إِدارَةُ الكُلِّيَّةِ”، وَمَجْلِسُ الإِدارَةِ: الجِهازُ البَشَرِيُّ الَّذي يُسَيِّرُ العَمَلَ.","t":"مَرْكَزٌ أَوْ مَكانُ التَّحَكُّمِ وَالتَّوْجيهِ؛ وَمَجْلِسُ الإِدارَةِ: الجِهازُ البَشَرِيُّ الَّذي يُسَيِّرُ العَمَلَ","o":["إِدارَةُ الكُلِّيَّةِ","مَجْلِسُ الإِدارَةِ"],"b":["إِدارَةُ الكُلِّيَّةِ","إِدارَةُ"],"tr":"yönetim, idare","ttr":"Kontrol ve yönlendirme merkezi ya da yeri; yönetim kurulu: işi yürüten insan kadrosu.","otr":["Fakülte yönetimi.","Yönetim kurulu."],"r":null,"s":8},
{"k":"أَدامَ","c":"","m":"يُديمُ إِدامَةً؛ أَدامَ الشَّيْءَ: جَعَلَهُ دائِماً، “أَدامَ اللهُ عِزَّكَ”.","t":"أَدامَ الشَّيْءَ: جَعَلَهُ دائِماً","o":["أَدامَ اللهُ عِزَّكَ"],"b":["أَدامَ اللهُ عِزَّكَ","أَدامَ"],"tr":"sürdürmek, daim kılmak","ttr":"Bir şeyi sürekli kıldı.","otr":["Allah izzetini daim etsin."],"r":null,"s":8,"f":"يُديمُ إِدامَةً"},
{"k":"أَدَبٌ","c":"آداب","m":"(ج) آداب: (١) مِثْلُ الشِّعْرِ وَالنَّثْرِ وَالقِصَّةِ. (٢) كُلِّيَّةُ الآدابِ: كُلِّيَّةٌ تُدْرَسُ فيها المَعارِفُ وَالعُلومُ الإِنْسانِيَّةُ. (٣) القَواعِدُ المُتَّبَعَةُ في مَجالٍ أَوْ سُلوكٍ مُعَيَّنٍ؛ مِثْل: آداب الطَّريقِ، آداب المائِدَةِ، آداب الحَديثِ.. إلخ. (٤) حُسْنُ التَّصَرُّفِ وَالأَخْلاقُ الحَميدَةُ وَالسُّلوكُ الطَّيِّبُ، “يَجِبُ أَنْ تُعامِلَ زُمَلاءَكَ بِأَدَبٍ”.","t":"(١) مِثْلُ الشِّعْرِ وَالنَّثْرِ وَالقِصَّةِ. (٢) كُلِّيَّةُ الآدابِ: كُلِّيَّةٌ تُدْرَسُ فيها المَعارِفُ وَالعُلومُ الإِنْسانِيَّةُ. (٣) القَواعِدُ المُتَّبَعَةُ في مَجالٍ أَوْ سُلوكٍ مُعَيَّنٍ. (٤) حُسْنُ التَّصَرُّفِ وَالأَخْلاقُ الحَميدَةُ وَالسُّلوكُ الطَّيِّبُ.","o":["آداب الطَّريقِ، آداب المائِدَةِ، آداب الحَديثِ","يَجِبُ أَنْ تُعامِلَ زُمَلاءَكَ بِأَدَبٍ"],"b":["يَجِبُ أَنْ تُعامِلَ زُمَلاءَكَ بِأَدَبٍ","بِأَدَبٍ"],"tr":"edebiyat; edep, terbiye","ttr":"(1) Şiir, nesir ve hikâye gibi (edebiyat). (2) Edebiyat fakültesi: bilgi ve beşerî bilimlerin okutulduğu fakülte. (3) Belirli bir alanda ya da davranışta uyulan kurallar. (4) Güzel davranış, övülen ahlak ve iyi tutum.","otr":["Yol adabı, sofra adabı, konuşma adabı vb.","Arkadaşlarına edeple davranmalısın."],"r":null,"s":8,"y":[["جمع","آداب"]]},
{"k":"أَدَّبَ","c":"","m":"يُؤَدِّبُ تَأْديباً: رَبّى عَلى مَحاسِنِ الأَخْلاقِ، “أَدَّبَ الوالِدُ ابْنَهُ”، وَفي الحَديثِ: (أَدَّبَني رَبّي فَأَحْسَنَ تَأْديبي).","t":"رَبّى عَلى مَحاسِنِ الأَخْلاقِ","o":["أَدَّبَ الوالِدُ ابْنَهُ","أَدَّبَني رَبّي فَأَحْسَنَ تَأْديبي"],"b":["أَدَّبَ الوالِدُ ابْنَهُ","أَدَّبَ"],"tr":"terbiye etmek","ttr":"Güzel ahlak üzere yetiştirdi.","otr":["Baba oğlunu terbiye etti.","Hadiste: Rabbim beni terbiye etti ve terbiyemi en güzel şekilde yaptı."],"r":null,"s":8,"f":"يُؤَدِّبُ تَأْديباً"},
{"k":"أَدْخَلَ","c":"","m":"يُدْخِلُ إِدْخالاً: (١) خِلافُ أَخْرَجَ، “أَدْخَلَ الرَّجُلُ ضَيْفَهُ إِلى البَيْتِ”. (٢) أَحْدَثَ، “أَدْخَلَ تَعْديلاتٍ عَلى القانونِ”.","t":"(١) خِلافُ أَخْرَجَ. (٢) أَحْدَثَ.","o":["أَدْخَلَ الرَّجُلُ ضَيْفَهُ إِلى البَيْتِ","أَدْخَلَ تَعْديلاتٍ عَلى القانونِ"],"b":["أَدْخَلَ الرَّجُلُ ضَيْفَهُ إِلى البَيْتِ","أَدْخَلَ"],"tr":"içeri sokmak, katmak","ttr":"(1) Çıkarmanın zıddı, içeri soktu. (2) Yeni bir şey getirdi, yaptı.","otr":["Adam misafirini eve aldı.","Kanunda değişiklikler yaptı."],"r":"p08_2","s":8,"y":[["مصدر","إِدْخال"]],"f":"يُدْخِلُ إِدْخالاً"},
{"k":"أَدْرَكَ","c":"","m":"يُدْرِكُ إِدْراكاً: (١) رَأى أَوْ فَهِمَ وَاسْتَوْعَبَ، “أَدْرَكْتُ ما تَقولُهُ الآنَ”. (٢)، بَلَغَ سِنَّ الحُلُمِ، “أَدْرَكَ الوَلَدُ”. (٣) لَحِقَ بِهِ، “أَدْرَكْتُ الرَّكْعَةَ الأُولى”.","t":"(١) رَأى أَوْ فَهِمَ وَاسْتَوْعَبَ. (٢) بَلَغَ سِنَّ الحُلُمِ. (٣) لَحِقَ بِهِ.","o":["أَدْرَكْتُ ما تَقولُهُ الآنَ","أَدْرَكَ الوَلَدُ","أَدْرَكْتُ الرَّكْعَةَ الأُولى"],"b":["أَدْرَكْتُ الرَّكْعَةَ الأُولى","أَدْرَكْتُ"],"tr":"kavramak; yetişmek","ttr":"(1) Gördü ya da anladı ve kavradı. (2) Ergenlik çağına erdi. (3) Ona yetişti.","otr":["Şimdi ne dediğini anladım.","Çocuk ergenliğe erdi.","İlk rekâte yetiştim."],"r":null,"s":8,"y":[["مصدر","إِدْراك"]],"f":"يُدْرِكُ إِدْراكاً"},
{"k":"أَدْنى","c":"","m":"(١) أَقْرَبُ، ﴿فَكانَ قابَ قَوْسَيْنِ أَوْ أَدْنى﴾. (٢) أَقَلُّ وَأَحْقَرُ، ﴿أَتَسْتَبْدِلُونَ الَّذي هُوَ أَدْنى بِالَّذي هُوَ خَيْرٌ﴾.","t":"(١) أَقْرَبُ. (٢) أَقَلُّ وَأَحْقَرُ.","o":["﴿فَكانَ قابَ قَوْسَيْنِ أَوْ أَدْنى﴾","﴿أَتَسْتَبْدِلُونَ الَّذي هُوَ أَدْنى بِالَّذي هُوَ خَيْرٌ﴾"],"b":["فَكانَ قابَ قَوْسَيْنِ أَوْ أَدْنى","أَدْنى"],"tr":"daha yakın; daha aşağı","ttr":"(1) Daha yakın. (2) Daha az ve daha değersiz.","otr":["İki yay arası kadar, hatta daha yakın oldu.","Daha değersiz olanı daha hayırlı olanla mı değiştirmek istiyorsunuz?"],"r":null,"s":8},
{"k":"أَرْقَط","c":"","m":"(مُؤ) رَقْطاء: اللَّوْنُ الَّذي فيه بُقَعٌ سَوْداءُ وَأُخْرى بَيْضاءُ، أَو غَيْرُهما، \"هذا قِطٌّ أَرْقَطُ، وتلك قِطَّةٌ رَقْطاء\".","t":"اللَّوْنُ الَّذي فيه بُقَعٌ سَوْداءُ وَأُخْرى بَيْضاءُ، أَو غَيْرُهما","o":["هذا قِطٌّ أَرْقَطُ، وتلك قِطَّةٌ رَقْطاء"],"b":["هذا قِطٌّ أَرْقَطُ، وتلك قِطَّةٌ رَقْطاء","أَرْقَطُ"],"tr":"alacalı, benekli","ttr":"Siyah ve beyaz ya da başka renklerde benekleri olan renk.","otr":["Bu alacalı bir erkek kedi, şu da alacalı bir dişi kedi."],"r":"p11_1","s":11},
{"k":"أَرْمَل","c":"أَرامِل","m":"(ج) أَرامِل: مَنْ ماتَتْ زَوْجَتُهُ؛ أَرْمَلَة: مَنْ ماتَ زَوْجُها، \"هُناكَ جَمعيَّةٌ لِرعايةِ الأَرامل\".","t":"مَنْ ماتَتْ زَوْجَتُهُ؛ أَرْمَلَة: مَنْ ماتَ زَوْجُها","o":["هُناكَ جَمعيَّةٌ لِرعايةِ الأَرامل"],"b":["هُناكَ جَمعيَّةٌ لِرعايةِ الأَرامل","الأَرامل"],"tr":"dul (erkek)","ttr":"Karısı ölmüş kimse; ermele: kocası ölmüş kadın.","otr":["Dullara bakmak için bir dernek var."],"r":null,"s":11},
{"k":"أَرْهَقَ","c":"","m":"يُرهِقُ إِرْهاقاً: أَتْعَبَ وأَجْهَدَ، \"عَمِلَ الطّالِبُ كَثيراً مَعَ والِدِه؛ فأَرْهَقَهُ العملُ\".","t":"أَتْعَبَ وأَجْهَدَ","o":["عَمِلَ الطّالِبُ كَثيراً مَعَ والِدِه؛ فأَرْهَقَهُ العملُ"],"b":["عَمِلَ الطّالِبُ كَثيراً مَعَ والِدِه؛ فأَرْهَقَهُ العملُ","فأَرْهَقَهُ"],"tr":"yormak, bitkin düşürmek","ttr":"Yordu ve takatini tüketti.","otr":["Öğrenci babasıyla birlikte çok çalıştı; iş onu bitkin düşürdü."],"r":null,"s":11,"y":[["مصدر","إِرْهاق"]],"f":"يُرهِقُ إِرْهاقاً"},
{"k":"أَرْوَعُ","c":"","m":"أَكْثَرُ رَوْعَةً: أَكْثَرُ جَمالاً، \"السَّفَرُ بَحْراً أَرْوَعُ مِن السَّفَرِ جَوّاً\".","t":"أَكْثَرُ رَوْعَةً: أَكْثَرُ جَمالاً","o":["السَّفَرُ بَحْراً أَرْوَعُ مِن السَّفَرِ جَوّاً"],"b":["السَّفَرُ بَحْراً أَرْوَعُ مِن السَّفَرِ جَوّاً","أَرْوَعُ"],"tr":"daha harika","ttr":"Daha muhteşem, daha güzel.","otr":["Deniz yolculuğu hava yolculuğundan daha harikadır."],"r":null,"s":11},
{"k":"أَريكَة","c":"أَرائِك","m":"(ج) أَرائِك: مَقْعَدٌ طَويلٌ (مُنجَّد) ذو ذِراعَين، ﴿عَلَى الأَرائِكِ يَنْظُرُونَ﴾.","t":"مَقْعَدٌ طَويلٌ (مُنجَّد) ذو ذِراعَين","o":["﴿عَلَى الأَرائِكِ يَنْظُرُونَ﴾"],"b":["عَلَى الأَرائِكِ يَنْظُرُونَ","الأَرائِكِ"],"tr":"kanepe, koltuk","ttr":"İki kollu, uzun (döşemeli) oturak.","otr":["\"Koltuklar üzerinde (etrafı) seyrederler.\" (Mutaffifîn 23)"],"r":"p11_2","s":11},
{"k":"أَزاحَ","c":"","m":"يُزيحُ إِزاحَةً: أَبْعَدَ، \"أَزاحَ العُمّالُ الصَّخْرَ عَنِ الطَّريقِ\".","t":"أَبْعَدَ","o":["أَزاحَ العُمّالُ الصَّخْرَ عَنِ الطَّريقِ"],"b":["أَزاحَ العُمّالُ الصَّخْرَ عَنِ الطَّريقِ","أَزاحَ"],"tr":"kaldırmak, uzaklaştırmak","ttr":"Uzaklaştırdı.","otr":["İşçiler kayaları yoldan kaldırdı."],"r":"p11_3","s":11,"f":"يُزيحُ إِزاحَةً"},
{"k":"أَزالَ","c":"","m":"يُزيلُ إِزالةً؛ (١) مَحا وَمَسَحَ، \"أَزالَ الكِتابَةَ عَنِ السَّبّورَةِ\". (٢) أَبعَدَ، \"أَزالَ الرَّجُلُ الشَّوكَ عَنِ الطَّريقِ\".","t":"(١) مَحا وَمَسَحَ (٢) أَبعَدَ","o":["أَزالَ الكِتابَةَ عَنِ السَّبّورَةِ","أَزالَ الرَّجُلُ الشَّوكَ عَنِ الطَّريقِ"],"b":["أَزالَ الكِتابَةَ عَنِ السَّبّورَةِ","أَزالَ"],"tr":"silmek, gidermek","ttr":"(1) Sildi, sildi süpürdü. (2) Uzaklaştırdı.","otr":["Yazıyı tahtadan sildi.","Adam dikenleri yoldan kaldırdı."],"r":"p11_4","s":11,"y":[["مصدر","إِزالَة"]],"f":"يُزيلُ إِزالةً"},
{"k":"أَزْر","c":"","m":"مَصْدَرُ أَزَرَ: قُوَّة، شَدَّ أَزْرَهُ/ شَدَّ مِنْ أَزْرِه: قَوّاهُ، ﴿اشْدُدْ بِهِ أَزْرِي﴾.","t":"مَصْدَرُ أَزَرَ: قُوَّة، شَدَّ أَزْرَهُ/ شَدَّ مِنْ أَزْرِه: قَوّاهُ","o":["شَدَّ أَزْرَهُ","شَدَّ مِنْ أَزْرِه","﴿اشْدُدْ بِهِ أَزْرِي﴾"],"b":["اشْدُدْ بِهِ أَزْرِي","أَزْرِي"],"tr":"güç, kuvvet","ttr":"Ezera fiilinin mastarı: güç, kuvvet. Şedde ezrehû / şedde min ezrihî: onu güçlendirdi, destekledi.","otr":["Onu güçlendirdi.","Onu destekledi.","\"Onunla beni güçlendir.\" (Tâhâ 31)"],"r":null,"s":11},
{"k":"أَزْرَق","c":"","m":"(مُؤ) زَرْقاء: أَحَدُ الأَلْوانِ الأَساسيَّة، \"لَوْنُ السَّماءِ أَزْرَقُ، وَلَوْنُ البَحْرِ أَزْرَقُ\".","t":"أَحَدُ الأَلْوانِ الأَساسيَّة","o":["لَوْنُ السَّماءِ أَزْرَقُ، وَلَوْنُ البَحْرِ أَزْرَقُ"],"b":["لَوْنُ السَّماءِ أَزْرَقُ","أَزْرَقُ"],"tr":"mavi","ttr":"Ana renklerden biri.","otr":["Gökyüzünün rengi mavidir, denizin rengi de mavidir."],"r":"p11_5","s":11},
{"k":"أَزْعَجَ","c":"","m":"يُزْعِجُ إِزْعاجاً: ضايَقَ وَأَقْلَقَ، \"أَزْعَجَني صَوْتُ السَّيّاراتِ في الشّارِعِ\"، \"أَزْعَجَني خَبَرُ الحادثِ الَّذي وَقَعَ لِصَديقي\".","t":"ضايَقَ وَأَقْلَقَ","o":["أَزْعَجَني صَوْتُ السَّيّاراتِ في الشّارِعِ","أَزْعَجَني خَبَرُ الحادثِ الَّذي وَقَعَ لِصَديقي"],"b":["أَزْعَجَني صَوْتُ السَّيّاراتِ في الشّارِعِ","أَزْعَجَني"],"tr":"rahatsız etmek","ttr":"Sıktı ve huzursuz etti.","otr":["Sokaktaki arabaların sesi beni rahatsız etti.","Arkadaşımın başına gelen kazanın haberi beni tedirgin etti."],"r":null,"s":11,"f":"يُزْعِجُ إِزْعاجاً"},
{"k":"أَزْمَة","c":"","m":"مُشْكِلَة، ضائِقَة، \"أَضاعَ فُلانٌ كُلَّ ثَرْوَتِه؛ فأصبح في أَزْمَةٍ ماليّة\"، \"هناك أزمة بَيْنَ الدَّوْلَتَيْنِ الجارَتَيْنِ\".","t":"مُشْكِلَة، ضائِقَة","o":["أَضاعَ فُلانٌ كُلَّ ثَرْوَتِه؛ فأصبح في أَزْمَةٍ ماليّة","هناك أزمة بَيْنَ الدَّوْلَتَيْنِ الجارَتَيْنِ"],"b":["أَضاعَ فُلانٌ كُلَّ ثَرْوَتِه؛ فأصبح في أَزْمَةٍ ماليّة","أَزْمَةٍ"],"tr":"kriz, bunalım","ttr":"Sorun, darlık, sıkıntı.","otr":["Falanca bütün servetini kaybetti; mali bir krize düştü.","İki komşu ülke arasında bir kriz var."],"r":null,"s":11},
{"k":"أَزْمَعَ","c":"","m":"يُزْمِعُ إِزْماعاً: عَزَمَ وقَرَّرَ، \"يُزْمِعُ المُديرُ عَلى عَقْدِ اجْتِماعٍ قَريب\".","t":"عَزَمَ وقَرَّرَ","o":["يُزْمِعُ المُديرُ عَلى عَقْدِ اجْتِماعٍ قَريب"],"b":["يُزْمِعُ المُديرُ عَلى عَقْدِ اجْتِماعٍ قَريب","يُزْمِعُ"],"tr":"azmetmek, karar vermek","ttr":"Azmetti ve karar verdi.","otr":["Müdür yakında bir toplantı yapmaya karar vermiş durumda."],"r":null,"s":11,"f":"يُزْمِعُ إِزْماعاً"},
{"k":"أَزيز","c":"","m":"الصَّوْتُ الشَّديد، \"أَزيزُ الطّائِراتِ يَمنَعُني النَّوْمَ\".","t":"الصَّوْتُ الشَّديد","o":["أَزيزُ الطّائِراتِ يَمنَعُني النَّوْمَ"],"b":["أَزيزُ الطّائِراتِ يَمنَعُني النَّوْمَ","أَزيزُ"],"tr":"uğultu, vızıltı","ttr":"Şiddetli ses.","otr":["Uçakların uğultusu beni uyutmuyor."],"r":null,"s":11},
{"k":"أَساءَ","c":"","m":"يُسيءُ إِساءَةً: لَم يُحْسِن؛ آذى، \"أَساءَ فُلانٌ التَّصَرُّفَ مَعَ زُمَلائِه\"، ﴿مَنْ عَمِلَ صالِحاً فَلِنَفْسِه وَمَنْ أَساءَ فَعَلَيْها﴾. \"لَم يَقْبَلْ إِبراهيمُ الإِساءَةَ؛ فَشَكا إِلى الرَّئيسِ\".","t":"لَم يُحْسِن؛ آذى","o":["أَساءَ فُلانٌ التَّصَرُّفَ مَعَ زُمَلائِه","﴿مَنْ عَمِلَ صالِحاً فَلِنَفْسِه وَمَنْ أَساءَ فَعَلَيْها﴾","لَم يَقْبَلْ إِبراهيمُ الإِساءَةَ؛ فَشَكا إِلى الرَّئيسِ"],"b":["أَساءَ فُلانٌ التَّصَرُّفَ مَعَ زُمَلائِه","أَساءَ"],"tr":"kötülük etmek","ttr":"İyi davranmadı; eziyet etti.","otr":["Falanca arkadaşlarına karşı kötü davrandı.","\"Kim iyi bir iş yaparsa kendi lehinedir, kim kötülük ederse kendi aleyhinedir.\" (Fussılet 46)","İbrahim kötü muameleyi kabul etmedi ve müdüre şikâyet etti."],"r":null,"s":12,"y":[["مصدر","إِساءَة"]],"f":"يُسيءُ إِساءَةً"},
{"k":"أَساس","c":"أُسُس","m":"(ج) أُسُس: المَبادِئُ الَّتي تَعتَمِدُ عَلَيها بَعْضُ الظَّواهِرِ أَوِ الأُمورِ، \"بَنَى داروِن نَظَرِيَّتَهُ عَلى أَساسٍ باطِلٍ\"، وفي المَثَلِ: \"العَدْلُ أَساسُ المُلْكِ\".","t":"المَبادِئُ الَّتي تَعتَمِدُ عَلَيها بَعْضُ الظَّواهِرِ أَوِ الأُمورِ","o":["بَنَى داروِن نَظَرِيَّتَهُ عَلى أَساسٍ باطِلٍ","العَدْلُ أَساسُ المُلْكِ"],"b":["العَدْلُ أَساسُ المُلْكِ","أَساسُ"],"tr":"temel, esas","ttr":"Bazı olguların veya işlerin dayandığı ilkeler.","otr":["Darwin teorisini batıl bir temel üzerine kurdu.","(Atasözü) Adalet mülkün temelidir."],"r":null,"s":12},
{"k":"أَساسيّ","c":"","m":"ذو عَلاقَةٍ بِالأَساس، ما لا يُستَغنَى عَنهُ مِنَ الأُمور، \"التَّعْليمُ الأَساسِيُّ مُهِمّ\".","t":"ذو عَلاقَةٍ بِالأَساس، ما لا يُستَغنَى عَنهُ مِنَ الأُمور","o":["التَّعْليمُ الأَساسِيُّ مُهِمّ"],"b":["التَّعْليمُ الأَساسِيُّ مُهِمّ","الأَساسِيُّ"],"tr":"temel, esaslı","ttr":"Temelle ilgili; vazgeçilemeyen şey.","otr":["Temel eğitim önemlidir."],"r":null,"s":12},
{"k":"أَسْبَغَ","c":"","m":"يُسبِغُ إِسباغاً: وَسَّعَ، كَثَّرَ، كَمَّلَ، \"تَوَضَّأَ فَأَسْبَغَ الوُضوءَ\"، ﴿وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُ ظاهِرَةً وَباطِنَةً﴾.","t":"وَسَّعَ، كَثَّرَ، كَمَّلَ","o":["تَوَضَّأَ فَأَسْبَغَ الوُضوءَ","﴿وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُ ظاهِرَةً وَباطِنَةً﴾"],"b":["تَوَضَّأَ فَأَسْبَغَ الوُضوءَ","فَأَسْبَغَ"],"tr":"bolca vermek, tamamlamak","ttr":"Genişletti, çoğalttı, tamamladı.","otr":["Abdest aldı ve abdestini tam (güzelce) aldı.","\"Size açık ve gizli nimetlerini bolca verdi.\" (Lokmân 20)"],"r":null,"s":12,"f":"يُسبِغُ إِسباغاً"},
{"k":"أَسْبَقُ","c":"","m":"أَكْثَرُ سَبْقاً وَتَقدُّماً وَمُبادَرَةً مِن غَيرِه، \"كانَ الفَرَسُ الأَبيَضُ الأَسْبَقَ في العَدْوِ\"، \"عَلِيٌّ أَسْبَقُ إِلى فِعلِ الخَيْراتِ مِن إِخْوَتِه\".","t":"أَكْثَرُ سَبْقاً وَتَقدُّماً وَمُبادَرَةً مِن غَيرِه","o":["كانَ الفَرَسُ الأَبيَضُ الأَسْبَقَ في العَدْوِ","عَلِيٌّ أَسْبَقُ إِلى فِعلِ الخَيْراتِ مِن إِخْوَتِه"],"b":["عَلِيٌّ أَسْبَقُ إِلى فِعلِ الخَيْراتِ مِن إِخْوَتِه","أَسْبَقُ"],"tr":"daha önde, daha önce davranan","ttr":"Başkasından daha önde, daha ileri ve daha girişken olan.","otr":["Beyaz at koşuda en öndeydi.","Ali hayır işlemede kardeşlerinden daha öndedir."],"r":null,"s":12},
{"k":"أَسْبَلَ","c":"","m":"يُسْبِلُ إِسْبالاً: أَطالَ ثَوبَهُ وَإِزارَهُ إِلى ما تَحْتَ الكَعْبَيْنِ، فَهُوَ مُسْبِلٌ، \"أَسْبَلَ الرَّجُلُ ثَوْبَهُ تَكَبُّراً\".","t":"أَطالَ ثَوبَهُ وَإِزارَهُ إِلى ما تَحْتَ الكَعْبَيْنِ، فَهُوَ مُسْبِلٌ","o":["أَسْبَلَ الرَّجُلُ ثَوْبَهُ تَكَبُّراً"],"b":["أَسْبَلَ الرَّجُلُ ثَوْبَهُ تَكَبُّراً","أَسْبَلَ"],"tr":"(elbiseyi) sarkıtmak","ttr":"Elbisesini ve izarını topukların altına kadar uzattı; böyle yapana müsbil denir.","otr":["Adam kibirlenerek elbisesini yerlere sarkıttı."],"r":"p12_5","s":12,"f":"يُسْبِلُ إِسْبالاً"},
{"k":"أُسْبوع","c":"أَسابيع","m":"(ج) أَسابيع: سَبْعَةُ أَيّامٍ، \"مِنَ الجُمُعَةِ إِلى الجُمُعَةِ أُسبوعٌ كامِلٌ فيهِ سَبْعَةُ أَيّام\"، \"وفي الشَّهْرِ أَرْبَعَةُ أَسابيعَ\".","t":"سَبْعَةُ أَيّامٍ","o":["مِنَ الجُمُعَةِ إِلى الجُمُعَةِ أُسبوعٌ كامِلٌ فيهِ سَبْعَةُ أَيّام","وفي الشَّهْرِ أَرْبَعَةُ أَسابيعَ"],"b":["مِنَ الجُمُعَةِ إِلى الجُمُعَةِ أُسبوعٌ كامِلٌ فيهِ سَبْعَةُ أَيّام","أُسبوعٌ"],"tr":"hafta","ttr":"Yedi gün.","otr":["Cumadan cumaya içinde yedi gün olan tam bir hafta vardır.","Ayda dört hafta vardır."],"r":null,"s":12,"y":[["جمع","أَسابيع"]]},
{"k":"أُسْتاذ","c":"أَساتِذَة","m":"(ج) أَساتِذَة: (١) مُعَلِّم، مُدَرِّس، \"إِبراهيمُ أُستاذُ العُلومِ في مَدْرَسَتِنا\". (٢) ماهِر، \"أَحمَدُ أُستاذٌ في كُرَةِ القَدَمِ\".","t":"(١) مُعَلِّم، مُدَرِّس (٢) ماهِر","o":["إِبراهيمُ أُستاذُ العُلومِ في مَدْرَسَتِنا","أَحمَدُ أُستاذٌ في كُرَةِ القَدَمِ"],"b":["إِبراهيمُ أُستاذُ العُلومِ في مَدْرَسَتِنا","أُستاذُ"],"tr":"öğretmen, hoca; usta","ttr":"(1) Muallim, öğretmen. (2) Usta, mahir.","otr":["İbrahim okulumuzun fen öğretmenidir.","Ahmed futbolda ustadır."],"r":"p12_1","s":12,"y":[["جمع","أَساتِذَة"]]},
{"k":"أَسَد","c":"أُسود","m":"(ج) أُسود: حَيَوانٌ مُفتَرِسٌ يُطلَقُ عَلَيهِ مَلِكُ الغابَةِ، يُضْرَبُ بِهِ المَثَلُ في الشَّجاعَةِ، \"الجُندِيُّ المُسلِمُ كَالأَسَدِ في الحُروبِ\".","t":"حَيَوانٌ مُفتَرِسٌ يُطلَقُ عَلَيهِ مَلِكُ الغابَةِ، يُضْرَبُ بِهِ المَثَلُ في الشَّجاعَةِ","o":["الجُندِيُّ المُسلِمُ كَالأَسَدِ في الحُروبِ"],"b":["الجُندِيُّ المُسلِمُ كَالأَسَدِ في الحُروبِ","كَالأَسَدِ"],"tr":"aslan","ttr":"Ormanlar kralı denen, cesarette örnek gösterilen yırtıcı hayvan.","otr":["Müslüman asker savaşlarda aslan gibidir."],"r":"p12_2","s":12},
{"k":"أَسْدَلَ","c":"","m":"يُسْدِلُ إِسْدالاً: أَرْخَى، \"أَسْدَلَ المُخْرِجُ السِّتارَةَ عَلى المَشْهَدِ الأَخير\".","t":"أَرْخَى","o":["أَسْدَلَ المُخْرِجُ السِّتارَةَ عَلى المَشْهَدِ الأَخير"],"b":["أَسْدَلَ المُخْرِجُ السِّتارَةَ عَلى المَشْهَدِ الأَخير","أَسْدَلَ"],"tr":"(perde) indirmek, sarkıtmak","ttr":"Salıverdi, sarkıttı.","otr":["Yönetmen son sahnede perdeyi indirdi."],"r":"p12_3","s":12,"f":"يُسْدِلُ إِسْدالاً"},
{"k":"أَسْدَى","c":"","m":"يُسْدي إِسْداءً: أَعْطَى وَقَدَّمَ، \"مَنْ أَسْدَى إِلَيكَ مَعروفاً فاشكُرْهُ\".","t":"أَعْطَى وَقَدَّمَ","o":["مَنْ أَسْدَى إِلَيكَ مَعروفاً فاشكُرْهُ"],"b":["مَنْ أَسْدَى إِلَيكَ مَعروفاً فاشكُرْهُ","أَسْدَى"],"tr":"(iyilik) etmek, sunmak","ttr":"Verdi ve sundu.","otr":["Sana bir iyilik yapana teşekkür et."],"r":null,"s":12,"f":"يُسْدي إِسْداءً"},
{"k":"أَسَرَ","c":"","m":"يَأْسِرُ أَسْراً؛ قَبَضَ عَلَى، \"أَسَرَ الجُنْدِيَّ\".","t":"قَبَضَ عَلَى","o":["أَسَرَ الجُنْدِيَّ"],"b":["أَسَرَ الجُنْدِيَّ","أَسَرَ"],"tr":"esir almak","ttr":"Yakaladı.","otr":["Askeri esir aldı."],"r":"p12_4","s":12,"f":"يَأْسِرُ أَسْراً"},
{"k":"إِسْرائيل","c":"","m":"لَقَبٌ أُطْلِقَ عَلَى يَعْقوبَ بنِ إِسحاقَ بنِ إِبراهيمَ الخَليلِ عَلَيهِمُ السَّلام، ﴿كُلُّ الطَّعامِ كانَ حِلّاً لِبَني إِسْرائيلَ إِلّا ما حَرَّمَ إِسْرائيلُ عَلى نَفْسِه﴾.","t":"لَقَبٌ أُطْلِقَ عَلَى يَعْقوبَ بنِ إِسحاقَ بنِ إِبراهيمَ الخَليلِ عَلَيهِمُ السَّلام","o":["﴿كُلُّ الطَّعامِ كانَ حِلّاً لِبَني إِسْرائيلَ إِلّا ما حَرَّمَ إِسْرائيلُ عَلى نَفْسِه﴾"],"b":["كُلُّ الطَّعامِ كانَ حِلّاً لِبَني إِسْرائيلَ","إِسْرائيلَ"],"tr":"İsrail (Hz. Yakub)","ttr":"Halil İbrahim oğlu İshak oğlu Yakub'a (selam üzerlerine olsun) verilen lakap.","otr":["\"İsrail'in (Yakub'un) kendisine haram kıldıkları dışında bütün yiyecekler İsrailoğullarına helaldi.\" (Âl-i İmrân 93)"],"r":null,"s":12},
{"k":"أُسْرَة","c":"أُسَر","m":"(ج) أُسَر: (١) الأُسْرَةُ الأَهلُ وَالأَقارِبُ، \"تَتَكَوَّنُ الأُسْرَةُ مِنَ الأَبِ وَالأُمِّ وَالأَوْلادِ\". (٢) جَماعَةٌ يَربِطُها أَمْرٌ مُشْتَرَكٌ، \"نَحنُ في هذِه المَدْرَسَةِ أُسْرَةٌ واحِدَةٌ\". العالَمِينَ ) ، ﴿ فَسُبْحَانَ اللَّهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ ﴾ . ( ٢ ) مِنْ أَخَواتِ كانَ ، “أَصْبَحَ الطّالِبُ طَبيباً” .","t":"(١) الأُسْرَةُ الأَهلُ وَالأَقارِبُ (٢) جَماعَةٌ يَربِطُها أَمْرٌ مُشْتَرَكٌ","o":["تَتَكَوَّنُ الأُسْرَةُ مِنَ الأَبِ وَالأُمِّ وَالأَوْلادِ","نَحنُ في هذِه المَدْرَسَةِ أُسْرَةٌ واحِدَةٌ"],"b":["تَتَكَوَّنُ الأُسْرَةُ مِنَ الأَبِ وَالأُمِّ وَالأَوْلادِ","الأُسْرَةُ"],"tr":"aile","ttr":"(1) Aile: ev halkı ve akrabalar. (2) Ortak bir işin birbirine bağladığı topluluk.","otr":["Aile anne, baba ve çocuklardan oluşur.","Biz bu okulda tek bir aileyiz."],"r":null,"s":12,"y":[["جمع","أُسَر"]]},
{"k":"إِصْبَعٌ","c":"أَصابِع","m":"(ج) أَصابِع ، مُؤَنَّث وقَدْ يُذَكَّر . عُضْوٌ في طَرَفِ الكَفِّ أَوِ القَدَمِ ، “أَصابِعُ اليَدِ خَمْسَةٌ وكَذلِكَ أَصابِعُ القَدَمِ” ، ﴿ يَجْعَلُونَ أَصَابِعَهُمْ فِي آذَانِهِمْ مِنَ الصَّوَاعِقِ ﴾ .","t":"مُؤَنَّث وقَدْ يُذَكَّر . عُضْوٌ في طَرَفِ الكَفِّ أَوِ القَدَمِ","o":["أَصابِعُ اليَدِ خَمْسَةٌ وكَذلِكَ أَصابِعُ القَدَمِ","يَجْعَلُونَ أَصَابِعَهُمْ فِي آذَانِهِمْ مِنَ الصَّوَاعِقِ"],"b":["أَصابِعُ اليَدِ خَمْسَةٌ وكَذلِكَ أَصابِعُ القَدَمِ","أَصابِعُ"],"tr":"parmak","ttr":"Dişildir, bazen eril de kullanılır. El ayasının veya ayağın ucundaki uzuv.","otr":["Elin parmakları beştir, ayağın parmakları da öyle.","Yıldırımlardan dolayı parmaklarını kulaklarına tıkıyorlar."],"r":"p16_1","s":16},
{"k":"أَصْدَرَ","c":"","m":"يُصْدِرُ إِصْداراً : ( ١ ) أَنْفَذَ ، “أَصْدَرَ الرَّئيسُ قَراراً بِمُعاقَبَةِ المَسْؤولينَ عَنِ الأَخْطاءِ” . ( ٢ ) نَشَرَ وَوَزَّعَ ، “أَصْدَرَ المُؤَلِّفُ كِتاباً جَديداً” .","t":"(١) أَنْفَذَ . (٢) نَشَرَ وَوَزَّعَ","o":["أَصْدَرَ الرَّئيسُ قَراراً بِمُعاقَبَةِ المَسْؤولينَ عَنِ الأَخْطاءِ","أَصْدَرَ المُؤَلِّفُ كِتاباً جَديداً"],"b":["أَصْدَرَ المُؤَلِّفُ كِتاباً جَديداً","أَصْدَرَ"],"tr":"çıkarmak, yayımlamak","ttr":"(1) Yürürlüğe koydu, çıkardı. (2) Yayımladı ve dağıttı.","otr":["Başkan, hatalardan sorumlu olanların cezalandırılmasına dair bir karar çıkardı.","Yazar yeni bir kitap yayımladı."],"r":null,"s":16,"f":"يُصْدِرُ إِصْداراً"},
{"k":"أَصْدَقُ","c":"","m":"أَكْثَرُ صِدْقاً ؛ “أَحْمَدُ أَصْدَقُ مِنْ أَخيهِ” ، ﴿ وَمَنْ أَصْدَقُ مِنَ اللَّهِ قِيلاً ﴾ .","t":"أَكْثَرُ صِدْقاً","o":["أَحْمَدُ أَصْدَقُ مِنْ أَخيهِ","وَمَنْ أَصْدَقُ مِنَ اللَّهِ قِيلاً"],"b":["أَحْمَدُ أَصْدَقُ مِنْ أَخيهِ","أَصْدَقُ"],"tr":"daha doğru sözlü","ttr":"Daha dürüst, daha doğru sözlü.","otr":["Ahmed kardeşinden daha doğru sözlüdür.","Söz bakımından Allah'tan daha doğru kim olabilir?"],"r":null,"s":16},
{"k":"أَصَرَّ","c":"","m":"يُصِرُّ إِصْراراً : لَزِمَ وثَبَتَ ، “أَصَرَّ على مَوْقِفِهِ” ، ﴿ وَأَصَرُّوا وَاسْتَكْبَرُوا اسْتِكْبَاراً ﴾ ، ﴿ وَكَانُوا يُصِرُّونَ عَلَى الْحِنْثِ الْعَظِيمِ ﴾ .","t":"لَزِمَ وثَبَتَ","o":["أَصَرَّ على مَوْقِفِهِ","وَأَصَرُّوا وَاسْتَكْبَرُوا اسْتِكْبَاراً","وَكَانُوا يُصِرُّونَ عَلَى الْحِنْثِ الْعَظِيمِ"],"b":["أَصَرَّ على مَوْقِفِهِ","أَصَرَّ"],"tr":"ısrar etmek","ttr":"Bir şeye sıkıca bağlı kaldı ve sebat etti.","otr":["Tutumunda ısrar etti.","Direttiler ve büyüklendikçe büyüklendiler.","Ve büyük günahta ısrar ediyorlardı."],"r":null,"s":16,"y":[["مصدر","إِصْرار"]],"f":"يُصِرُّ إِصْراراً"},
{"k":"أَصْعَبُ","c":"","m":"أَكْثَرُ صُعوبَةً ؛ خِلافُ أَسْهَل وأَيْسَر ، “صُعودُ الجَبَلِ أَصْعَبُ مِنْ صُعودِ الدَّرَجِ” ، “اخْتِبارُ الرِّياضِيّاتِ أَصْعَبُ مِنِ اخْتِبارِ اللُّغَةِ العَرَبِيَّةِ” .","t":"أَكْثَرُ صُعوبَةً ؛ خِلافُ أَسْهَل وأَيْسَر","o":["صُعودُ الجَبَلِ أَصْعَبُ مِنْ صُعودِ الدَّرَجِ","اخْتِبارُ الرِّياضِيّاتِ أَصْعَبُ مِنِ اخْتِبارِ اللُّغَةِ العَرَبِيَّةِ"],"b":["صُعودُ الجَبَلِ أَصْعَبُ مِنْ صُعودِ الدَّرَجِ","أَصْعَبُ"],"tr":"daha zor","ttr":"Daha zor; 'daha kolay' ve 'daha rahat'ın zıddı.","otr":["Dağa çıkmak merdiven çıkmaktan daha zordur.","Matematik sınavı Arapça sınavından daha zordur."],"r":null,"s":16},
{"k":"أَصْغَرُ","c":"","m":"خِلافُ أَكْبَر ، “لَيْلَى أَصْغَرُ مِنْ أُخْتِها” . “عَلِيٌّ أَكْبَرُ أَبْنائي وَمُحَمَّدٌ أَصْغَرُهُمْ” ، ﴿ وَلَا أَصْغَرَ مِنْ ذَلِكَ وَلَا أَكْبَرَ إِلَّا فِي كِتَابٍ ﴾ .","t":"خِلافُ أَكْبَر","o":["لَيْلَى أَصْغَرُ مِنْ أُخْتِها","عَلِيٌّ أَكْبَرُ أَبْنائي وَمُحَمَّدٌ أَصْغَرُهُمْ","وَلَا أَصْغَرَ مِنْ ذَلِكَ وَلَا أَكْبَرَ إِلَّا فِي كِتَابٍ"],"b":["لَيْلَى أَصْغَرُ مِنْ أُخْتِها","أَصْغَرُ"],"tr":"daha küçük","ttr":"'Daha büyük'ün zıddı.","otr":["Leyla kız kardeşinden daha küçüktür.","Ali oğullarımın en büyüğü, Muhammed ise en küçükleridir.","Ondan daha küçüğü de daha büyüğü de ancak bir kitaptadır."],"r":"p16_2","s":16},
{"k":"أَصْغَى","c":"","m":"يُصْغي إِصْغاءً ؛ اسْتَمَعَ بِعِنايَةٍ واهْتِمامٍ ، “أَصْغِ لِنَصيحَةِ والِدَيْكَ” .","t":"اسْتَمَعَ بِعِنايَةٍ واهْتِمامٍ","o":["أَصْغِ لِنَصيحَةِ والِدَيْكَ"],"b":["أَصْغِ لِنَصيحَةِ والِدَيْكَ","أَصْغِ"],"tr":"kulak vermek","ttr":"Özenle ve ilgiyle dinledi.","otr":["Anne babanın nasihatine kulak ver."],"r":null,"s":16,"f":"يُصْغي إِصْغاءً"},
{"k":"أَصْفَر","c":"","m":"(مُؤ) صَفْراء : لَوْنٌ . “المَوْزُ أَصْفَرُ اللَّوْنِ” ، ﴿ إِنَّهَا بَقَرَةٌ صَفْرَاءُ فَاقِعٌ لَوْنُهَا ﴾ .","t":"(مُؤ) صَفْراء : لَوْنٌ","o":["المَوْزُ أَصْفَرُ اللَّوْنِ","إِنَّهَا بَقَرَةٌ صَفْرَاءُ فَاقِعٌ لَوْنُهَا"],"b":["المَوْزُ أَصْفَرُ اللَّوْنِ","أَصْفَرُ"],"tr":"sarı","ttr":"Dişili: safrâ. Bir renk.","otr":["Muz sarı renklidir.","O, rengi parlak sarı bir inektir."],"r":"p16_3","s":16},
{"k":"أَصْل","c":"أُصول","m":"(ج) أُصول : ( ١ ) أَساسُ الشَّيْءِ وَمَبْدَؤُهُ الَّذي قامَ عَلَيْهِ ، “كانَ أَصْلُ الكِتابِ بَحْثاً صَغيراً في هذا المَوْضوعِ” . ( ٢ ) جِذْر ، “أَصْلُ الشَّجَرَةِ قَوِيٌّ” ، ﴿ أَلَمْ تَرَ كَيْفَ ضَرَبَ اللَّهُ مَثَلاً كَلِمَةً طَيِّبَةً كَشَجَرَةٍ طَيِّبَةٍ أَصْلُهَا ثَابِتٌ وَفَرْعُهَا فِي السَّمَاءِ ﴾ .","t":"(١) أَساسُ الشَّيْءِ وَمَبْدَؤُهُ الَّذي قامَ عَلَيْهِ . (٢) جِذْر","o":["كانَ أَصْلُ الكِتابِ بَحْثاً صَغيراً في هذا المَوْضوعِ","أَصْلُ الشَّجَرَةِ قَوِيٌّ","أَلَمْ تَرَ كَيْفَ ضَرَبَ اللَّهُ مَثَلاً كَلِمَةً طَيِّبَةً كَشَجَرَةٍ طَيِّبَةٍ أَصْلُهَا ثَابِتٌ وَفَرْعُهَا فِي السَّمَاءِ"],"b":["أَصْلُ الشَّجَرَةِ قَوِيٌّ","أَصْلُ"],"tr":"asıl, kök","ttr":"(1) Bir şeyin dayandığı temel ve başlangıç noktası. (2) Kök.","otr":["Kitabın aslı bu konuda küçük bir araştırmaydı.","Ağacın kökü sağlamdır.","Görmedin mi Allah nasıl bir misal verdi: Güzel bir söz, kökü sağlam, dalları göğe uzanan güzel bir ağaç gibidir."],"r":null,"s":16,"y":[["جمع","أُصول"]]},
{"k":"أَصْلَحُ","c":"","m":"أَكْثَرُ صَلاحاً : وَمَنْفَعَةً .","t":"أَكْثَرُ صَلاحاً وَمَنْفَعَةً","o":[],"b":null,"tr":"daha iyi, daha yararlı","ttr":"Daha iyi ve daha faydalı.","otr":[],"r":null,"s":16,"y":[["مصدر","إِصْلاح"]]},
{"k":"أَصْلَحَ","c":"","m":"يُصْلِحُ إِصْلاحاً : ( ١ ) أَزالَ الفَسادَ ، “أَصْلَحَ مُحَمَّدٌ دَرّاجَتَهُ” . ( ٢ ) أَزالَ الخِصامَ ، “أَصْلَحَ مُحَمَّدٌ بَيْنَ عَلِيٍّ وَأَحْمَدَ” ، ﴿ وَإِنْ طَائِفَتَانِ مِنَ الْمُؤْمِنِينَ اقْتَتَلُوا فَأَصْلِحُوا بَيْنَهُمَا ﴾ .","t":"(١) أَزالَ الفَسادَ . (٢) أَزالَ الخِصامَ","o":["أَصْلَحَ مُحَمَّدٌ دَرّاجَتَهُ","أَصْلَحَ مُحَمَّدٌ بَيْنَ عَلِيٍّ وَأَحْمَدَ","وَإِنْ طَائِفَتَانِ مِنَ الْمُؤْمِنِينَ اقْتَتَلُوا فَأَصْلِحُوا بَيْنَهُمَا"],"b":["أَصْلَحَ مُحَمَّدٌ دَرّاجَتَهُ","أَصْلَحَ"],"tr":"onarmak, barıştırmak","ttr":"(1) Bozukluğu giderdi, onardı. (2) Anlaşmazlığı giderdi, arayı düzeltti.","otr":["Muhammed bisikletini tamir etti.","Muhammed, Ali ile Ahmed'in arasını düzeltti.","Müminlerden iki grup birbiriyle savaşırsa aralarını düzeltin."],"r":"p16_4","s":16,"f":"يُصْلِحُ إِصْلاحاً"},
{"k":"أَصْلَعُ","c":"","m":"أَقْرَعُ ، مَنْ سَقَطَ شَعْرُ رَأْسِهِ أَوْ بَعْضُهُ ، “لا يَتْرُكُ الأَصْلَعُ رَأْسَهُ حاسِراً” .","t":"أَقْرَعُ ، مَنْ سَقَطَ شَعْرُ رَأْسِهِ أَوْ بَعْضُهُ","o":["لا يَتْرُكُ الأَصْلَعُ رَأْسَهُ حاسِراً"],"b":["لا يَتْرُكُ الأَصْلَعُ رَأْسَهُ حاسِراً","الأَصْلَعُ"],"tr":"kel, dazlak","ttr":"Kel; başının saçının tamamı veya bir kısmı dökülmüş kimse.","otr":["Kel adam başını açık bırakmaz."],"r":"p16_5","s":16},
{"k":"أُصولِيّ","c":"","m":"أَمْرٌ أَوْ شَخْصٌ يَسيرُ حَسَبَ القَواعِدِ والأُصولِ ، “هذا اتِّجاهٌ أُصولِيٌّ” .","t":"أَمْرٌ أَوْ شَخْصٌ يَسيرُ حَسَبَ القَواعِدِ والأُصولِ","o":["هذا اتِّجاهٌ أُصولِيٌّ"],"b":["هذا اتِّجاهٌ أُصولِيٌّ","أُصولِيٌّ"],"tr":"usule bağlı, kuralcı","ttr":"Kurallara ve usullere göre hareket eden şey veya kişi.","otr":["Bu, usule bağlı (kuralcı) bir yaklaşımdır."],"r":null,"s":16},
{"k":"أَصيل","c":"","m":"(مُؤ) أَصيلَة : ( ١ ) شَريفُ الأَصْلِ عَريقُ النَّسَبِ ، “إِذا كُنْتَ أَصيلاً ، فَكُنْ ذا مُروءَةٍ” . ( ٢ ) الجَيِّدُ المُبْتَكَرُ ، “هذا بَحْثٌ أَفْكارُهُ أَصيلَةٌ” . ( ٣ ) مِنْ نَوْعٍ جَيِّدٍ ، “هذا الحِصانُ أَصيلٌ” .","t":"(١) شَريفُ الأَصْلِ عَريقُ النَّسَبِ . (٢) الجَيِّدُ المُبْتَكَرُ . (٣) مِنْ نَوْعٍ جَيِّدٍ","o":["إِذا كُنْتَ أَصيلاً ، فَكُنْ ذا مُروءَةٍ","هذا بَحْثٌ أَفْكارُهُ أَصيلَةٌ","هذا الحِصانُ أَصيلٌ"],"b":["هذا الحِصانُ أَصيلٌ","أَصيلٌ"],"tr":"soylu, özgün, safkan","ttr":"Dişili: asîle. (1) Soyu şerefli, köklü nesepli. (2) İyi ve özgün. (3) İyi cinsten.","otr":["Soylu biriysen mürüvvet sahibi ol.","Bu, fikirleri özgün bir araştırmadır.","Bu at safkandır."],"r":null,"s":16},
{"k":"أَضاءَ","c":"","m":"يُضيءُ إِضاءَةً . أَشْرَقَ وَأَنارَ ، ﴿ كُلَّمَا أَضَاءَ لَهُمْ مَشَوْا فِيهِ ﴾ .","t":"أَشْرَقَ وَأَنارَ","o":["كُلَّمَا أَضَاءَ لَهُمْ مَشَوْا فِيهِ"],"b":["كُلَّمَا أَضَاءَ لَهُمْ مَشَوْا فِيهِ","أَضَاءَ"],"tr":"aydınlatmak, parlamak","ttr":"Parladı ve aydınlattı.","otr":["(Şimşek) onlara ışık verdikçe onun ışığında yürürler."],"r":"p17_1","s":17,"y":[["مصدر","إِضاءَة"]]},
{"k":"أَضاعَ","c":"","m":"يُضيعُ إِضاعَةً : فَقَدَ / أَفْقَدَ ، أَضاعَ الشَّيْءَ : فَقَدَهُ ، ﴿ إِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ ﴾ .","t":"فَقَدَ / أَفْقَدَ ، أَضاعَ الشَّيْءَ : فَقَدَهُ","o":["إِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ"],"b":["إِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ","يُضِيعُ"],"tr":"kaybetmek, zayi etmek","ttr":"Kaybetti / kaybettirdi; bir şeyi zayi etti: onu kaybetti.","otr":["Şüphesiz Allah iyilik yapanların ecrini zayi etmez."],"r":null,"s":17,"y":[["مصدر","إِضاعَة"]],"f":"يُضيعُ إِضاعَةً"},
{"k":"أَضافَ","c":"","m":"يُضيفُ إِضافَةً : ( ١ ) ضَمَّ وَزادَ ، “أَضافَ الكاتِبُ فَصْلاً جَديداً إِلى كِتابِهِ” . ( ٢ ) الإِضافَةُ في النَّحْوِ : رَبْطُ اسْمَيْنِ بَعْضِهِما بِبَعْضٍ لِلتَّعْريفِ أَوِ التَّخْصيصِ ؛ فَيُسَمَّى الأَوَّلُ مُضافاً وَيُسَمَّى الثّاني مُضافاً إِلَيْهِ ، مِثْل : “كِتابُ الطّالِبِ” ، “مُديرُ المَعْهَدِ” .","t":"(١) ضَمَّ وَزادَ . (٢) الإِضافَةُ في النَّحْوِ : رَبْطُ اسْمَيْنِ بَعْضِهِما بِبَعْضٍ لِلتَّعْريفِ أَوِ التَّخْصيصِ ؛ فَيُسَمَّى الأَوَّلُ مُضافاً وَيُسَمَّى الثّاني مُضافاً إِلَيْهِ","o":["أَضافَ الكاتِبُ فَصْلاً جَديداً إِلى كِتابِهِ","كِتابُ الطّالِبِ","مُديرُ المَعْهَدِ"],"b":["أَضافَ الكاتِبُ فَصْلاً جَديداً إِلى كِتابِهِ","أَضافَ"],"tr":"eklemek","ttr":"(1) Kattı ve artırdı. (2) Nahivde izafet: iki ismin belirlilik veya özellik kazandırmak için birbirine bağlanması; birincisine muzâf, ikincisine muzâfun ileyh denir.","otr":["Yazar kitabına yeni bir bölüm ekledi.","öğrencinin kitabı","enstitünün müdürü"],"r":null,"s":17,"y":[["مصدر","إِضافَة"]],"f":"يُضيفُ إِضافَةً"},
{"k":"أَضْحَكَ","c":"","m":"يُضْحِكُ إِضْحاكاً : سَرَّ وَأَفْرَحَ ، خِلافُ أَبْكَى ، ﴿ وَأَنَّهُ هُوَ أَضْحَكَ وَأَبْكَى ﴾ .","t":"سَرَّ وَأَفْرَحَ ، خِلافُ أَبْكَى","o":["وَأَنَّهُ هُوَ أَضْحَكَ وَأَبْكَى"],"b":["وَأَنَّهُ هُوَ أَضْحَكَ وَأَبْكَى","أَضْحَكَ"],"tr":"güldürmek","ttr":"Sevindirdi ve neşelendirdi; 'ağlattı'nın zıddı.","otr":["Güldüren de ağlatan da O'dur."],"r":"p17_2","s":17,"y":[["مصدر","إِضْحاك"]],"f":"يُضْحِكُ إِضْحاكاً"},
{"k":"أُضْحِيَة","c":"أَضاحٍ (الأَضاحي)","m":"(ج) أَضاحٍ ( الأَضاحي ) ؛ الشّاةُ أَوْ نَحْوُها مِمّا يُضَحَّى بِهِ في عيدِ الأَضْحَى .","t":"الشّاةُ أَوْ نَحْوُها مِمّا يُضَحَّى بِهِ في عيدِ الأَضْحَى","o":[],"b":null,"tr":"kurbanlık","ttr":"Kurban Bayramı'nda kurban edilen koyun ve benzeri hayvan.","otr":[],"r":null,"s":17},
{"k":"أَضْرَبَ","c":"","m":"يُضْرِبُ إِضْراباً : كَفَّ وَتَوَقَّفَ احْتِجاجاً لِأَمْرٍ ما ، “أَضْرَبَ العُمّالُ عَنِ العَمَلِ” ، “أَضْرَبَ الأَسيرُ عَنِ الطَّعامِ احْتِجاجاً عَلى سوءِ مُعامَلَتِهِ” .","t":"كَفَّ وَتَوَقَّفَ احْتِجاجاً لِأَمْرٍ ما","o":["أَضْرَبَ العُمّالُ عَنِ العَمَلِ","أَضْرَبَ الأَسيرُ عَنِ الطَّعامِ احْتِجاجاً عَلى سوءِ مُعامَلَتِهِ"],"b":["أَضْرَبَ العُمّالُ عَنِ العَمَلِ","أَضْرَبَ"],"tr":"grev yapmak","ttr":"Bir şeyi protesto etmek için (bir işten) el çekti ve durdu.","otr":["İşçiler grev yaptı (işi bıraktı).","Esir, kötü muameleyi protesto ederek açlık grevi yaptı."],"r":null,"s":17,"f":"يُضْرِبُ إِضْراباً"},
{"k":"أَضْرَمَ","c":"","m":"يُضْرِمُ إِضْراماً : أَوْقَدَ وَأَشْعَلَ ، “أَضْرَمَ النّارَ” ، “أَضْرَمَ الكاذِبُ الحَرْبَ بَيْنَ الصَّديقَيْنِ” .","t":"أَوْقَدَ وَأَشْعَلَ","o":["أَضْرَمَ النّارَ","أَضْرَمَ الكاذِبُ الحَرْبَ بَيْنَ الصَّديقَيْنِ"],"b":["أَضْرَمَ الكاذِبُ الحَرْبَ بَيْنَ الصَّديقَيْنِ","أَضْرَمَ"],"tr":"tutuşturmak, alevlendirmek","ttr":"Yaktı ve tutuşturdu.","otr":["Ateşi tutuşturdu.","Yalancı, iki arkadaş arasında savaşı alevlendirdi."],"r":"p17_3","s":17,"f":"يُضْرِمُ إِضْراماً"},
{"k":"أَضْعَفَ","c":"","m":"يُضْعِفُ إِضْعافاً : أَهْزَلَ ، أَنْهَكَ ، أَضْعَفَ الشَّيْءَ : جَعَلَهُ ضَعيفاً ، “أَضْعَفَ جِسْمَهُ بِقِلَّةِ الأَكْلِ ، وَعَدَمِ مُمارَسَةِ الرِّياضَةِ” ، “العَدُوُّ يَجْتَهِدُ لِإِضْعافِ الأُمَّةِ” .","t":"أَهْزَلَ ، أَنْهَكَ ، أَضْعَفَ الشَّيْءَ : جَعَلَهُ ضَعيفاً","o":["أَضْعَفَ جِسْمَهُ بِقِلَّةِ الأَكْلِ ، وَعَدَمِ مُمارَسَةِ الرِّياضَةِ","العَدُوُّ يَجْتَهِدُ لِإِضْعافِ الأُمَّةِ"],"b":["أَضْعَفَ جِسْمَهُ بِقِلَّةِ الأَكْلِ ، وَعَدَمِ مُمارَسَةِ الرِّياضَةِ","أَضْعَفَ"],"tr":"zayıflatmak","ttr":"Zayıf düşürdü, bitkin düşürdü; bir şeyi zayıflattı: onu zayıf kıldı.","otr":["Az yemek ve spor yapmamakla bedenini zayıflattı.","Düşman, ümmeti zayıflatmak için çabalıyor."],"r":null,"s":17,"y":[["مصدر","إِضْعاف"]],"f":"يُضْعِفُ إِضْعافاً"},
{"k":"أَضْنَى","c":"","m":"يُضْني إِضْناءً : أَتْعَبَ وَأَجْهَدَ ، “أَضْناهُ المَرَضُ وَكَثْرَةُ العَمَلِ” .","t":"أَتْعَبَ وَأَجْهَدَ","o":["أَضْناهُ المَرَضُ وَكَثْرَةُ العَمَلِ"],"b":["أَضْناهُ المَرَضُ وَكَثْرَةُ العَمَلِ","أَضْناهُ"],"tr":"bitkin düşürmek","ttr":"Yordu ve takatini kesti.","otr":["Hastalık ve çok çalışmak onu bitkin düşürdü."],"r":null,"s":17,"f":"يُضْني إِضْناءً"},
{"k":"إِطار","c":"إِطارات","m":"(ج) إِطارات : ما يُحيطُ بِالشَّيْءِ مِنْ خارِجِهِ ، “إِطارُ الصّورَةِ” ، “الإِطارُ الخارِجِيُّ لِلْعَجَلَةِ” .","t":"ما يُحيطُ بِالشَّيْءِ مِنْ خارِجِهِ","o":["إِطارُ الصّورَةِ","الإِطارُ الخارِجِيُّ لِلْعَجَلَةِ"],"b":["إِطارُ الصّورَةِ","إِطارُ"],"tr":"çerçeve; dış lastik","ttr":"Bir şeyi dışından çevreleyen şey.","otr":["resmin çerçevesi","tekerleğin dış lastiği"],"r":"p17_4","s":17,"y":[["جمع","إِطارات"]]},
{"k":"أَطاعَ","c":"","m":"يُطيعُ إِطاعَةً وَطاعَةً : انْقادَ ، فَعَلَ ما أُمِرَ بِهِ ، “أَطاعَ الابْنُ أَباهُ” ، ﴿ مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ ﴾ .","t":"انْقادَ ، فَعَلَ ما أُمِرَ بِهِ","o":["أَطاعَ الابْنُ أَباهُ","مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ"],"b":["أَطاعَ الابْنُ أَباهُ","أَطاعَ"],"tr":"itaat etmek","ttr":"Boyun eğdi; kendisine emredileni yaptı.","otr":["Oğul babasına itaat etti.","Kim Peygamber'e itaat ederse Allah'a itaat etmiş olur."],"r":null,"s":17},
{"k":"أَطاقَ","c":"","m":"يُطيقُ إِطاقَةً : قَدَرَ وَاحْتَمَلَ بِمَشَقَّةٍ ، “حَمَلَتِ الأُمُّ ما لا تُطيقُ حَمْلَهُ مِنْ أَجْلِ وَلَدِها” ، “هذا أَمْرٌ لا يُطاقُ” ، ﴿ وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ ﴾ .","t":"قَدَرَ وَاحْتَمَلَ بِمَشَقَّةٍ","o":["حَمَلَتِ الأُمُّ ما لا تُطيقُ حَمْلَهُ مِنْ أَجْلِ وَلَدِها","هذا أَمْرٌ لا يُطاقُ","وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ"],"b":["هذا أَمْرٌ لا يُطاقُ","يُطاقُ"],"tr":"güç yetirmek, katlanmak","ttr":"Zorlukla da olsa gücü yetti ve katlandı.","otr":["Anne, çocuğu için taşımaya gücü yetmeyeni taşıdı.","Bu dayanılmaz bir şey.","Ona (oruca) güçleri ancak zorlukla yetenlerin fidye vermesi gerekir."],"r":null,"s":17,"f":"يُطيقُ إِطاقَةً"},
{"k":"أَطالَ","c":"","m":"يُطيلُ إِطالَةً : مَدَّ وَزادَ ، “أَطالَ أَخي السَّفَرَ” .","t":"مَدَّ وَزادَ","o":["أَطالَ أَخي السَّفَرَ"],"b":["أَطالَ أَخي السَّفَرَ","أَطالَ"],"tr":"uzatmak","ttr":"Uzattı ve artırdı.","otr":["Kardeşim yolculuğu uzattı."],"r":null,"s":17,"f":"يُطيلُ إِطالَةً"},
{"k":"أَطْرَش","c":"طُرْش","m":"(ج) طُرْش : فاقِدُ السَّمْعِ ، “إِنَّهُ لا يَسْمَعُ ؛ فَهُوَ أَطْرَشُ” .","t":"فاقِدُ السَّمْعِ","o":["إِنَّهُ لا يَسْمَعُ ؛ فَهُوَ أَطْرَشُ"],"b":["إِنَّهُ لا يَسْمَعُ ؛ فَهُوَ أَطْرَشُ","أَطْرَشُ"],"tr":"sağır","ttr":"İşitme yetisini kaybetmiş.","otr":["O duymuyor; o sağırdır."],"r":null,"s":17},
{"k":"أَطْرَى","c":"","m":"يُطْري إِطْراءً : بالَغَ في المَدْحِ ، وَفي الحَديثِ : (لا تُطْروني كَما أَطْرَتِ النَّصارَى ابْنَ مَرْيَمَ فَإِنَّما أَنا عَبْدٌ فَقولوا عَبْدُ اللهِ وَرَسولُهُ) .","t":"بالَغَ في المَدْحِ","o":["لا تُطْروني كَما أَطْرَتِ النَّصارَى ابْنَ مَرْيَمَ فَإِنَّما أَنا عَبْدٌ فَقولوا عَبْدُ اللهِ وَرَسولُهُ"],"b":["لا تُطْروني كَما أَطْرَتِ النَّصارَى ابْنَ مَرْيَمَ","أَطْرَتِ"],"tr":"aşırı övmek","ttr":"Övmede aşırıya gitti.","otr":["Hıristiyanların Meryem oğlunu aşırı övdüğü gibi beni aşırı övmeyin; ben ancak bir kulum, 'Allah'ın kulu ve elçisi' deyin."],"r":null,"s":17,"f":"يُطْري إِطْراءً"},
{"k":"أَعْطَى","c":"","m":"يُعْطي إِعْطاءً: مَنَحَ وناوَلَ ووَهَبَ، “أَعْطَيْتُ أَخي أَلْفَ دينارٍ”، “أَعْطَتِ المُمَرِّضَةُ الدَّواءَ للمَريضِ”، “أَعْطِني مِمَّا أَعطاكَ اللهُ”، ﴿إِنَّا أَعْطَيْناكَ الْكَوْثَرَ﴾.","t":"مَنَحَ وناوَلَ ووَهَبَ","o":["أَعْطَيْتُ أَخي أَلْفَ دينارٍ","أَعْطَتِ المُمَرِّضَةُ الدَّواءَ للمَريضِ","أَعْطِني مِمَّا أَعطاكَ اللهُ","﴿إِنَّا أَعْطَيْناكَ الْكَوْثَرَ﴾"],"b":["أَعْطَيْتُ أَخي أَلْفَ دينارٍ","أَعْطَيْتُ"],"tr":"vermek","ttr":"Bağışlamak, uzatıp vermek, hibe etmek.","otr":["Kardeşime bin dinar verdim.","Hemşire hastaya ilacı verdi.","Allah'ın sana verdiğinden bana ver.","Şüphesiz biz sana Kevser'i verdik."],"r":"p22_1","s":22,"f":"يُعْطي إِعْطاءً"},
{"k":"أَعْظَمُ","c":"","m":"أَكْثَرُ عَظَمَةً؛ خِلافُ أَحْقَرَ وأَقَلَّ شَأْناً، “رَأَيْتُ اللهَ أَعْظَمَ كُلِّ شَيْءٍ”. ﴿الَّذينَ آمَنوا وهاجَروا وجاهَدوا في سَبيلِ اللهِ بِأَمْوالِهِمْ وأَنْفُسِهِمْ أَعْظَمُ دَرَجَةً عِنْدَ اللهِ﴾.","t":"أَكْثَرُ عَظَمَةً؛ خِلافُ أَحْقَرَ وأَقَلَّ شَأْناً","o":["رَأَيْتُ اللهَ أَعْظَمَ كُلِّ شَيْءٍ","﴿الَّذينَ آمَنوا وهاجَروا وجاهَدوا في سَبيلِ اللهِ بِأَمْوالِهِمْ وأَنْفُسِهِمْ أَعْظَمُ دَرَجَةً عِنْدَ اللهِ﴾"],"b":["رَأَيْتُ اللهَ أَعْظَمَ كُلِّ شَيْءٍ","أَعْظَمَ"],"tr":"en büyük, daha yüce","ttr":"Büyüklüğü daha fazla olan; daha değersiz ve daha önemsiz olanın zıddı.","otr":["Allah'ı her şeyden daha büyük gördüm.","İman edip hicret eden ve Allah yolunda mallarıyla ve canlarıyla cihad edenler, Allah katında derece bakımından daha büyüktür."],"r":null,"s":22},
{"k":"إِعْلام","c":"","m":"مَصْدَرُ أَعْلَمَ: النَّشْرُ بِواسِطَةِ الإِذاعَةِ والتِّلْفازِ والصَّحافَةِ وما شابَهَها. “تُشْرِفُ وِزارَةُ الإِعْلامِ عَلى وَسائِلِ الإِعْلامِ”.","t":"مَصْدَرُ أَعْلَمَ: النَّشْرُ بِواسِطَةِ الإِذاعَةِ والتِّلْفازِ والصَّحافَةِ وما شابَهَها","o":["تُشْرِفُ وِزارَةُ الإِعْلامِ عَلى وَسائِلِ الإِعْلامِ"],"b":["تُشْرِفُ وِزارَةُ الإِعْلامِ عَلى وَسائِلِ الإِعْلامِ","الإِعْلامِ"],"tr":"medya, bilgilendirme","ttr":"أعلم fiilinin mastarı: radyo, televizyon, basın ve benzerleri aracılığıyla yayın yapma.","otr":["Enformasyon (basın-yayın) bakanlığı medya organlarını denetler."],"r":null,"s":22},
{"k":"أَعْلَنَ","c":"","m":"يُعْلِنُ إِعْلاناً: أَظْهَرَ وصَرَّحَ وبَيَّنَ وأَذاعَ، خِلافُ أَخْفى، “أَعْلَنَ المُديرُ نَتائِجَ الاخْتِباراتِ”، ﴿رَبَّنا إِنَّكَ تَعْلَمُ ما نُخْفي وما نُعْلِنُ﴾.","t":"أَظْهَرَ وصَرَّحَ وبَيَّنَ وأَذاعَ، خِلافُ أَخْفى","o":["أَعْلَنَ المُديرُ نَتائِجَ الاخْتِباراتِ","﴿رَبَّنا إِنَّكَ تَعْلَمُ ما نُخْفي وما نُعْلِنُ﴾"],"b":["أَعْلَنَ المُديرُ نَتائِجَ الاخْتِباراتِ","أَعْلَنَ"],"tr":"ilan etmek","ttr":"Açığa vurmak, açıkça söylemek, açıklamak ve yaymak; gizlemenin zıddı.","otr":["Müdür sınav sonuçlarını açıkladı.","Rabbimiz! Şüphesiz sen gizlediğimizi de açığa vurduğumuzu da bilirsin."],"r":null,"s":22,"y":[["مصدر","إِعْلان"]],"f":"يُعْلِنُ إِعْلاناً"},
{"k":"أَعْلَى","c":"","m":"(مُؤ) عُلْيا: أَكْثَرُ عُلُوّاً وارْتِفاعاً، خِلافُ أَقَلَّ وأَخْفَض، “مَرْتَبَةُ الرَّئيسِ أَعْلى مِنْ مَرْتَبَةِ الوَزيرِ”، وفي الحَديثِ: (اليَدُ العُلْيا خَيْرٌ مِنَ اليَدِ السُّفْلى)، ﴿سَبِّحِ اسْمَ رَبِّكَ الأَعْلى﴾.","t":"أَكْثَرُ عُلُوّاً وارْتِفاعاً، خِلافُ أَقَلَّ وأَخْفَض","o":["مَرْتَبَةُ الرَّئيسِ أَعْلى مِنْ مَرْتَبَةِ الوَزيرِ","(اليَدُ العُلْيا خَيْرٌ مِنَ اليَدِ السُّفْلى)","﴿سَبِّحِ اسْمَ رَبِّكَ الأَعْلى﴾"],"b":["مَرْتَبَةُ الرَّئيسِ أَعْلى مِنْ مَرْتَبَةِ الوَزيرِ","أَعْلى"],"tr":"daha yüksek, en yüce","ttr":"(Müennesi: عُلْيا) Yüksekliği ve yüceliği daha fazla olan; daha az ve daha alçak olanın zıddı.","otr":["Cumhurbaşkanının makamı bakanın makamından daha yüksektir.","Hadiste: (Veren el, alan elden hayırlıdır.)","Yüce Rabbinin adını tesbih et."],"r":"p22_2","s":22},
{"k":"إِعْمار","c":"","m":"مَصْدَرُ أَعْمَرَ، أَعْمَرَ الدّارَ: بَناها وسَكَنَها أَو أَقامَ فيها، “يَهْتَمُّ المُسْلِمونَ بِإِعْمارِ المَساجِدِ”.","t":"مَصْدَرُ أَعْمَرَ، أَعْمَرَ الدّارَ: بَناها وسَكَنَها أَو أَقامَ فيها","o":["يَهْتَمُّ المُسْلِمونَ بِإِعْمارِ المَساجِدِ"],"b":["يَهْتَمُّ المُسْلِمونَ بِإِعْمارِ المَساجِدِ","بِإِعْمارِ"],"tr":"imar etmek, şenlendirme","ttr":"أعمر fiilinin mastarı; evi imar etmek: onu inşa etmek, içinde oturmak ya da ikamet etmek.","otr":["Müslümanlar camilerin imarına önem verir."],"r":null,"s":22},
{"k":"أَعْمَش","c":"","m":"ضَعيفُ البَصَرِ. “هذا الرَّجُلُ أَعْمَشُ لا يَرى جَيِّداً”.","t":"ضَعيفُ البَصَرِ","o":["هذا الرَّجُلُ أَعْمَشُ لا يَرى جَيِّداً"],"b":["هذا الرَّجُلُ أَعْمَشُ لا يَرى جَيِّداً","أَعْمَشُ"],"tr":"gözü zayıf","ttr":"Görme gücü zayıf.","otr":["Bu adamın gözü zayıf, iyi göremiyor."],"r":"p22_3","s":22},
{"k":"أَعْمَقُ","c":"","m":"أَكْثَرُ عُمْقاً، “بِئْرُ زَمْزَمَ أَعْمَقُ مِمَّا كانَتْ عَلَيْهِ في الماضي”، “المُحيطُ الهادِئُ أَعْمَقُ مِنَ البَحْرِ الأَحْمَرِ”.","t":"أَكْثَرُ عُمْقاً","o":["بِئْرُ زَمْزَمَ أَعْمَقُ مِمَّا كانَتْ عَلَيْهِ في الماضي","المُحيطُ الهادِئُ أَعْمَقُ مِنَ البَحْرِ الأَحْمَرِ"],"b":["المُحيطُ الهادِئُ أَعْمَقُ مِنَ البَحْرِ الأَحْمَرِ","أَعْمَقُ"],"tr":"daha derin","ttr":"Derinliği daha fazla olan.","otr":["Zemzem kuyusu geçmişte olduğundan daha derindir.","Pasifik Okyanusu Kızıldeniz'den daha derindir."],"r":null,"s":22},
{"k":"أَعْمَى","c":"عُمْيٌ","m":"(ج) عُمْيٌ. (مُؤ) عَمْياءُ: ضَريرٌ، الَّذي لا يُبْصِرُ. ﴿لَيْسَ عَلى الأَعْمى حَرَجٌ﴾.","t":"ضَريرٌ، الَّذي لا يُبْصِرُ","o":["﴿لَيْسَ عَلى الأَعْمى حَرَجٌ﴾"],"b":["﴿لَيْسَ عَلى الأَعْمى حَرَجٌ﴾","الأَعْمى"],"tr":"kör, âmâ","ttr":"Görme engelli; göremeyen kimse.","otr":["Köre bir güçlük (vebal) yoktur."],"r":"p22_4","s":22},
{"k":"أَعْوَر","c":"عُور","m":"(ج) عُورٌ: مَنْ ذَهَبَ بَصَرُ إِحْدى عَيْنَيْهِ، “أَصابَ المَرَضُ إِحْدى عَيْنَيْهِ؛ فَأَصْبَحَ أَعْوَرَ”.","t":"مَنْ ذَهَبَ بَصَرُ إِحْدى عَيْنَيْهِ","o":["أَصابَ المَرَضُ إِحْدى عَيْنَيْهِ؛ فَأَصْبَحَ أَعْوَرَ"],"b":["أَصابَ المَرَضُ إِحْدى عَيْنَيْهِ؛ فَأَصْبَحَ أَعْوَرَ","أَعْوَرَ"],"tr":"tek gözlü","ttr":"Gözlerinden birinin görmesi gitmiş kimse.","otr":["Hastalık gözlerinden birine isabet etti, böylece tek gözlü kaldı."],"r":"p22_5","s":22},
{"k":"أَغاثَ","c":"","m":"يُغيثُ إِغاثَةً: أَعانَ ونَصَرَ، “أَغاثَ المُسْلِمونَ إِخْوانَهُمْ في الدّينِ”، “يَعْمَلُ مُحَمَّدٌ في وَكالَةِ الإِغاثَةِ الإِسْلامِيَّةِ”.","t":"أَعانَ ونَصَرَ","o":["أَغاثَ المُسْلِمونَ إِخْوانَهُمْ في الدّينِ","يَعْمَلُ مُحَمَّدٌ في وَكالَةِ الإِغاثَةِ الإِسْلامِيَّةِ"],"b":["أَغاثَ المُسْلِمونَ إِخْوانَهُمْ في الدّينِ","أَغاثَ"],"tr":"yardıma koşmak","ttr":"Yardım etmek ve destek olmak.","otr":["Müslümanlar din kardeşlerinin yardımına koştu.","Muhammed İslami Yardım Ajansında çalışıyor."],"r":"p22_6","s":22,"f":"يُغيثُ إِغاثَةً"},
{"k":"أَغارَ","c":"","m":"يُغيرُ إِغارَةً: هَجَمَ عَلى، “أَغارَ اللُّصوصُ عَلى قافِلَةِ المُسافِرينَ”.","t":"هَجَمَ عَلى","o":["أَغارَ اللُّصوصُ عَلى قافِلَةِ المُسافِرينَ"],"b":["أَغارَ اللُّصوصُ عَلى قافِلَةِ المُسافِرينَ","أَغارَ"],"tr":"baskın yapmak","ttr":"Saldırmak, hücum etmek.","otr":["Hırsızlar yolcu kervanına baskın yaptı."],"r":"p22_7","s":22,"f":"يُغيرُ إِغارَةً"},
{"k":"أَغْرَى","c":"","m":"يُغْري إِغْراءً: حَرَّضَ، دَفَعَ، “أَغْراهُ صاحِبُ السُّوءِ بِفِعْلِ الفاحِشَةِ”، ﴿لَنُغْرِيَنَّكَ بِهِمْ ثُمَّ لا يُجاوِرُونَكَ فيها إِلَّا قَليلاً﴾.","t":"حَرَّضَ، دَفَعَ","o":["أَغْراهُ صاحِبُ السُّوءِ بِفِعْلِ الفاحِشَةِ","﴿لَنُغْرِيَنَّكَ بِهِمْ ثُمَّ لا يُجاوِرُونَكَ فيها إِلَّا قَليلاً﴾"],"b":["أَغْراهُ صاحِبُ السُّوءِ بِفِعْلِ الفاحِشَةِ","أَغْراهُ"],"tr":"kışkırtmak, ayartmak","ttr":"Kışkırtmak, itmek.","otr":["Kötü arkadaşı onu çirkin bir iş yapmaya ayarttı.","Seni onlara karşı mutlaka harekete geçiririz; sonra orada seninle ancak az bir süre komşu kalabilirler."],"r":null,"s":23,"f":"يُغْري إِغْراءً"},
{"k":"أَغْضَبَ","c":"","m":"يُغْضِبُ إِغْضاباً: أَسْخَطَ، “أَغْضَبَ بَدْرٌ موسى بِكَلامِهِ السَّيِّئِ”، “لا تُغْضِبْ والِدَيْكَ، فَإِنَّ اللهَ لا يَرْضى ذلِكَ مِنْكَ”.","t":"أَسْخَطَ","o":["أَغْضَبَ بَدْرٌ موسى بِكَلامِهِ السَّيِّئِ","لا تُغْضِبْ والِدَيْكَ، فَإِنَّ اللهَ لا يَرْضى ذلِكَ مِنْكَ"],"b":["لا تُغْضِبْ والِدَيْكَ، فَإِنَّ اللهَ لا يَرْضى ذلِكَ مِنْكَ","تُغْضِبْ"],"tr":"kızdırmak","ttr":"Öfkelendirmek, hoşnutsuz etmek.","otr":["Bedir kötü sözleriyle Musa'yı kızdırdı.","Anne babanı kızdırma; çünkü Allah bundan razı olmaz."],"r":null,"s":23,"y":[["مصدر","إِغْضاب"]],"f":"يُغْضِبُ إِغْضاباً"},
{"k":"أَغْلَبُ","c":"","m":"أَكْثَرُ، مُعْظَمُ، “أَغْلَبُ الطُّلّابِ في هذِهِ المَدْرَسَةِ مِنْ صِغارِ السِّنِّ”، “السُّرْعَةُ الزّائِدَةُ سَبَبُ حَوادِثِ المُرورِ في أَغْلَبِ الأَحْيانِ”.","t":"أَكْثَرُ، مُعْظَمُ","o":["أَغْلَبُ الطُّلّابِ في هذِهِ المَدْرَسَةِ مِنْ صِغارِ السِّنِّ","السُّرْعَةُ الزّائِدَةُ سَبَبُ حَوادِثِ المُرورِ في أَغْلَبِ الأَحْيانِ"],"b":["السُّرْعَةُ الزّائِدَةُ سَبَبُ حَوادِثِ المُرورِ في أَغْلَبِ الأَحْيانِ","أَغْلَبِ"],"tr":"çoğu, ekseriyet","ttr":"Daha çok olan; büyük kısım.","otr":["Bu okuldaki öğrencilerin çoğu küçük yaştadır.","Aşırı hız çoğu zaman trafik kazalarının sebebidir."],"r":null,"s":23},
{"k":"أَغْلَى","c":"","m":"أَكْثَرُ غَلاءً؛ خِلافُ أَرْخَصَ، “الذَّهَبُ أَغْلى مِنَ الفِضَّةِ”، “السَّفَرُ بِالجَوِّ أَغْلى مِنَ السَّفَرِ بِالبَحْرِ”.","t":"أَكْثَرُ غَلاءً؛ خِلافُ أَرْخَصَ","o":["الذَّهَبُ أَغْلى مِنَ الفِضَّةِ","السَّفَرُ بِالجَوِّ أَغْلى مِنَ السَّفَرِ بِالبَحْرِ"],"b":["الذَّهَبُ أَغْلى مِنَ الفِضَّةِ","أَغْلى"],"tr":"daha pahalı","ttr":"Pahalılığı daha fazla olan; daha ucuzun zıddı.","otr":["Altın gümüşten daha pahalıdır.","Hava yoluyla yolculuk deniz yoluyla yolculuktan daha pahalıdır."],"r":"p23_1","s":23},
{"k":"أَغْلَقَ","c":"","m":"يُغْلِقُ إِغْلاقاً: أَقْفَلَ ومَنَعَ؛ خِلافُ فَتَحَ، “أَغْلِقِ البابَ يا عَلِيُّ”، “أَغْلَقَ الجَيْشُ الحُدودَ”.","t":"أَقْفَلَ ومَنَعَ؛ خِلافُ فَتَحَ","o":["أَغْلِقِ البابَ يا عَلِيُّ","أَغْلَقَ الجَيْشُ الحُدودَ"],"b":["أَغْلَقَ الجَيْشُ الحُدودَ","أَغْلَقَ"],"tr":"kapatmak","ttr":"Kilitlemek ve engellemek; açmanın zıddı.","otr":["Kapıyı kapat ey Ali.","Ordu sınırları kapattı."],"r":"p23_2","s":23,"y":[["مصدر","إِغْلاق"]],"f":"يُغْلِقُ إِغْلاقاً"},
{"k":"أَغْمَضَ","c":"","m":"يُغْمِضُ إِغْماضاً: (١) أَطْبَقَ جَفْنَيْهِ، “أَغْمَضَ الطِّفْلُ عَيْنَيْهِ”. (٢) تَساهَلَ وتَسامَحَ، ﴿وَلَسْتُمْ بِآخِذيهِ إِلَّا أَنْ تُغْمِضوا فيهِ﴾.","t":"(١) أَطْبَقَ جَفْنَيْهِ (٢) تَساهَلَ وتَسامَحَ","o":["أَغْمَضَ الطِّفْلُ عَيْنَيْهِ","﴿وَلَسْتُمْ بِآخِذيهِ إِلَّا أَنْ تُغْمِضوا فيهِ﴾"],"b":["أَغْمَضَ الطِّفْلُ عَيْنَيْهِ","أَغْمَضَ"],"tr":"gözünü kapamak","ttr":"(1) Göz kapaklarını kapatmak. (2) Göz yummak, hoşgörülü davranmak.","otr":["Çocuk gözlerini kapadı.","Siz de göz yummadıkça onu almazdınız."],"r":"p23_3","s":23,"f":"يُغْمِضُ إِغْماضاً"},
{"k":"أُغْمِيَ","c":"","m":"يُغْمى (عَلَيْهِ) إِغْماءً: فَقَدَ الحِسَّ والحَرَكَةَ بِسَبَبِ مَرَضٍ أَو حادِثٍ عارِضٍ؛ خِلافُ أَفاقَ، “أُغْمِيَ عَلى المَريضِ في أَثْناءِ نَقْلِهِ إِلى المُسْتَشْفى”، “نَزَفَ الجَريحُ كَثيراً مِنَ الدَّمِ؛ فَأُغْمِيَ عَلَيْهِ”.","t":"فَقَدَ الحِسَّ والحَرَكَةَ بِسَبَبِ مَرَضٍ أَو حادِثٍ عارِضٍ؛ خِلافُ أَفاقَ","o":["أُغْمِيَ عَلى المَريضِ في أَثْناءِ نَقْلِهِ إِلى المُسْتَشْفى","نَزَفَ الجَريحُ كَثيراً مِنَ الدَّمِ؛ فَأُغْمِيَ عَلَيْهِ"],"b":["نَزَفَ الجَريحُ كَثيراً مِنَ الدَّمِ؛ فَأُغْمِيَ عَلَيْهِ","فَأُغْمِيَ"],"tr":"bayılmak","ttr":"Bir hastalık ya da ani bir olay sebebiyle duyu ve hareketini kaybetmek; ayılmanın zıddı.","otr":["Hasta hastaneye taşınırken bayıldı.","Yaralı çok kan kaybetti ve bayıldı."],"r":"p23_4","s":23},
{"k":"أَغْنَى","c":"","m":"يُغْني إِغْناءً: جَعَلَهُ غَنِيّاً، “أَعْطى الغَنِيُّ الفَقيرَ مالاً فَأَغْناهُ عَنِ السُّؤالِ”، ﴿وَوَجَدَكَ عائِلاً فَأَغْنى﴾.","t":"جَعَلَهُ غَنِيّاً","o":["أَعْطى الغَنِيُّ الفَقيرَ مالاً فَأَغْناهُ عَنِ السُّؤالِ","﴿وَوَجَدَكَ عائِلاً فَأَغْنى﴾"],"b":["أَعْطى الغَنِيُّ الفَقيرَ مالاً فَأَغْناهُ عَنِ السُّؤالِ","فَأَغْناهُ"],"tr":"zengin etmek","ttr":"Onu zengin kılmak.","otr":["Zengin fakire para verdi ve onu dilenmekten kurtardı.","Seni fakir buldu da zengin etmedi mi?"],"r":null,"s":23,"f":"يُغْني إِغْناءً"},
{"k":"أَغْيَرُ","c":"","m":"أَكْثَرُ غَيْرَةً، “المُسْلِمُ أَغْيَرُ عَلى أَهْلِهِ مِنَ الآخَرينَ”، وفي الحَديثِ: (لا أَحَدَ أَغْيَرُ مِنَ اللهِ).","t":"أَكْثَرُ غَيْرَةً","o":["المُسْلِمُ أَغْيَرُ عَلى أَهْلِهِ مِنَ الآخَرينَ","(لا أَحَدَ أَغْيَرُ مِنَ اللهِ)"],"b":["المُسْلِمُ أَغْيَرُ عَلى أَهْلِهِ مِنَ الآخَرينَ","أَغْيَرُ"],"tr":"daha kıskanç (gayretli)","ttr":"Gayreti (namus kıskançlığı) daha fazla olan.","otr":["Müslüman ailesini başkalarından daha çok kıskanır (korur).","Hadiste: (Allah'tan daha gayretli kimse yoktur.)"],"r":null,"s":23},
{"k":"أُفٍّ","c":"","m":"كَلِمَةٌ يُرادُ مِنْها التَّضَجُّرُ والتَّعْبيرُ عَنْ عَدَمِ الرِّضى، ﴿فَلا تَقُلْ لَهُما أُفٍّ﴾، ﴿أُفٍّ لَكُمْ وَلِما تَعْبُدونَ مِنْ دونِ اللهِ﴾.","t":"كَلِمَةٌ يُرادُ مِنْها التَّضَجُّرُ والتَّعْبيرُ عَنْ عَدَمِ الرِّضى","o":["﴿فَلا تَقُلْ لَهُما أُفٍّ﴾","﴿أُفٍّ لَكُمْ وَلِما تَعْبُدونَ مِنْ دونِ اللهِ﴾"],"b":["﴿فَلا تَقُلْ لَهُما أُفٍّ﴾","أُفٍّ"],"tr":"öf!","ttr":"Bıkkınlık ve hoşnutsuzluğu ifade etmek için söylenen bir kelime.","otr":["Onlara 'öf' bile deme.","Yazıklar olsun size ve Allah'ı bırakıp taptıklarınıza!"],"r":null,"s":23},
{"k":"أَفادَ","c":"","m":"يُفيدُ إِفادَةً وفائِدَةً: أَكْسَبَ ونَفَعَ، “أَفادَ مُحَمَّدٌ عَلِيّاً بِعِلْمِهِ”، “العِلْمُ الَّذي دَرَسَهُ في الصِّغَرِ أَفادَهُ في الكِبَرِ”.","t":"أَكْسَبَ ونَفَعَ","o":["أَفادَ مُحَمَّدٌ عَلِيّاً بِعِلْمِهِ","العِلْمُ الَّذي دَرَسَهُ في الصِّغَرِ أَفادَهُ في الكِبَرِ"],"b":["العِلْمُ الَّذي دَرَسَهُ في الصِّغَرِ أَفادَهُ في الكِبَرِ","أَفادَهُ"],"tr":"fayda vermek","ttr":"Kazandırmak ve faydalı olmak.","otr":["Muhammed bilgisiyle Ali'ye fayda sağladı.","Küçükken öğrendiği ilim büyüyünce ona fayda verdi."],"r":null,"s":23},
{"k":"أَفاضَ","c":"","m":"يُفيضُ إِفاضَةً: (١) تَوَسَّعَ في الكَلامِ وفَصَّلَ، “أَفاضَ الخَطيبُ في عَرْضِ المَوْضوعِ”. (٢) في الحَجِّ: انْصَرَفَ إِلى المُزْدَلِفَةِ مِنْ عَرَفاتٍ، ﴿ثُمَّ أَفيضوا مِنْ حَيْثُ أَفاضَ النّاسُ واسْتَغْفِروا اللهَ﴾، ﴿فَإِذا أَفَضْتُمْ مِنْ عَرَفاتٍ فَاذْكُروا اللهَ عِنْدَ المَشْعَرِ الحَرامِ﴾.","t":"(١) تَوَسَّعَ في الكَلامِ وفَصَّلَ (٢) في الحَجِّ: انْصَرَفَ إِلى المُزْدَلِفَةِ مِنْ عَرَفاتٍ","o":["أَفاضَ الخَطيبُ في عَرْضِ المَوْضوعِ","﴿ثُمَّ أَفيضوا مِنْ حَيْثُ أَفاضَ النّاسُ واسْتَغْفِروا اللهَ﴾","﴿فَإِذا أَفَضْتُمْ مِنْ عَرَفاتٍ فَاذْكُروا اللهَ عِنْدَ المَشْعَرِ الحَرامِ﴾"],"b":["أَفاضَ الخَطيبُ في عَرْضِ المَوْضوعِ","أَفاضَ"],"tr":"uzun uzun anlatmak; Arafat'tan inmek","ttr":"(1) Sözü genişletip ayrıntılı anlatmak. (2) Hacda: Arafat'tan Müzdelife'ye doğru ayrılmak.","otr":["Hatip konuyu anlatırken ayrıntıya girdi.","Sonra insanların akın ettiği yerden siz de akın edin ve Allah'tan bağışlanma dileyin.","Arafat'tan akın ettiğinizde Meş'ar-i Haram'ın yanında Allah'ı anın."],"r":null,"s":23,"f":"يُفيضُ إِفاضَةً"},
{"k":"أَفاقَ","c":"","m":"يُفيقُ إِفاقَةً: عادَ إِلى طَبيعَتِهِ بَعْدَ أَنْ أُغْمِيَ عَلَيْهِ، أَو بَعْدَ أَنْ كانَ سَكْرانَ، “أَفاقَ الرَّجُلُ الَّذي أُغْمِيَ عَلَيْهِ في المُسْتَشْفى”، ﴿فَلَمّا أَفاقَ قالَ سُبْحانَكَ﴾.","t":"عادَ إِلى طَبيعَتِهِ بَعْدَ أَنْ أُغْمِيَ عَلَيْهِ، أَو بَعْدَ أَنْ كانَ سَكْرانَ","o":["أَفاقَ الرَّجُلُ الَّذي أُغْمِيَ عَلَيْهِ في المُسْتَشْفى","﴿فَلَمّا أَفاقَ قالَ سُبْحانَكَ﴾"],"b":["أَفاقَ الرَّجُلُ الَّذي أُغْمِيَ عَلَيْهِ في المُسْتَشْفى","أَفاقَ"],"tr":"ayılmak, kendine gelmek","ttr":"Bayıldıktan ya da sarhoşken sonra normal hâline dönmek.","otr":["Hastanede bayılan adam kendine geldi.","Kendine gelince 'Seni tesbih ederim' dedi."],"r":null,"s":23,"f":"يُفيقُ إِفاقَةً"},
{"k":"أَفْتَى","c":"","m":"يُفْتي إِفْتاءً: (١) أَفْتَى في المَسْأَلَة: أَبانَ الحُكْمَ فيها شَرْعاً، في الحَديث: (مَنْ أُفْتيَ بِفُتْيا غَيْرِ ثَبْتٍ، فَإِنَّما إِثْمُهُ عَلَى مَنْ أَفْتاه). (٢) تَعبيرُ الرُّؤْيا، ﴿يا أَيُّها الْمَلأُ أَفْتُوني في رُؤْيايَ﴾.","t":"(١) أَفْتَى في المَسْأَلَة: أَبانَ الحُكْمَ فيها شَرْعاً (٢) تَعبيرُ الرُّؤْيا","o":["(مَنْ أُفْتيَ بِفُتْيا غَيْرِ ثَبْتٍ، فَإِنَّما إِثْمُهُ عَلَى مَنْ أَفْتاه)","﴿يا أَيُّها الْمَلأُ أَفْتُوني في رُؤْيايَ﴾"],"b":["يا أَيُّها الْمَلأُ أَفْتُوني في رُؤْيايَ","أَفْتُوني"],"tr":"fetva vermek","ttr":"(1) Bir meselede fetva verdi: onun dini hükmünü açıkladı. (2) Rüya yorumlamak.","otr":["Hadiste: (Kim sağlam olmayan bir fetvayla fetva verilirse, onun günahı ona fetva verenin üzerinedir.)","Ey ileri gelenler, rüyam hakkında bana fetva (yorum) verin!"],"r":null,"s":24,"y":[["مصدر","إِفْتاء"]],"f":"يُفْتي إِفْتاءً"},
{"k":"أَفْحَشَ","c":"","m":"يُفْحِشُ إِفْحاشاً: جاءَ بِالقَوْلِ أَوِ العَمَلِ القَبيحِ، “لا تُفْحِشْ في قَوْلِكَ”.","t":"جاءَ بِالقَوْلِ أَوِ العَمَلِ القَبيحِ","o":["لا تُفْحِشْ في قَوْلِكَ"],"b":["لا تُفْحِشْ في قَوْلِكَ","تُفْحِشْ"],"tr":"çirkin söz/iş yapmak","ttr":"Çirkin bir söz ya da iş ortaya koydu.","otr":["Sözünde edepsizlik etme."],"r":null,"s":24,"f":"يُفْحِشُ إِفْحاشاً"},
{"k":"أَفْرَجَ","c":"","m":"يُفْرِجُ إِفْراجاً: أَطْلَقَ؛ خِلافُ حَبَسَ أَو قَيَّدَ، “أَفْرَجَ رِجالُ الأَمْنِ عَنْ أَحَدِ المُعتَقَلينَ”.","t":"أَطْلَقَ؛ خِلافُ حَبَسَ أَو قَيَّدَ","o":["أَفْرَجَ رِجالُ الأَمْنِ عَنْ أَحَدِ المُعتَقَلينَ"],"b":["أَفْرَجَ رِجالُ الأَمْنِ عَنْ أَحَدِ المُعتَقَلينَ","أَفْرَجَ"],"tr":"serbest bırakmak","ttr":"Serbest bıraktı; hapsetmenin ya da bağlamanın zıddı.","otr":["Güvenlik görevlileri tutuklulardan birini serbest bıraktı."],"r":"p24_1","s":24,"f":"يُفْرِجُ إِفْراجاً"},
{"k":"أَفْرَطَ","c":"","m":"يُفْرِطُ إِفْراطاً: جاوَزَ الحَدَّ في القَوْلِ أَوِ الفِعْلِ، “أَفْرَطَ الصَّديقُ في لَوْمِ صاحِبِهِ”، “الإِسْلامُ يَدعو إِلى الاعْتِدالِ في كُلِّ شَيْءٍ، فَلا إِفْراطَ وَلا تَفْريطَ”.","t":"جاوَزَ الحَدَّ في القَوْلِ أَوِ الفِعْلِ","o":["أَفْرَطَ الصَّديقُ في لَوْمِ صاحِبِهِ","الإِسْلامُ يَدعو إِلى الاعْتِدالِ في كُلِّ شَيْءٍ، فَلا إِفْراطَ وَلا تَفْريطَ"],"b":["أَفْرَطَ الصَّديقُ في لَوْمِ صاحِبِهِ","أَفْرَطَ"],"tr":"aşırı gitmek","ttr":"Sözde ya da işte haddi aştı.","otr":["Arkadaş, dostunu kınamakta aşırı gitti.","İslam her şeyde ölçülü olmaya çağırır; ne aşırılık vardır ne de ihmal."],"r":null,"s":24,"y":[["مصدر","إِفْراط"]],"f":"يُفْرِطُ إِفْراطاً"},
{"k":"أَفْرَغَ","c":"","m":"يُفْرِغُ إِفْراغاً: (١) أَخْلَى، “أَفْرَغَ رِجالُ الأَمْنِ الشّارِعَ مِنَ المُتَظاهِرينَ”. (٢) صَبَّ، “أَفْرَغَ الإِناءَ مِنَ الماءِ”.","t":"(١) أَخْلَى (٢) صَبَّ","o":["أَفْرَغَ رِجالُ الأَمْنِ الشّارِعَ مِنَ المُتَظاهِرينَ","أَفْرَغَ الإِناءَ مِنَ الماءِ"],"b":["أَفْرَغَ رِجالُ الأَمْنِ الشّارِعَ مِنَ المُتَظاهِرينَ","أَفْرَغَ"],"tr":"boşaltmak; dökmek","ttr":"(1) Boşalttı. (2) Döktü.","otr":["Güvenlik görevlileri sokağı göstericilerden boşalttı.","Kaptaki suyu boşalttı."],"r":"p24_2","s":24,"f":"يُفْرِغُ إِفْراغاً"},
{"k":"أَفْزَعَ","c":"","m":"يُفْزِعُ إِفْزاعاً: أَخافَ، “أَفْزَعَ صَوْتُ الطّائِرَةِ الأَطْفالَ”.","t":"أَخافَ","o":["أَفْزَعَ صَوْتُ الطّائِرَةِ الأَطْفالَ"],"b":["أَفْزَعَ صَوْتُ الطّائِرَةِ الأَطْفالَ","أَفْزَعَ"],"tr":"korkutmak","ttr":"Korkuttu.","otr":["Uçağın sesi çocukları korkuttu."],"r":null,"s":24,"f":"يُفْزِعُ إِفْزاعاً"},
{"k":"أَفْسَدَ","c":"","m":"يُفْسِدُ إِفْساداً: خِلافُ أَصْلَحَ، “وَضَعَ كَثيراً مِنَ المِلْحِ في الإِناءِ؛ فَأَفْسَدَ الطَّعامَ”، ﴿وَلا تُفْسِدُوا فِي الأَرْضِ بَعْدَ إِصْلاحِها﴾.","t":"خِلافُ أَصْلَحَ","o":["وَضَعَ كَثيراً مِنَ المِلْحِ في الإِناءِ؛ فَأَفْسَدَ الطَّعامَ","﴿وَلا تُفْسِدُوا فِي الأَرْضِ بَعْدَ إِصْلاحِها﴾"],"b":["وَضَعَ كَثيراً مِنَ المِلْحِ في الإِناءِ؛ فَأَفْسَدَ الطَّعامَ","فَأَفْسَدَ"],"tr":"bozmak","ttr":"Düzeltmenin zıddı; bozdu.","otr":["Kaba çok tuz koydu ve yemeği bozdu.","Islah edildikten sonra yeryüzünde bozgunculuk yapmayın."],"r":null,"s":24,"f":"يُفْسِدُ إِفْساداً"},
{"k":"أَفْشَى","c":"","m":"يُفْشي إِفْشاءً: نَشَرَ وَأَذاعَ، “أَفْشَى أَحَدُ الأَعْضاءِ السِّرَّ، فَعَلِمَ النّاسُ بِهِ”. وَفي الحَديث: (أَلا أَدُلُّكُم عَلَى شَيْءٍ إِذا فَعَلْتُموهُ تَحابَبْتُم؛ أَفْشوا السَّلامَ بَيْنَكُم).","t":"نَشَرَ وَأَذاعَ","o":["أَفْشَى أَحَدُ الأَعْضاءِ السِّرَّ، فَعَلِمَ النّاسُ بِهِ","(أَلا أَدُلُّكُم عَلَى شَيْءٍ إِذا فَعَلْتُموهُ تَحابَبْتُم؛ أَفْشوا السَّلامَ بَيْنَكُم)"],"b":["أَفْشَى أَحَدُ الأَعْضاءِ السِّرَّ، فَعَلِمَ النّاسُ بِهِ","أَفْشَى"],"tr":"yaymak, ifşa etmek","ttr":"Yaydı ve duyurdu.","otr":["Üyelerden biri sırrı ifşa etti, insanlar da onu öğrendi.","Hadiste: (Size, yaptığınızda birbirinizi seveceğiniz bir şeyi göstereyim mi? Aranızda selamı yayın.)"],"r":null,"s":24,"y":[["مصدر","إِفْشاء"]],"f":"يُفْشي إِفْشاءً"},
{"k":"أَفْصَحَ","c":"","m":"يُفْصِحُ إِفْصاحاً: أَظْهَرَ، بَيَّنَ؛ خِلافُ كَتَمَ. “أَفْصَحَ عَنْ كَثيرٍ مِنَ الأَسْرارِ الَّتي كانَ يَكْتُمُها”.","t":"أَظْهَرَ، بَيَّنَ؛ خِلافُ كَتَمَ","o":["أَفْصَحَ عَنْ كَثيرٍ مِنَ الأَسْرارِ الَّتي كانَ يَكْتُمُها"],"b":["أَفْصَحَ عَنْ كَثيرٍ مِنَ الأَسْرارِ الَّتي كانَ يَكْتُمُها","أَفْصَحَ"],"tr":"açığa vurmak","ttr":"Açığa çıkardı, açıkladı; gizlemenin zıddı.","otr":["Sakladığı sırların birçoğunu açığa vurdu."],"r":null,"s":24,"f":"يُفْصِحُ إِفْصاحاً"},
{"k":"أَفْضَلُ","c":"أَفاضِل","m":"(ج) أَفاضِل: أَكْثَرُ فَضْلاً؛ أَحْسَنُ، “الذَّهابُ إِلى المَكْتَبَةِ وَالقِراءَةُ فيها أَفْضَلُ مِنَ الجُلوسِ في البَيْتِ”، “عَلِيٌّ أَفْضَلُ الطُّلّابِ أَدَباً في صَفِّهِ”.","t":"أَكْثَرُ فَضْلاً؛ أَحْسَنُ","o":["الذَّهابُ إِلى المَكْتَبَةِ وَالقِراءَةُ فيها أَفْضَلُ مِنَ الجُلوسِ في البَيْتِ","عَلِيٌّ أَفْضَلُ الطُّلّابِ أَدَباً في صَفِّهِ"],"b":["عَلِيٌّ أَفْضَلُ الطُّلّابِ أَدَباً في صَفِّهِ","أَفْضَلُ"],"tr":"daha üstün, en iyi","ttr":"Fazileti daha çok olan; daha güzel.","otr":["Kütüphaneye gidip orada okumak evde oturmaktan daha iyidir.","Ali, sınıfında ahlakça öğrencilerin en üstünüdür."],"r":null,"s":24},
{"k":"أَفْطَرَ","c":"","m":"يُفْطِرُ إِفْطاراً: (١) تَناوَلَ وَجْبَةَ الصَّباحِ، “مَتَى تُفْطِرُ عادَةً؟” (٢) تَناوَلَ الطَّعامَ عِنْدَ غُروبِ الشَّمْسِ في الصَّوْمِ، “أُفْطِرُ في رَمَضانَ عَلَى تَمَراتٍ”. (٣) أَفْسَدَ صِيامَهُ، وَفي الحَديث: (أَفْطَرَ الحاجِمُ وَالمَحْجومُ).","t":"(١) تَناوَلَ وَجْبَةَ الصَّباحِ (٢) تَناوَلَ الطَّعامَ عِنْدَ غُروبِ الشَّمْسِ في الصَّوْمِ (٣) أَفْسَدَ صِيامَهُ","o":["مَتَى تُفْطِرُ عادَةً؟","أُفْطِرُ في رَمَضانَ عَلَى تَمَراتٍ","(أَفْطَرَ الحاجِمُ وَالمَحْجومُ)"],"b":["أُفْطِرُ في رَمَضانَ عَلَى تَمَراتٍ","أُفْطِرُ"],"tr":"kahvaltı etmek; iftar etmek","ttr":"(1) Sabah yemeğini yedi. (2) Oruçta güneş batınca yemek yedi. (3) Orucunu bozdu.","otr":["Genellikle ne zaman kahvaltı edersin?","Ramazanda birkaç hurmayla iftar ederim.","Hadiste: (Hacamat yapan da yaptıran da orucunu bozmuştur.)"],"r":null,"s":24,"y":[["مصدر","إِفْطار"]],"f":"يُفْطِرُ إِفْطاراً"},
{"k":"أَفْعَى","c":"أَفاعٍ (الأَفاعي)","m":"(ج) أَفاعٍ (الأَفاعي): ثُعْبانٌ أَو حَيَّةٌ. “رَأَيْتُ الأَفْعَى تَأْكُلُ عُصْفوراً”.","t":"ثُعْبانٌ أَو حَيَّةٌ","o":["رَأَيْتُ الأَفْعَى تَأْكُلُ عُصْفوراً"],"b":["رَأَيْتُ الأَفْعَى تَأْكُلُ عُصْفوراً","الأَفْعَى"],"tr":"engerek, yılan","ttr":"Büyük yılan ya da yılan.","otr":["Yılanın bir serçe yediğini gördüm."],"r":"p24_3","s":24,"y":[["جمع","أَفاعٍ"]]},
{"k":"أُفُق","c":"آفاق","m":"(ج) آفاق: خَطٌّ دائِرِيٌّ يَرَى فيهِ المُشاهِدُ السَّماءَ كَأَنَّها مُتَّصِلَةٌ بِالأَرْضِ، “رَأَيْتُ الهِلالَ في الأُفُقِ”.","t":"خَطٌّ دائِرِيٌّ يَرَى فيهِ المُشاهِدُ السَّماءَ كَأَنَّها مُتَّصِلَةٌ بِالأَرْضِ","o":["رَأَيْتُ الهِلالَ في الأُفُقِ"],"b":["رَأَيْتُ الهِلالَ في الأُفُقِ","الأُفُقِ"],"tr":"ufuk","ttr":"Bakanın, gökyüzünü yere bitişikmiş gibi gördüğü dairesel çizgi.","otr":["Hilali ufukta gördüm."],"r":"p24_4","s":24},
{"k":"أَفْقَدَ","c":"","m":"يُفْقِدُ إِفْقاداً: جَعَلَهُ يَفْقِدُ الشَّيْءَ، “سَمِعَ كَلاماً قَبيحاً، أَفْقَدَهُ أَعْصابَهُ”.","t":"جَعَلَهُ يَفْقِدُ الشَّيْءَ","o":["سَمِعَ كَلاماً قَبيحاً، أَفْقَدَهُ أَعْصابَهُ"],"b":["سَمِعَ كَلاماً قَبيحاً، أَفْقَدَهُ أَعْصابَهُ","أَفْقَدَهُ"],"tr":"kaybettirmek","ttr":"Onun bir şeyi kaybetmesine yol açtı.","otr":["Çirkin bir söz işitti; bu onu sinirlendirdi (sinirlerini kaybettirdi)."],"r":null,"s":24,"f":"يُفْقِدُ إِفْقاداً"},
{"k":"أَفْقَرُ","c":"","m":"أَكْثَرُ فَقْراً؛ خِلافُ أَغْنَى، “كانَ غَنِيّاً، لَكِنَّهُ أَصْبَحَ مِنْ أَفْقَرِ النّاسِ، بِسَبَبِ المَيْسِرِ وَالرِّبا”.","t":"أَكْثَرُ فَقْراً؛ خِلافُ أَغْنَى","o":["كانَ غَنِيّاً، لَكِنَّهُ أَصْبَحَ مِنْ أَفْقَرِ النّاسِ، بِسَبَبِ المَيْسِرِ وَالرِّبا"],"b":["كانَ غَنِيّاً، لَكِنَّهُ أَصْبَحَ مِنْ أَفْقَرِ النّاسِ، بِسَبَبِ المَيْسِرِ وَالرِّبا","أَفْقَرِ"],"tr":"daha fakir","ttr":"Daha yoksul; daha zenginin zıddı.","otr":["Zengindi, ama kumar ve faiz yüzünden insanların en fakirlerinden biri oldu."],"r":null,"s":24},
{"k":"أَفْلَتَ","c":"","m":"يُفْلِتُ إِفْلاتاً: نَجا وَتَخَلَّصَ، “أَفْلَتَ المُجْرِمُ مِنَ العِقابِ، حَيْثُ لَمْ يَكُنِ الدَّليلُ واضِحاً”.","t":"نَجا وَتَخَلَّصَ","o":["أَفْلَتَ المُجْرِمُ مِنَ العِقابِ، حَيْثُ لَمْ يَكُنِ الدَّليلُ واضِحاً"],"b":["أَفْلَتَ المُجْرِمُ مِنَ العِقابِ، حَيْثُ لَمْ يَكُنِ الدَّليلُ واضِحاً","أَفْلَتَ"],"tr":"kurtulmak, yakayı sıyırmak","ttr":"Kurtuldu ve sıyrıldı.","otr":["Delil açık olmadığı için suçlu cezadan yakayı sıyırdı."],"r":null,"s":25,"y":[["مصدر","إِفْلات"]],"f":"يُفْلِتُ إِفْلاتاً"},
{"k":"أَفْلَحَ","c":"","m":"يُفْلِحُ إِفْلاحاً وَفَلاحاً: فازَ، ظَفِرَ، “أَفْلَحَ مَنِ اتَّقَى اللهَ”، ﴿قَدْ أَفْلَحَ الْمُؤْمِنُونَ﴾.","t":"فازَ، ظَفِرَ","o":["أَفْلَحَ مَنِ اتَّقَى اللهَ","﴿قَدْ أَفْلَحَ الْمُؤْمِنُونَ﴾"],"b":["قَدْ أَفْلَحَ الْمُؤْمِنُونَ","أَفْلَحَ"],"tr":"kurtuluşa ermek","ttr":"Kazandı, başarıya ulaştı.","otr":["Allah'tan korkan kurtuluşa erdi.","Müminler gerçekten kurtuluşa ermiştir."],"r":null,"s":25},
{"k":"أَفْلَسَ","c":"","m":"يُفْلِسُ إِفْلاساً: فَقَدَ مالَهُ. “أَفْلَسَ التّاجِرُ بَعْدَ أَنْ كَسَدَتْ بِضاعَتُهُ”، “أَعْلَنَتِ الشَّرِكَةُ إِفْلاسَها، وَتَوَقَّفَتْ عَنْ دَفْعِ الرَّواتِبِ لِلْمُوَظَّفينَ”.","t":"فَقَدَ مالَهُ","o":["أَفْلَسَ التّاجِرُ بَعْدَ أَنْ كَسَدَتْ بِضاعَتُهُ","أَعْلَنَتِ الشَّرِكَةُ إِفْلاسَها، وَتَوَقَّفَتْ عَنْ دَفْعِ الرَّواتِبِ لِلْمُوَظَّفينَ"],"b":["أَفْلَسَ التّاجِرُ بَعْدَ أَنْ كَسَدَتْ بِضاعَتُهُ","أَفْلَسَ"],"tr":"iflas etmek","ttr":"Malını kaybetti.","otr":["Tüccar, malları satılmaz olunca iflas etti.","Şirket iflasını açıkladı ve çalışanlara maaş ödemeyi durdurdu."],"r":null,"s":25,"y":[["مصدر","إِفْلاس"]],"f":"يُفْلِسُ إِفْلاساً"},
{"k":"أَفْنَى","c":"","m":"يُفْني إِفْناءً: أَبادَ وَقَضَى، “تُفْني الحَرْبُ كَثيراً مِنَ الأَبْرِياءِ”، “أَفْنَى حَياتَهُ في نَصْرِ الحَقِّ”.","t":"أَبادَ وَقَضَى","o":["تُفْني الحَرْبُ كَثيراً مِنَ الأَبْرِياءِ","أَفْنَى حَياتَهُ في نَصْرِ الحَقِّ"],"b":["أَفْنَى حَياتَهُ في نَصْرِ الحَقِّ","أَفْنَى"],"tr":"yok etmek; tüketmek","ttr":"Yok etti, bitirdi.","otr":["Savaş birçok masumu yok eder.","Ömrünü hakkı savunmaya adadı (harcadı)."],"r":"p25_1","s":25,"f":"يُفْني إِفْناءً"},
{"k":"أَفْهَمَ","c":"","m":"يُفْهِمُ إِفْهاماً: جَعَلَهُ يَفْهَمُ الأَمْرَ. “أَفْهَمْتُهُ الحَقيقَةَ كامِلَةً”.","t":"جَعَلَهُ يَفْهَمُ الأَمْرَ","o":["أَفْهَمْتُهُ الحَقيقَةَ كامِلَةً"],"b":["أَفْهَمْتُهُ الحَقيقَةَ كامِلَةً","أَفْهَمْتُهُ"],"tr":"anlatmak, anlatıp kavratmak","ttr":"Ona meseleyi anlamasını sağladı.","otr":["Ona gerçeği tümüyle anlattım."],"r":null,"s":25,"f":"يُفْهِمُ إِفْهاماً"},
{"k":"أَقالَ","c":"","m":"يُقيلُ إِقالَةً: أَبْعَدَ، “أَقالَ الرَّئيسُ وَزيرَ الإِعْلامِ دونَ ذِكْرِ الأَسْبابِ”.","t":"أَبْعَدَ","o":["أَقالَ الرَّئيسُ وَزيرَ الإِعْلامِ دونَ ذِكْرِ الأَسْبابِ"],"b":["أَقالَ الرَّئيسُ وَزيرَ الإِعْلامِ دونَ ذِكْرِ الأَسْبابِ","أَقالَ"],"tr":"görevden almak","ttr":"Uzaklaştırdı (görevden aldı).","otr":["Cumhurbaşkanı, sebeplerini belirtmeden enformasyon bakanını görevden aldı."],"r":null,"s":25,"f":"يُقيلُ إِقالَةً"},
{"k":"أَقامَ","c":"","m":"يُقيمُ إِقامَةً: (١) اتَّخَذَ المَكانَ لِلإِقامَةِ وَالسُّكْنَى فيهِ، “أَقامَ في مَكَّةَ سَنَتَيْنِ”. (٢) أَدامَ وَحافَظَ عَلَى، ﴿الَّذينَ إِنْ مَكَّنّاهُمْ فِي الأَرْضِ أَقامُوا الصَّلاةَ﴾. (٣) هَيَّأَ وَأَعَدَّ، “أَقامَ حَفْلَ غَداءٍ لِلضُّيوفِ”، “أَقامَتِ المَدرَسَةُ حَفْلاً كَبيراً”. (٤) أَظْهَرَ، بَيَّنَ، “أَقامَ الدَّليلَ عَلَى صِدْقِهِ”.","t":"(١) اتَّخَذَ المَكانَ لِلإِقامَةِ وَالسُّكْنَى فيهِ (٢) أَدامَ وَحافَظَ عَلَى (٣) هَيَّأَ وَأَعَدَّ (٤) أَظْهَرَ، بَيَّنَ","o":["أَقامَ في مَكَّةَ سَنَتَيْنِ","﴿الَّذينَ إِنْ مَكَّنّاهُمْ فِي الأَرْضِ أَقامُوا الصَّلاةَ﴾","أَقامَ حَفْلَ غَداءٍ لِلضُّيوفِ","أَقامَتِ المَدرَسَةُ حَفْلاً كَبيراً","أَقامَ الدَّليلَ عَلَى صِدْقِهِ"],"b":["أَقامَ في مَكَّةَ سَنَتَيْنِ","أَقامَ"],"tr":"ikamet etmek; kılmak; düzenlemek","ttr":"(1) Bir yeri ikamet ve oturma yeri edindi. (2) Devam ettirdi ve korudu. (3) Hazırladı, düzenledi. (4) Ortaya koydu, açıkladı.","otr":["Mekke'de iki yıl kaldı.","Onlar ki, kendilerini yeryüzünde iktidar sahibi kılarsak namazı dosdoğru kılarlar.","Misafirler için bir öğle yemeği daveti verdi.","Okul büyük bir tören düzenledi.","Doğruluğuna dair delil ortaya koydu."],"r":null,"s":25,"y":[["مصدر","إِقامَة"]],"f":"يُقيمُ إِقامَةً"},
{"k":"أَقْبَلَ","c":"","m":"يُقْبِلُ إِقْبالاً: (١) قَدِمَ وَجاءَ؛ خِلافُ أَدْبَرَ، “أَقْبَلَ أَحمَدُ مَسْروراً مِنَ الحَفْلِ”، وَفي الحَديث: (إِذا أَقْبَلَ اللَّيلُ مِن ها هُنا، وَأَدْبَرَ النَّهارُ مِن ها هُنا، فَقَدْ أَفْطَرَ الصّائِمُ)، ﴿يا مُوسَى أَقْبِلْ وَلا تَخَفْ﴾. (٢) اهتَمَّ وَاجتَهَدَ، “يُقْبِلُ العامِلُ المُخْلِصُ عَلَى عَمَلِهِ”.","t":"(١) قَدِمَ وَجاءَ؛ خِلافُ أَدْبَرَ (٢) اهتَمَّ وَاجتَهَدَ","o":["أَقْبَلَ أَحمَدُ مَسْروراً مِنَ الحَفْلِ","(إِذا أَقْبَلَ اللَّيلُ مِن ها هُنا، وَأَدْبَرَ النَّهارُ مِن ها هُنا، فَقَدْ أَفْطَرَ الصّائِمُ)","﴿يا مُوسَى أَقْبِلْ وَلا تَخَفْ﴾","يُقْبِلُ العامِلُ المُخْلِصُ عَلَى عَمَلِهِ"],"b":["أَقْبَلَ أَحمَدُ مَسْروراً مِنَ الحَفْلِ","أَقْبَلَ"],"tr":"yönelip gelmek","ttr":"(1) Gelip yaklaştı; arkasını dönüp gitmenin zıddı. (2) Bir işe ilgi gösterip çalıştı.","otr":["Ahmet törenden sevinçli olarak geldi.","Hadiste: (Gece şuradan gelip gündüz şuradan çekip gidince oruçlu iftar etmiş olur.)","Ey Musa, gel ve korkma!","İhlaslı işçi işine sarılır."],"r":"p25_2","s":25,"f":"يُقْبِلُ إِقْبالاً"},
{"k":"أَقْحَمَ","c":"","m":"يُقْحِمُ إِقْحاماً: أَدْخَلَ نَفْسَهُ، أَو غَيْرَهُ في الأَمْرِ دونَ تَفْكيرٍ أَو اسْتِعْدادٍ، “لا تُقْحِمْ نَفْسَكَ فيما لا يَعْنيكَ”.","t":"أَدْخَلَ نَفْسَهُ، أَو غَيْرَهُ في الأَمْرِ دونَ تَفْكيرٍ أَو اسْتِعْدادٍ","o":["لا تُقْحِمْ نَفْسَكَ فيما لا يَعْنيكَ"],"b":["لا تُقْحِمْ نَفْسَكَ فيما لا يَعْنيكَ","تُقْحِمْ"],"tr":"(bir işe) sokmak, bulaştırmak","ttr":"Kendini ya da başkasını düşünmeden ve hazırlıksız bir işe soktu.","otr":["Seni ilgilendirmeyen işlere burnunu sokma."],"r":null,"s":25,"f":"يُقْحِمُ إِقْحاماً"},
{"k":"أَقْدَرَ","c":"","m":"يُقْدِرُ إِقْداراً: قَوّاهُ، وَجَعَلَهُ قادِراً عَلَى القِيامِ بِالعَمَلِ، “أَسأَلُ اللهَ أَنْ يُقْدِرَني عَلَى تَرْبِيَةِ أَوْلادي”.","t":"قَوّاهُ، وَجَعَلَهُ قادِراً عَلَى القِيامِ بِالعَمَلِ","o":["أَسأَلُ اللهَ أَنْ يُقْدِرَني عَلَى تَرْبِيَةِ أَوْلادي"],"b":["أَسأَلُ اللهَ أَنْ يُقْدِرَني عَلَى تَرْبِيَةِ أَوْلادي","يُقْدِرَني"],"tr":"güç yetirtmek","ttr":"Onu güçlendirdi ve işi yapabilecek hale getirdi.","otr":["Allah'tan, çocuklarımı yetiştirmeye güç yetirmemi sağlamasını dilerim."],"r":null,"s":25,"f":"يُقْدِرُ إِقْداراً"},
{"k":"أَقْدَمَ","c":"","m":"يُقْدِمُ إِقْداماً: أَخَذَ، شَرَعَ، “أَقْدَمْتُ عَلَى تَنْفيذِ المَشْروعِ دونَ تَرَدُّدٍ”.","t":"أَخَذَ، شَرَعَ","o":["أَقْدَمْتُ عَلَى تَنْفيذِ المَشْروعِ دونَ تَرَدُّدٍ"],"b":["أَقْدَمْتُ عَلَى تَنْفيذِ المَشْروعِ دونَ تَرَدُّدٍ","أَقْدَمْتُ"],"tr":"girişmek, kalkışmak","ttr":"Başladı, girişti.","otr":["Tereddüt etmeden projeyi uygulamaya giriştim."],"r":null,"s":25,"y":[["مصدر","إِقْدام"]],"f":"يُقْدِمُ إِقْداماً"},
{"k":"أَقَرَّ","c":"","m":"يُقِرُّ إِقْراراً: (١) رَضِيَ، قَبِلَ وَوافَقَ، “أَقَرَّ الوُزَراءُ الميزانِيَّةَ، بَعْدَ نِقاشٍ طَويلٍ”. (٢) اعْتَرَفَ، “أَقَرَّ العَدُوُّ بِالهَزيمَةِ”.","t":"(١) رَضِيَ، قَبِلَ وَوافَقَ (٢) اعْتَرَفَ","o":["أَقَرَّ الوُزَراءُ الميزانِيَّةَ، بَعْدَ نِقاشٍ طَويلٍ","أَقَرَّ العَدُوُّ بِالهَزيمَةِ"],"b":["أَقَرَّ العَدُوُّ بِالهَزيمَةِ","أَقَرَّ"],"tr":"onaylamak; itiraf etmek","ttr":"(1) Razı oldu, kabul etti ve onayladı. (2) İtiraf etti.","otr":["Bakanlar uzun bir tartışmadan sonra bütçeyi onayladı.","Düşman yenilgiyi kabul etti."],"r":null,"s":25,"f":"يُقِرُّ إِقْراراً"},
{"k":"أَقْرَأَ","c":"","m":"يُقْرِئُ إِقْراءً: (١) جَعَلَ الشَّخْصَ يَقْرَأُ، “أَقْرَأَ المُعَلِّمُ التَّلاميذَ الدَّرْسَ واحِداً بَعْدَ الآخَرِ”. (٢) عَلَّمَهُ القُرْآنَ، ﴿سَنُقْرِئُكَ فَلا تَنْسَى﴾.","t":"(١) جَعَلَ الشَّخْصَ يَقْرَأُ (٢) عَلَّمَهُ القُرْآنَ","o":["أَقْرَأَ المُعَلِّمُ التَّلاميذَ الدَّرْسَ واحِداً بَعْدَ الآخَرِ","﴿سَنُقْرِئُكَ فَلا تَنْسَى﴾"],"b":["أَقْرَأَ المُعَلِّمُ التَّلاميذَ الدَّرْسَ واحِداً بَعْدَ الآخَرِ","أَقْرَأَ"],"tr":"okutmak","ttr":"(1) Kişiye okuttu. (2) Ona Kur'an öğretti.","otr":["Öğretmen dersi öğrencilere birbiri ardınca okuttu.","Sana okutacağız, artık unutmayacaksın."],"r":"p25_3","s":25,"f":"يُقْرِئُ إِقْراءً"},
{"k":"أَقْرَضَ","c":"","m":"يُقْرِضُ إِقْراضاً وَقَرْضاً: (١) أَعْطَى غَيْرَهُ قَرْضاً (شَيْئاً) لِيَرُدَّهُ إِلَيهِ لاحِقاً، “سَأَلْتُهُ أَنْ يُقْرِضَني بَعْضَ المالِ فَوافَقَ”. (٢) أَقْرَضَ اللهَ: تَصَدَّقَ عَلَى الفُقَراءِ، ﴿وَأَقْرِضُوا اللَّهَ قَرْضاً حَسَناً﴾.","t":"(١) أَعْطَى غَيْرَهُ قَرْضاً (شَيْئاً) لِيَرُدَّهُ إِلَيهِ لاحِقاً (٢) أَقْرَضَ اللهَ: تَصَدَّقَ عَلَى الفُقَراءِ","o":["سَأَلْتُهُ أَنْ يُقْرِضَني بَعْضَ المالِ فَوافَقَ","﴿وَأَقْرِضُوا اللَّهَ قَرْضاً حَسَناً﴾"],"b":["سَأَلْتُهُ أَنْ يُقْرِضَني بَعْضَ المالِ فَوافَقَ","يُقْرِضَني"],"tr":"borç vermek","ttr":"(1) Sonra geri vermesi için başkasına borç (bir şey) verdi. (2) Allah'a borç verdi: fakirlere sadaka verdi.","otr":["Ondan bana biraz borç para vermesini istedim, o da kabul etti.","Allah'a güzel bir borç verin."],"r":null,"s":25},
{"k":"أَلْحَدَ","c":"","m":"يُلْحِدُ إلْحاداً : مالَ ، وانْحَرَفَ ، والإلْحادُ : نُكْرانُ وُجودِ اللهِ سُبْحانَهُ وتَعالَى ، “انْتَشَرَ الإلْحادُ في هذا العَصْرِ” ، ﴿وَلِلَّهِ الأَسْمَاءُ الحُسْنَى فَادْعُوهُ بِهَا وَذَرُوا الَّذِينَ يُلْحِدُونَ فِي أَسْمَائِهِ سَيُجْزَوْنَ مَا كَانُوا يَعْمَلُونَ﴾ .","t":"مالَ ، وانْحَرَفَ ؛ والإلْحادُ : نُكْرانُ وُجودِ اللهِ سُبْحانَهُ وتَعالَى","o":["انْتَشَرَ الإلْحادُ في هذا العَصْرِ","﴿وَلِلَّهِ الأَسْمَاءُ الحُسْنَى فَادْعُوهُ بِهَا وَذَرُوا الَّذِينَ يُلْحِدُونَ فِي أَسْمَائِهِ سَيُجْزَوْنَ مَا كَانُوا يَعْمَلُونَ﴾"],"b":["انْتَشَرَ الإلْحادُ في هذا العَصْرِ","الإلْحادُ"],"tr":"sapmak; inkâra düşmek","ttr":"Meyletti, saptı; ilhad: Allah'ın (c.c.) varlığını inkâr etmek.","otr":["Bu çağda ateizm yayıldı.","En güzel isimler Allah'ındır; O'na onlarla dua edin. O'nun isimleri hakkında sapkınlık edenleri bırakın; yapmakta olduklarının cezasını göreceklerdir."],"r":null,"s":28,"f":"يُلْحِدُ إلْحاداً"},
{"k":"إلْزامِيّ","c":"","m":"إجْبارِيّ ، “هذا المُقَرَّرُ إلْزامِيٌّ على طُلّابِ الكُلِّيَّةِ” .","t":"إجْبارِيّ","o":["هذا المُقَرَّرُ إلْزامِيٌّ على طُلّابِ الكُلِّيَّةِ"],"b":["هذا المُقَرَّرُ إلْزامِيٌّ على طُلّابِ الكُلِّيَّةِ","إلْزامِيٌّ"],"tr":"zorunlu","ttr":"Mecburi.","otr":["Bu ders fakülte öğrencileri için zorunludur."],"r":null,"s":28},
{"k":"أَلْغَى","c":"","m":"يُلْغي إلْغاءً : أَبْطَلَ وأَوْقَفَ ، “أَلْغَى المَعْهَدُ الرِّحْلَةَ لِكَثْرَةِ الأَمْطارِ” .","t":"أَبْطَلَ وأَوْقَفَ","o":["أَلْغَى المَعْهَدُ الرِّحْلَةَ لِكَثْرَةِ الأَمْطارِ"],"b":["أَلْغَى المَعْهَدُ الرِّحْلَةَ لِكَثْرَةِ الأَمْطارِ","أَلْغَى"],"tr":"iptal etmek","ttr":"Geçersiz kıldı ve durdurdu.","otr":["Enstitü, yağmurların çokluğu yüzünden geziyi iptal etti."],"r":null,"s":28,"f":"يُلْغي إلْغاءً"},
{"k":"أَلْف","c":"آلاف، أُلوف","m":"(ج) آلاف وأُلوف : الأَلْفُ يُساوي عَشْرَ مِئاتٍ ، وَيُرْسَمُ رَقْماً هكَذا (١٠٠٠) ، ﴿لَيْلَةُ القَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ﴾ ، ﴿وَهُمْ أُلُوفٌ حَذَرَ المَوْتِ﴾ .","t":"الأَلْفُ يُساوي عَشْرَ مِئاتٍ ، وَيُرْسَمُ رَقْماً هكَذا (١٠٠٠)","o":["﴿لَيْلَةُ القَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ﴾","﴿وَهُمْ أُلُوفٌ حَذَرَ المَوْتِ﴾"],"b":["﴿لَيْلَةُ القَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ﴾","أَلْفِ"],"tr":"bin","ttr":"Bin, on yüze eşittir ve rakamla şöyle yazılır: (1000).","otr":["Kadir gecesi bin aydan hayırlıdır.","Onlar ölüm korkusuyla (yurtlarından çıkan) binlerce kişiydi."],"r":null,"s":28},
{"k":"أَلِفْباء","c":"","m":"تَرْتيبُ حُروفِ اللُّغَةِ العَرَبِيَّةِ الثَّمانِيَةِ وَالعِشْرينَ بَدْءاً مِنَ الهَمْزَةِ وانْتِهاءً بالياءِ .","t":"تَرْتيبُ حُروفِ اللُّغَةِ العَرَبِيَّةِ الثَّمانِيَةِ وَالعِشْرينَ بَدْءاً مِنَ الهَمْزَةِ وانْتِهاءً بالياءِ","o":[],"b":null,"tr":"alfabe","ttr":"Arap dilinin yirmi sekiz harfinin hemzeden başlayıp ye ile biten sıralaması.","otr":[],"r":null,"s":28},
{"k":"أُلْفَة","c":"","m":"مَحَبَّةٌ وَوُدّ ، “بَيْنَ عَلِيٍّ وَمُحَمَّدٍ أُلْفَةٌ قَوِيَّةٌ ؛ فَهُما صَديقانِ مُنْذُ طُفولَتِهِما” .","t":"مَحَبَّةٌ وَوُدّ","o":["بَيْنَ عَلِيٍّ وَمُحَمَّدٍ أُلْفَةٌ قَوِيَّةٌ ؛ فَهُما صَديقانِ مُنْذُ طُفولَتِهِما"],"b":["بَيْنَ عَلِيٍّ وَمُحَمَّدٍ أُلْفَةٌ قَوِيَّةٌ","أُلْفَةٌ"],"tr":"ülfet, yakınlık","ttr":"Sevgi ve dostluk.","otr":["Ali ile Muhammed arasında güçlü bir yakınlık var; ikisi çocukluklarından beri arkadaş."],"r":null,"s":28},
{"k":"أَلْفَى","c":"","m":"يُلْفي إلْفاءً : وَجَدَ وَصادَفَ ، “عَرَفْتُ صَديقَكَ ، فَأَلْفَيْتُهُ نِعْمَ الصَّديقِ” ، ﴿قَالُوا بَلْ نَتَّبِعُ مَا أَلْفَيْنَا عَلَيْهِ آبَاءَنَا﴾ .","t":"وَجَدَ وَصادَفَ","o":["عَرَفْتُ صَديقَكَ ، فَأَلْفَيْتُهُ نِعْمَ الصَّديقِ","﴿قَالُوا بَلْ نَتَّبِعُ مَا أَلْفَيْنَا عَلَيْهِ آبَاءَنَا﴾"],"b":["عَرَفْتُ صَديقَكَ ، فَأَلْفَيْتُهُ نِعْمَ الصَّديقِ","فَأَلْفَيْتُهُ"],"tr":"bulmak, rastlamak","ttr":"Buldu ve rastladı.","otr":["Arkadaşını tanıdım ve onu ne güzel bir arkadaş buldum.","Dediler ki: Hayır, biz babalarımızı üzerinde bulduğumuz şeye uyarız."],"r":null,"s":28,"f":"يُلْفي إلْفاءً"},
{"k":"أَلْقَى","c":"","m":"يُلْقي إلْقاءً : (١) طَرَحَ وَرَمَى ، “أَلْقَى يُوسُفُ الحَجَرَ في النَّهْرِ” ، ﴿قَالُوا يَا مُوسَى إِمَّا أَنْ تُلْقِيَ وَإِمَّا أَنْ نَكُونَ أَوَّلَ مَنْ أَلْقَى﴾ . (٢) أَلْقَى السَّلامَ : سَلَّمَ ، ﴿وَلَا تَقُولُوا لِمَنْ أَلْقَى إِلَيْكُمُ السَّلَامَ لَسْتَ مُؤْمِنًا﴾ .","t":"(١) طَرَحَ وَرَمَى . (٢) أَلْقَى السَّلامَ : سَلَّمَ","o":["أَلْقَى يُوسُفُ الحَجَرَ في النَّهْرِ","﴿قَالُوا يَا مُوسَى إِمَّا أَنْ تُلْقِيَ وَإِمَّا أَنْ نَكُونَ أَوَّلَ مَنْ أَلْقَى﴾","﴿وَلَا تَقُولُوا لِمَنْ أَلْقَى إِلَيْكُمُ السَّلَامَ لَسْتَ مُؤْمِنًا﴾"],"b":["أَلْقَى يُوسُفُ الحَجَرَ في النَّهْرِ","أَلْقَى"],"tr":"atmak, fırlatmak","ttr":"(1) Attı, fırlattı. (2) Selam verdi: selamladı.","otr":["Yusuf taşı nehre attı.","Dediler ki: Ey Musa! Ya sen at ya da ilk atan biz olalım.","Size selam verene 'Sen mümin değilsin' demeyin."],"r":"p28_1","s":28,"y":[["مصدر","إلْقاء"]],"f":"يُلْقي إلْقاءً"},
{"k":"أَلَم","c":"آلام","m":"(ج) آلام : وَجَعٌ ؛ خِلافُ اللَّذَّةِ ، “شَعَرَ المَريضُ بِأَلَمٍ شَديدٍ عَقِبَ العَمَلِيَّةِ الجِراحِيَّةِ” ، “وَجَعُ الأَسْنانِ مِنْ أَشَدِّ الآلامِ” .","t":"وَجَعٌ ؛ خِلافُ اللَّذَّةِ","o":["شَعَرَ المَريضُ بِأَلَمٍ شَديدٍ عَقِبَ العَمَلِيَّةِ الجِراحِيَّةِ","وَجَعُ الأَسْنانِ مِنْ أَشَدِّ الآلامِ"],"b":["شَعَرَ المَريضُ بِأَلَمٍ شَديدٍ عَقِبَ العَمَلِيَّةِ الجِراحِيَّةِ","بِأَلَمٍ"],"tr":"acı, ağrı","ttr":"Ağrı; hazzın zıddı.","otr":["Hasta, ameliyattan sonra şiddetli bir acı hissetti.","Diş ağrısı en şiddetli acılardandır."],"r":"p28_2","s":28},
{"k":"إلْماحَة","c":"إلْماحات","m":"(ج) إلْماحات : إشارَةٌ خَفيفَةٌ عابِرَةٌ ، “في حَديثِهِ مَعي بَدَرَتْ مِنْهُ إلْماحَةٌ إلى رَغْبَتِهِ في السَّفَرِ” .","t":"إشارَةٌ خَفيفَةٌ عابِرَةٌ","o":["في حَديثِهِ مَعي بَدَرَتْ مِنْهُ إلْماحَةٌ إلى رَغْبَتِهِ في السَّفَرِ"],"b":["في حَديثِهِ مَعي بَدَرَتْ مِنْهُ إلْماحَةٌ إلى رَغْبَتِهِ في السَّفَرِ","إلْماحَةٌ"],"tr":"ima, üstü kapalı işaret","ttr":"Hafif, geçici bir işaret.","otr":["Benimle konuşurken yolculuğa çıkma isteğine dair bir ima ondan sadır oldu."],"r":null,"s":28},
{"k":"أَلْمَحَ","c":"","m":"يُلْمِحُ إلْماحاً : أَشارَ ، “أَلْمَحَ المُديرُ إلى كَثْرَةِ تَغَيُّبِ بَعْضِ المُوَظَّفينَ” .","t":"أَشارَ","o":["أَلْمَحَ المُديرُ إلى كَثْرَةِ تَغَيُّبِ بَعْضِ المُوَظَّفينَ"],"b":["أَلْمَحَ المُديرُ إلى كَثْرَةِ تَغَيُّبِ بَعْضِ المُوَظَّفينَ","أَلْمَحَ"],"tr":"ima etmek","ttr":"İşaret etti.","otr":["Müdür bazı çalışanların sık sık devamsızlık yaptığını ima etti."],"r":null,"s":28,"f":"يُلْمِحُ إلْماحاً"},
{"k":"إلَه","c":"آلِهَة","m":"(ج) آلِهَة : المَعْبودُ ، “أَشْهَدُ أَنْ لا إلَهَ إلاَّ اللهُ” ، أي : لا مَعْبودَ بِحَقٍّ إلا اللهُ . ﴿أَنَّهُ لَا إِلَهَ إِلَّا أَنَا فَاعْبُدُونِ﴾ ، ﴿لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللَّهُ لَفَسَدَتَا﴾ .","t":"المَعْبودُ","o":["أَشْهَدُ أَنْ لا إلَهَ إلاَّ اللهُ","﴿أَنَّهُ لَا إِلَهَ إِلَّا أَنَا فَاعْبُدُونِ﴾","﴿لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللَّهُ لَفَسَدَتَا﴾"],"b":["أَشْهَدُ أَنْ لا إلَهَ إلاَّ اللهُ","إلَهَ"],"tr":"ilah","ttr":"Kendisine ibadet edilen.","otr":["Allah'tan başka ilah olmadığına şahitlik ederim (yani hak ile ibadet edilen yalnızca Allah'tır).","Benden başka ilah yoktur; öyleyse bana ibadet edin.","Eğer yerde ve gökte Allah'tan başka ilahlar olsaydı, ikisinin de düzeni bozulurdu."],"r":null,"s":28,"y":[["جمع","آلِهَة"]]},
{"k":"أَلْهَبَ","c":"","m":"يُلْهِبُ إلْهاباً : أَشْعَلَ وَأَوْقَدَ ، “أَلْهَبَ الرَّجُلُ النّارَ” .","t":"أَشْعَلَ وَأَوْقَدَ","o":["أَلْهَبَ الرَّجُلُ النّارَ"],"b":["أَلْهَبَ الرَّجُلُ النّارَ","أَلْهَبَ"],"tr":"tutuşturmak","ttr":"Yaktı, tutuşturdu.","otr":["Adam ateşi tutuşturdu."],"r":"p28_3","s":28,"f":"يُلْهِبُ إلْهاباً"},
{"k":"أَلْهَمَ","c":"","m":"يُلْهِمُ إلْهاماً : أَلْقاهُ في خاطِرِهِ ، “أَلْهَمَهُ اللهُ الجَوابَ الصَّحيحَ” .","t":"أَلْقاهُ في خاطِرِهِ","o":["أَلْهَمَهُ اللهُ الجَوابَ الصَّحيحَ"],"b":["أَلْهَمَهُ اللهُ الجَوابَ الصَّحيحَ","أَلْهَمَهُ"],"tr":"ilham etmek","ttr":"Onu gönlüne/aklına düşürdü.","otr":["Allah ona doğru cevabı ilham etti."],"r":null,"s":28,"f":"يُلْهِمُ إلْهاماً"},
{"k":"أَلْهَى","c":"","m":"يُلْهي إلْهاءً : سَلَّى وَشَغَلَ وَأَنْسَى ، “أَلْهاهُ اللَّعِبُ عَنِ الدَّرْسِ فَرَسَبَ” ، ﴿أَلْهَاكُمُ التَّكَاثُرُ﴾ .","t":"سَلَّى وَشَغَلَ وَأَنْسَى","o":["أَلْهاهُ اللَّعِبُ عَنِ الدَّرْسِ فَرَسَبَ","﴿أَلْهَاكُمُ التَّكَاثُرُ﴾"],"b":["أَلْهاهُ اللَّعِبُ عَنِ الدَّرْسِ فَرَسَبَ","أَلْهاهُ"],"tr":"oyalamak, alıkoymak","ttr":"Oyaladı, meşgul etti ve unutturdu.","otr":["Oyun onu dersten alıkoydu, bu yüzden sınıfta kaldı.","Çoklukla övünmek sizi oyaladı."],"r":null,"s":28,"f":"يُلْهي إلْهاءً"},
{"k":"آلَى","c":"","m":"يُؤْلي إيلاءً : أَقْسَمَ ، حَلَفَ ، “آلَى مُحَمَّدٌ عَلَى نَفْسِهِ أَنْ يَحْفَظَ القُرْآنَ” ، ﴿لِلَّذِينَ يُؤْلُونَ مِنْ نِسَائِهِمْ تَرَبُّصُ أَرْبَعَةِ﴾ .","t":"أَقْسَمَ ، حَلَفَ","o":["آلَى مُحَمَّدٌ عَلَى نَفْسِهِ أَنْ يَحْفَظَ القُرْآنَ","﴿لِلَّذِينَ يُؤْلُونَ مِنْ نِسَائِهِمْ تَرَبُّصُ أَرْبَعَةِ﴾"],"b":["آلَى مُحَمَّدٌ عَلَى نَفْسِهِ أَنْ يَحْفَظَ القُرْآنَ","آلَى"],"tr":"yemin etmek","ttr":"Yemin etti, ant içti.","otr":["Muhammed Kur'an'ı ezberlemeye kendi kendine söz verdi (yemin etti).","Kadınlarına yaklaşmamaya yemin edenler için dört (ay) bekleme süresi vardır."],"r":null,"s":28,"f":"يُؤْلي إيلاءً"},
{"k":"إلى","c":"","m":"حَرْفُ جَرٍّ لانْتِهاءِ الغايَةِ ، “سِرْتُ مِنَ البَيْتِ إلى المَدْرَسَةِ” ، “قُلْتُ لَهُ عِنْدَ الوَداعِ : إلى اللِّقاءِ” .","t":"حَرْفُ جَرٍّ لانْتِهاءِ الغايَةِ","o":["سِرْتُ مِنَ البَيْتِ إلى المَدْرَسَةِ","قُلْتُ لَهُ عِنْدَ الوَداعِ : إلى اللِّقاءِ"],"b":["سِرْتُ مِنَ البَيْتِ إلى المَدْرَسَةِ","إلى"],"tr":"-e, -a doğru","ttr":"Varış noktasını bildiren harf-i cer.","otr":["Evden okula yürüdüm.","Vedalaşırken ona 'Görüşmek üzere' dedim."],"r":null,"s":28},
{"k":"أَليم","c":"","m":"شَديدُ الأَلَمِ ، مُؤْلِمٌ ، كَثيرُ الوَجَعِ ، ﴿وَأَنَّ عَذَابِي هُوَ الْعَذَابُ الْأَلِيمُ﴾ .","t":"شَديدُ الأَلَمِ ، مُؤْلِمٌ ، كَثيرُ الوَجَعِ","o":["﴿وَأَنَّ عَذَابِي هُوَ الْعَذَابُ الْأَلِيمُ﴾"],"b":["﴿وَأَنَّ عَذَابِي هُوَ الْعَذَابُ الْأَلِيمُ﴾","الْأَلِيمُ"],"tr":"acıklı, can yakıcı","ttr":"Çok acı veren, acıtan, çok ağrılı.","otr":["Ve şüphesiz benim azabım, çok acıklı azaptır."],"r":null,"s":28},
{"k":"أَلْيَنُ","c":"","m":"أَكْثَرُ ليناً وَطَراوَةً وَسُهولَةً ؛ خِلافُ أَقْسَى وَأَصْلَب ، “الحَريرُ أَلْيَنُ مِنَ الوَرَقِ ، وَالوَرَقُ أَلْيَنُ مِنَ الحَديدِ وَالخَشَبِ” .","t":"أَكْثَرُ ليناً وَطَراوَةً وَسُهولَةً ؛ خِلافُ أَقْسَى وَأَصْلَب","o":["الحَريرُ أَلْيَنُ مِنَ الوَرَقِ ، وَالوَرَقُ أَلْيَنُ مِنَ الحَديدِ وَالخَشَبِ"],"b":["الحَريرُ أَلْيَنُ مِنَ الوَرَقِ","أَلْيَنُ"],"tr":"daha yumuşak","ttr":"Daha yumuşak, daha taze ve daha kolay; 'daha sert, daha katı'nın zıddı.","otr":["İpek kâğıttan daha yumuşaktır, kâğıt da demirden ve tahtadan daha yumuşaktır."],"r":"p28_4","s":28},
{"k":"أَمَّ","c":"","m":"يَؤُمُّ أَمّاً : (١) قَصَدَ وَتَوَجَّهَ إلى ، “أَمَّ الطُّلّابُ مَكْتَبَ المُديرِ” ، “في الظَّلامِ يَؤُمُّ النّاسُ الصَّوْتَ ؛ فَيَصِلونَ إلى المَكانِ المَطْلوبِ” . (٢) قادَ وَتَقَدَّمَ ، “أَمَّ مُحَمَّدٌ المُصَلِّينَ في الصَّلاةِ” ، (يَؤُمُّ القَوْمَ أَقْرَؤُهُمْ لِكِتابِ اللهِ) .","t":"(١) قَصَدَ وَتَوَجَّهَ إلى . (٢) قادَ وَتَقَدَّمَ","o":["أَمَّ الطُّلّابُ مَكْتَبَ المُديرِ","في الظَّلامِ يَؤُمُّ النّاسُ الصَّوْتَ ؛ فَيَصِلونَ إلى المَكانِ المَطْلوبِ","أَمَّ مُحَمَّدٌ المُصَلِّينَ في الصَّلاةِ","(يَؤُمُّ القَوْمَ أَقْرَؤُهُمْ لِكِتابِ اللهِ)"],"b":["أَمَّ الطُّلّابُ مَكْتَبَ المُديرِ","أَمَّ"],"tr":"yönelmek; imamlık etmek","ttr":"(1) Kastetti, yöneldi. (2) Önderlik etti, öne geçti (namaz kıldırdı).","otr":["Öğrenciler müdürün odasına yöneldi.","Karanlıkta insanlar sese yönelir; böylece istenen yere ulaşırlar.","Muhammed namazda cemaate imamlık etti.","Topluluğa Allah'ın kitabını en iyi okuyanları imam olur."],"r":null,"s":28,"f":"يَؤُمُّ أَمّاً"},
{"k":"أُمّ","c":"أُمَّهات، أُمّات","m":"(ج) أُمَّهات / أُمّات : (١) الوالِدَةُ ، “آمِنَةُ بِنْتُ وَهْبٍ أُمُّ الرَّسولِ ﷺ” ، قالَ عُمَرُ : “مَتَى اسْتَعْبَدْتُمُ النّاسَ وَقَدْ وَلَدَتْهُمْ أُمَّهاتُهُمْ أَحْراراً” ، ﴿وَإِذْ أَنْتُمْ أَجِنَّةٌ فِي بُطُونِ أُمَّهَاتِكُمْ﴾ . (٢) الأَصْلُ ، “العَرَبِيَّةُ هِيَ اللُّغَةُ الأُمُّ لِكُلِّ العَرَبِ” . (٣) أُمُّ القُرْآنِ : الفاتِحَةُ . (٤) أُمُّ القُرَى : مَكَّةُ . (٥) أُمُّ الخَبائِثِ : الخَمْرُ .","t":"(١) الوالِدَةُ . (٢) الأَصْلُ . (٣) أُمُّ القُرْآنِ : الفاتِحَةُ . (٤) أُمُّ القُرَى : مَكَّةُ . (٥) أُمُّ الخَبائِثِ : الخَمْرُ","o":["آمِنَةُ بِنْتُ وَهْبٍ أُمُّ الرَّسولِ ﷺ","مَتَى اسْتَعْبَدْتُمُ النّاسَ وَقَدْ وَلَدَتْهُمْ أُمَّهاتُهُمْ أَحْراراً","﴿وَإِذْ أَنْتُمْ أَجِنَّةٌ فِي بُطُونِ أُمَّهَاتِكُمْ﴾","العَرَبِيَّةُ هِيَ اللُّغَةُ الأُمُّ لِكُلِّ العَرَبِ"],"b":["آمِنَةُ بِنْتُ وَهْبٍ أُمُّ الرَّسولِ ﷺ","أُمُّ"],"tr":"anne","ttr":"(1) Anne. (2) Asıl, köken. (3) Ümmü'l-Kur'an: Fâtiha suresi. (4) Ümmü'l-Kurâ: Mekke. (5) Ümmü'l-Habâis (kötülüklerin anası): içki.","otr":["Vehb'in kızı Âmine, Resûlullah'ın (s.a.v.) annesidir.","Hz. Ömer dedi ki: Anneleri onları hür doğurmuşken insanları ne zamandan beri köleleştirdiniz?","Hani siz annelerinizin karnında ceninler iken...","Arapça bütün Araplar için ana dildir."],"r":"p29_1","s":29},
{"k":"أَماتَ","c":"","m":"يُميتُ إماتَةً : قَضَى عَلَى ؛ خِلافُ أَحْيا ، “تُميتُ الحَرْبُ آلافَ الأَبْرِياءِ كُلَّ يَوْمٍ” ، ﴿وَأَنَّهُ هُوَ أَمَاتَ وَأَحْيَا﴾ .","t":"قَضَى عَلَى ؛ خِلافُ أَحْيا","o":["تُميتُ الحَرْبُ آلافَ الأَبْرِياءِ كُلَّ يَوْمٍ","﴿وَأَنَّهُ هُوَ أَمَاتَ وَأَحْيَا﴾"],"b":["تُميتُ الحَرْبُ آلافَ الأَبْرِياءِ كُلَّ يَوْمٍ","تُميتُ"],"tr":"öldürmek","ttr":"İşini bitirdi; diriltmenin zıddı.","otr":["Savaş her gün binlerce masumu öldürüyor.","Öldüren de dirilten de O'dur."],"r":"p29_2","s":29,"f":"يُميتُ إماتَةً"},
{"k":"إمارَة","c":"إمارات","m":"(ج) إمارات : (١) وِلايَةُ شُؤونِ المُسْلِمينَ ، “تَوَلَّى عَمْرُو بْنُ العاصِ إمارَةَ مِصْرَ” . (٢) الإقْليمُ أَوِ المَنْطِقَةُ الَّتي يَحْكُمُها الأَميرُ . “إمارَةُ الكُوَيْتِ ، وَإمارَةُ قَطَرٍ مِنْ دُوَلِ الخَليجِ العَرَبِيَّةِ” .","t":"(١) وِلايَةُ شُؤونِ المُسْلِمينَ . (٢) الإقْليمُ أَوِ المَنْطِقَةُ الَّتي يَحْكُمُها الأَميرُ","o":["تَوَلَّى عَمْرُو بْنُ العاصِ إمارَةَ مِصْرَ","إمارَةُ الكُوَيْتِ ، وَإمارَةُ قَطَرٍ مِنْ دُوَلِ الخَليجِ العَرَبِيَّةِ"],"b":["تَوَلَّى عَمْرُو بْنُ العاصِ إمارَةَ مِصْرَ","إمارَةَ"],"tr":"emirlik, valilik","ttr":"(1) Müslümanların işlerini yönetme (valilik). (2) Emirin yönettiği bölge veya arazi.","otr":["Amr b. el-Âs Mısır valiliğini üstlendi.","Kuveyt Emirliği ve Katar Emirliği Arap Körfez ülkelerindendir."],"r":null,"s":29},
{"k":"أَماطَ","c":"","m":"يُميطُ إماطَةً : أَبْعَدَ ، وَنَحَّى ، “أَماطَ الشَّوْكَ عَنِ الطَّريقِ” ، “أَماطَ اللِّثامَ عَنْ وَجْهِهِ” ، وفي الحَديثِ : (إماطَةُ الأَذَى عَنِ الطَّريقِ صَدَقَةٌ) .","t":"أَبْعَدَ ، وَنَحَّى","o":["أَماطَ الشَّوْكَ عَنِ الطَّريقِ","أَماطَ اللِّثامَ عَنْ وَجْهِهِ","(إماطَةُ الأَذَى عَنِ الطَّريقِ صَدَقَةٌ)"],"b":["أَماطَ الشَّوْكَ عَنِ الطَّريقِ","أَماطَ"],"tr":"gidermek, kaldırmak","ttr":"Uzaklaştırdı, bir kenara çekti.","otr":["Dikenleri yoldan kaldırdı.","Yüzündeki peçeyi kaldırdı.","Hadiste: Yoldan eziyet veren şeyi kaldırmak sadakadır."],"r":"p29_3","s":29,"y":[["مصدر","إماطَة"]],"f":"يُميطُ إماطَةً"},
{"k":"أَمالَ","c":"","m":"يُميلُ إمالَةً : جَعَلَ الشَّيْءَ مائِلاً ، “أَمالَتِ الرِّياحُ الأَشْجارَ” .","t":"جَعَلَ الشَّيْءَ مائِلاً","o":["أَمالَتِ الرِّياحُ الأَشْجارَ"],"b":["أَمالَتِ الرِّياحُ الأَشْجارَ","أَمالَتِ"],"tr":"eğmek","ttr":"Bir şeyi eğik hale getirdi.","otr":["Rüzgârlar ağaçları eğdi."],"r":null,"s":29,"f":"يُميلُ إمالَةً"},
{"k":"أَمام","c":"","m":"ظَرْفُ مَكانٍ بِمَعْنَى قُدّام ؛ خِلافُ وَراء ، “اُنْظُرْ أَمامَكَ عِنْدَما تَقودُ السَّيّارَةَ” ، ﴿بَلْ يُرِيدُ الْإِنْسَانُ لِيَفْجُرَ أَمَامَهُ﴾ .","t":"ظَرْفُ مَكانٍ بِمَعْنَى قُدّام ؛ خِلافُ وَراء","o":["اُنْظُرْ أَمامَكَ عِنْدَما تَقودُ السَّيّارَةَ","﴿بَلْ يُرِيدُ الْإِنْسَانُ لِيَفْجُرَ أَمَامَهُ﴾"],"b":["اُنْظُرْ أَمامَكَ عِنْدَما تَقودُ السَّيّارَةَ","أَمامَكَ"],"tr":"ön, önünde","ttr":"'Ön' anlamında yer zarfı; 'arka'nın zıddı.","otr":["Araba sürerken önüne bak.","Bilakis insan, önündeki (ömrü boyunca) günah işlemek ister."],"r":"p29_4","s":29,"y":[["جمع","أئِمَّة"]]},
{"k":"إمام","c":"أَئِمَّة","m":"(ج) أَئِمَّة : (١) مَنْ يَؤُمُّ المُصَلِّينَ في الصَّلاةِ ، “أَمَّ الإمامُ الجَديدُ المُصَلِّينَ في صَلاةِ الفَجْرِ” . (٢) رَئيسُ القَوْمِ ، ﴿قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامًا﴾ ، ﴿فَقَاتِلُوا أَئِمَّةَ الْكُفْرِ﴾ .","t":"(١) مَنْ يَؤُمُّ المُصَلِّينَ في الصَّلاةِ . (٢) رَئيسُ القَوْمِ","o":["أَمَّ الإمامُ الجَديدُ المُصَلِّينَ في صَلاةِ الفَجْرِ","﴿قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامًا﴾","﴿فَقَاتِلُوا أَئِمَّةَ الْكُفْرِ﴾"],"b":["أَمَّ الإمامُ الجَديدُ المُصَلِّينَ في صَلاةِ الفَجْرِ","الإمامُ"],"tr":"imam, önder","ttr":"(1) Namazda cemaate imamlık eden kişi. (2) Topluluğun başkanı.","otr":["Yeni imam sabah namazında cemaate imamlık etti.","(Allah) dedi ki: Seni insanlara önder yapacağım.","Küfrün önderleriyle savaşın."],"r":"p29_5","s":29},
{"k":"أَمان","c":"","m":"مَصْدَرُ أَمِنَ : اطْمَأَنَّ وَلَمْ يَخَفْ ، “يَعيشُ النّاسُ تَحْتَ حِمَى الشَّريعَةِ في أَمْنٍ وَأَمانٍ” ، ﴿أَوَأَمِنَ أَهْلُ الْقُرَى أَنْ يَأْتِيَهُمْ بَأْسُنَا ضُحًى وَهُمْ يَلْعَبُونَ﴾ . في أَمانِ اللهِ : في حِفْظِ اللهِ .","t":"مَصْدَرُ أَمِنَ : اطْمَأَنَّ وَلَمْ يَخَفْ . في أَمانِ اللهِ : في حِفْظِ اللهِ","o":["يَعيشُ النّاسُ تَحْتَ حِمَى الشَّريعَةِ في أَمْنٍ وَأَمانٍ","﴿أَوَأَمِنَ أَهْلُ الْقُرَى أَنْ يَأْتِيَهُمْ بَأْسُنَا ضُحًى وَهُمْ يَلْعَبُونَ﴾"],"b":["يَعيشُ النّاسُ تَحْتَ حِمَى الشَّريعَةِ في أَمْنٍ وَأَمانٍ","وَأَمانٍ"],"tr":"güven, emniyet","ttr":"Emin olmak fiilinin mastarı: içi rahat olmak ve korkmamak. Allah'ın emanında: Allah'ın korumasında.","otr":["İnsanlar şeriatın himayesi altında güven ve emniyet içinde yaşar.","Yoksa ülkelerin halkı, kuşluk vakti oyun oynarlarken azabımızın kendilerine gelmeyeceğinden emin mi oldular?"],"r":null,"s":29},
{"k":"أَمانَة","c":"","m":"خِلافُ الخِيانَةِ ؛ (١) الوَفاءُ ، “يُؤَدِّي الجُنْدِيُّ عَمَلَهُ بِأَمانَةٍ” . (٢) الوَديعَةُ ، ﴿إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الْأَمَانَاتِ إِلَى أَهْلِهَا﴾ . (٣) المَسْؤولِيَّةُ ، ﴿إِنَّا عَرَضْنَا الْأَمَانَةَ عَلَى السَّمَاوَاتِ وَالْأَرْضِ وَالْجِبَالِ﴾ .","t":"خِلافُ الخِيانَةِ ؛ (١) الوَفاءُ . (٢) الوَديعَةُ . (٣) المَسْؤولِيَّةُ","o":["يُؤَدِّي الجُنْدِيُّ عَمَلَهُ بِأَمانَةٍ","﴿إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الْأَمَانَاتِ إِلَى أَهْلِهَا﴾","﴿إِنَّا عَرَضْنَا الْأَمَانَةَ عَلَى السَّمَاوَاتِ وَالْأَرْضِ وَالْجِبَالِ﴾"],"b":["يُؤَدِّي الجُنْدِيُّ عَمَلَهُ بِأَمانَةٍ","بِأَمانَةٍ"],"tr":"emanet; dürüstlük","ttr":"Hıyanetin zıddı; (1) vefa, sadakat. (2) Emanet bırakılan şey. (3) Sorumluluk.","otr":["Asker işini dürüstlükle yapar.","Allah size emanetleri ehline vermenizi emrediyor.","Biz emaneti göklere, yere ve dağlara sunduk."],"r":null,"s":29},
{"k":"إمْبِراطور","c":"أَباطِرَة","m":"(ج) أَباطِرَة : لَقَبٌ مِنْ أَلْقابِ الحاكِمِ ، وَمِنْ أَمْثِلَتِهِ اليَوْمَ إمْبِراطورُ اليابانِ .","t":"لَقَبٌ مِنْ أَلْقابِ الحاكِمِ","o":["وَمِنْ أَمْثِلَتِهِ اليَوْمَ إمْبِراطورُ اليابانِ"],"b":["وَمِنْ أَمْثِلَتِهِ اليَوْمَ إمْبِراطورُ اليابانِ","إمْبِراطورُ"],"tr":"imparator","ttr":"Hükümdar unvanlarından biri.","otr":["Bugünkü örneklerinden biri Japonya imparatorudur."],"r":null,"s":29},
{"k":"أَمَة","c":"إماء","m":"(ج) إماء ، المَرْأَةُ العَبْدَةُ ؛ خِلافُ الحُرَّةِ ، ﴿وَلَأَمَةٌ مُؤْمِنَةٌ خَيْرٌ مِنْ مُشْرِكَةٍ وَلَوْ أَعْجَبَتْكُمْ﴾ ، ﴿وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ﴾ .","t":"المَرْأَةُ العَبْدَةُ ؛ خِلافُ الحُرَّةِ","o":["﴿وَلَأَمَةٌ مُؤْمِنَةٌ خَيْرٌ مِنْ مُشْرِكَةٍ وَلَوْ أَعْجَبَتْكُمْ﴾","﴿وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ﴾"],"b":["﴿وَلَأَمَةٌ مُؤْمِنَةٌ خَيْرٌ مِنْ مُشْرِكَةٍ وَلَوْ أَعْجَبَتْكُمْ﴾","وَلَأَمَةٌ"],"tr":"cariye","ttr":"Köle kadın; hür kadının zıddı.","otr":["Mümin bir cariye, hoşunuza gitse bile müşrik bir kadından daha hayırlıdır.","Aranızdaki bekârları, kölelerinizden ve cariyelerinizden salih olanları evlendirin."],"r":null,"s":29,"y":[["جمع","إماء"]]},
{"k":"أُمَّة","c":"أُمَم","m":"(ج) أُمَم : (١) جَماعَةٌ كَبيرَةٌ مِنَ النّاسِ تَجْمَعُ بَيْنَها عَلاقَةٌ كالدِّينِ أَوِ اللُّغَةِ أَوِ العِرْقِ ، “الأُمَّةُ العَرَبِيَّةُ جُزْءٌ مِنَ الأُمَّةِ الإسْلامِيَّةِ” ، “دَخَلَتْ في الإسْلامِ أُمَمٌ كَثيرَةٌ في الشَّرْقِ وَالغَرْبِ” . (٢) مُدَّةٌ مِنَ الزَّمَنِ ، ﴿وَقَالَ الَّذِي نَجَا مِنْهُمَا وَادَّكَرَ بَعْدَ أُمَّةٍ﴾ .","t":"(١) جَماعَةٌ كَبيرَةٌ مِنَ النّاسِ تَجْمَعُ بَيْنَها عَلاقَةٌ كالدِّينِ أَوِ اللُّغَةِ أَوِ العِرْقِ . (٢) مُدَّةٌ مِنَ الزَّمَنِ","o":["الأُمَّةُ العَرَبِيَّةُ جُزْءٌ مِنَ الأُمَّةِ الإسْلامِيَّةِ","دَخَلَتْ في الإسْلامِ أُمَمٌ كَثيرَةٌ في الشَّرْقِ وَالغَرْبِ","﴿وَقَالَ الَّذِي نَجَا مِنْهُمَا وَادَّكَرَ بَعْدَ أُمَّةٍ﴾"],"b":["الأُمَّةُ العَرَبِيَّةُ جُزْءٌ مِنَ الأُمَّةِ الإسْلامِيَّةِ","الأُمَّةُ"],"tr":"ümmet, millet","ttr":"(1) Aralarında din, dil veya soy gibi bir bağ bulunan büyük insan topluluğu. (2) Bir zaman dilimi.","otr":["Arap milleti İslam ümmetinin bir parçasıdır.","Doğuda ve batıda pek çok millet İslam'a girdi.","İkisinden kurtulmuş olan, bir süre sonra (Yusuf'u) hatırlayıp dedi ki..."],"r":null,"s":29},
{"k":"إِنْ","c":"","m":"( ١ ) أَداةُ شَرْطٍ ؛ تَجْزِمُ فِعْلَيْنِ ، “إِنْ تَحْضُرْ مُبَكِّراً تأخُذْ ما تُريدُ” . ( ٢ ) نافِيَة ، ﴿ إِنْ أَنْتُمْ إِلاّ في ضَلالٍ مُبينٍ ﴾ . ( ٣ ) زائِدَة ، “ما إِنْ فَعلتُ شَيْئاً خَطيراً” .","t":"( ١ ) أَداةُ شَرْطٍ ؛ تَجْزِمُ فِعْلَيْنِ ( ٢ ) نافِيَة ( ٣ ) زائِدَة","o":["إِنْ تَحْضُرْ مُبَكِّراً تأخُذْ ما تُريدُ","﴿ إِنْ أَنْتُمْ إِلاّ في ضَلالٍ مُبينٍ ﴾","ما إِنْ فَعلتُ شَيْئاً خَطيراً"],"b":["إِنْ تَحْضُرْ مُبَكِّراً تأخُذْ ما تُريدُ","إِنْ"],"tr":"eğer; değil (nefy)","ttr":"(1) İki fiili cezmeden şart edatı. (2) Olumsuzluk edatı. (3) Zâid (fazladan gelen) edat.","otr":["Erken gelirsen istediğini alırsın.","Siz ancak apaçık bir sapıklık içindesiniz.","Tehlikeli hiçbir şey yapmadım."],"r":null,"s":32},
{"k":"آنَئِذٍ","c":"","m":"في ذلكَ الوَقْتِ ، “عِنْدَما نَشِبَتِ الحَرْبُ كانَ عُمْري آنَئِذ خَمْسَةَ عَشَرَ عاماً” .","t":"في ذلكَ الوَقْتِ","o":["عِنْدَما نَشِبَتِ الحَرْبُ كانَ عُمْري آنَئِذ خَمْسَةَ عَشَرَ عاماً"],"b":["عِنْدَما نَشِبَتِ الحَرْبُ كانَ عُمْري آنَئِذ خَمْسَةَ عَشَرَ عاماً","آنَئِذ"],"tr":"o zaman, o sırada","ttr":"O vakit.","otr":["Savaş patlak verdiğinde o sırada on beş yaşındaydım."],"r":null,"s":32},
{"k":"أَنا","c":"","m":"ضَميرُ رَفْعٍ مُنْفَصِلٍ لِلمُتَكَلِّمِ مُذَكَّرٍ أَو مُؤَنَّثٍ ، قالَ الرَّسولُ ﷺ : (أنا سَيِّدُ وَلَدِ آدمَ ولا فَخْرَ) .","t":"ضَميرُ رَفْعٍ مُنْفَصِلٍ لِلمُتَكَلِّمِ مُذَكَّرٍ أَو مُؤَنَّثٍ","o":["أنا سَيِّدُ وَلَدِ آدمَ ولا فَخْرَ"],"b":["أنا سَيِّدُ وَلَدِ آدمَ ولا فَخْرَ","أنا"],"tr":"ben","ttr":"Eril veya dişil birinci tekil şahıs için ayrık merfû zamir.","otr":["Resûlullah (s.a.v.) buyurdu: Ben Âdemoğlunun efendisiyim, (bununla) övünmek yok."],"r":null,"s":32},
{"k":"إِناء","c":"أَوانٍ (الأَواني)","m":"(ج) أَوانٍ (الأَواني) : وِعاءٌ لِلطَّعامِ والشَّرابِ ، مِثْلِ الصُّحونِ والأَطْباقِ ، “اشْتَرينا أَوانيَ لِلمَطْبَخِ ؛ كَالمَلاعِقِ وَالأَطْباقِ ، وَالسَّكاكينِ وَغَيْرِها” ..","t":"وِعاءٌ لِلطَّعامِ والشَّرابِ ، مِثْلِ الصُّحونِ والأَطْباقِ","o":["اشْتَرينا أَوانيَ لِلمَطْبَخِ ؛ كَالمَلاعِقِ وَالأَطْباقِ ، وَالسَّكاكينِ وَغَيْرِها"],"b":["اشْتَرينا أَوانيَ لِلمَطْبَخِ ؛ كَالمَلاعِقِ وَالأَطْباقِ ، وَالسَّكاكينِ وَغَيْرِها","أَوانيَ"],"tr":"kap","ttr":"Tabaklar ve sahanlar gibi yiyecek ve içecek kabı.","otr":["Mutfak için kaşık, tabak, bıçak gibi kap kacak satın aldık."],"r":"p32_1","s":32},
{"k":"أَنابَ","c":"","m":"يُنيبُ إِنابَةً : رَجَعَ أَو تابَ ، “أَنابَ العَبْدُ إِلى رَبِّه” ، ﴿ وَأَنيبوا إِلى رَبِّكُمْ وَأَسْلِموا لَه ﴾ .","t":"رَجَعَ أَو تابَ","o":["أَنابَ العَبْدُ إِلى رَبِّه","﴿ وَأَنيبوا إِلى رَبِّكُمْ وَأَسْلِموا لَه ﴾"],"b":["أَنابَ العَبْدُ إِلى رَبِّه","أَنابَ"],"tr":"(Allah'a) yönelmek, tövbe etmek","ttr":"Dönmek veya tövbe etmek.","otr":["Kul Rabbine yöneldi (tövbe etti).","Rabbinize yönelin ve O'na teslim olun."],"r":null,"s":32,"f":"يُنيبُ إِنابَةً"},
{"k":"أَنارَ","c":"","m":"يُنيرُ إِنارَةً : أَضاءَ وَأَشْعَلَ ؛ خِلافُ أَظْلَمَ وأَطْفَأَ ، “أَنارَتِ الدَّوْلَةُ الشَّوارِعَ العامَّةَ” .","t":"أَضاءَ وَأَشْعَلَ ؛ خِلافُ أَظْلَمَ وأَطْفَأَ","o":["أَنارَتِ الدَّوْلَةُ الشَّوارِعَ العامَّةَ"],"b":["أَنارَتِ الدَّوْلَةُ الشَّوارِعَ العامَّةَ","أَنارَتِ"],"tr":"aydınlatmak","ttr":"Işık vermek, yakmak; karartmak ve söndürmenin zıddı.","otr":["Devlet ana caddeleri aydınlattı."],"r":"p32_2","s":32,"f":"يُنيرُ إِنارَةً"},
{"k":"أُناسٌ","c":"","m":"بَشَرٌ ، وَيُخَفَّفُ بِحَذْفِ الهَمْزَةِ هكَذا “ناس” . ﴿ يَوْمَ نَدْعُو كُلَّ أُناسٍ بِإِمامِهِمْ ﴾ ، ﴿ قُلْ أَعُوذُ بِرَبِّ النَّاسِ ﴾ .","t":"بَشَرٌ ، وَيُخَفَّفُ بِحَذْفِ الهَمْزَةِ هكَذا “ناس”","o":["﴿ يَوْمَ نَدْعُو كُلَّ أُناسٍ بِإِمامِهِمْ ﴾","﴿ قُلْ أَعُوذُ بِرَبِّ النَّاسِ ﴾"],"b":["يَوْمَ نَدْعُو كُلَّ أُناسٍ بِإِمامِهِمْ","أُناسٍ"],"tr":"insanlar","ttr":"İnsanlar; hemzesi düşürülerek “nâs” şeklinde de hafifletilir.","otr":["Her insan topluluğunu önderleriyle çağıracağımız gün...","De ki: İnsanların Rabbine sığınırım."],"r":null,"s":32},
{"k":"أَنَّبَ","c":"","m":"يُؤَنِّبُ تَأْنيباً : وَبَّخَ ، ولامَ ، “أَنَّبَ الوالِدُ ابْنَهُ عَلى ما فَعَلَ مِنْ أَخْطاءٍ” .","t":"وَبَّخَ ، ولامَ","o":["أَنَّبَ الوالِدُ ابْنَهُ عَلى ما فَعَلَ مِنْ أَخْطاءٍ"],"b":["أَنَّبَ الوالِدُ ابْنَهُ عَلى ما فَعَلَ مِنْ أَخْطاءٍ","أَنَّبَ"],"tr":"azarlamak","ttr":"Azarlamak, kınamak.","otr":["Baba, oğlunu yaptığı hatalardan dolayı azarladı."],"r":null,"s":32,"f":"يُؤَنِّبُ تَأْنيباً"},
{"k":"أَنْبَأَ","c":"","m":"يُنْبِئُ إِنْباءً : أَخْبَرَ ، أَعْلَمَ ، “أَنْبَأَتِ الشَّرِكَةُ العُمّالَ بِزِيادَةِ الرَّواتِبِ” ، ﴿ قالَتْ مَنْ أَنْبَأَكَ هَذا قالَ نَبَّأَنِيَ الْعَليمُ الْخَبيرُ ﴾ .","t":"أَخْبَرَ ، أَعْلَمَ","o":["أَنْبَأَتِ الشَّرِكَةُ العُمّالَ بِزِيادَةِ الرَّواتِبِ","﴿ قالَتْ مَنْ أَنْبَأَكَ هَذا قالَ نَبَّأَنِيَ الْعَليمُ الْخَبيرُ ﴾"],"b":["أَنْبَأَتِ الشَّرِكَةُ العُمّالَ بِزِيادَةِ الرَّواتِبِ","أَنْبَأَتِ"],"tr":"haber vermek","ttr":"Haber vermek, bildirmek.","otr":["Şirket işçilere maaş artışını bildirdi.","(Kadın) “Bunu sana kim haber verdi?” dedi. “Her şeyi bilen, her şeyden haberdar olan haber verdi” dedi."],"r":null,"s":32,"f":"يُنْبِئُ إِنْباءً"},
{"k":"أَنْبَتَ","c":"","m":"يُنْبِتُ إِنْباتاً : أَخْرَجَ النَّباتَ ، ﴿ يُنْبِتُ لَكُمْ بِهِ الزَّرْعَ وَالزَّيْتُونَ وَالنَّخيلَ وَالأَعْنابَ ﴾ .","t":"أَخْرَجَ النَّباتَ","o":["﴿ يُنْبِتُ لَكُمْ بِهِ الزَّرْعَ وَالزَّيْتُونَ وَالنَّخيلَ وَالأَعْنابَ ﴾"],"b":["يُنْبِتُ لَكُمْ بِهِ الزَّرْعَ وَالزَّيْتُونَ وَالنَّخيلَ وَالأَعْنابَ","يُنْبِتُ"],"tr":"bitirmek, yetiştirmek","ttr":"Bitki çıkarmak, yetiştirmek.","otr":["Onunla sizin için ekin, zeytin, hurma ve üzüm yetiştirir."],"r":null,"s":32,"f":"يُنْبِتُ إِنْباتاً"},
{"k":"أَنْتِ","c":"أَنْتُنَّ","m":"ضَميرُ رَفْعٍ مُنْفَصِلٌ لِلمُخاطَبَةِ ، أَنْتِ(مؤ) ، (ج) أَنْتُنَّ ، وَالمُثَنّى أَنْتُما ، “يا فاطِمَةُ أَنتِ الَّتي فُزْتِ بِجائِزَةِ حِفْظِ القُرْآنِ الكَريمِ وَتِلاوَتِه” .","t":"ضَميرُ رَفْعٍ مُنْفَصِلٌ لِلمُخاطَبَةِ ، وَالمُثَنّى أَنْتُما","o":["يا فاطِمَةُ أَنتِ الَّتي فُزْتِ بِجائِزَةِ حِفْظِ القُرْآنِ الكَريمِ وَتِلاوَتِه"],"b":["يا فاطِمَةُ أَنتِ الَّتي فُزْتِ بِجائِزَةِ حِفْظِ القُرْآنِ الكَريمِ وَتِلاوَتِه","أَنتِ"],"tr":"sen (dişil)","ttr":"İkinci tekil şahıs dişil için ayrık merfû zamir; ikili: entumâ, çoğul: entunne.","otr":["Ey Fatıma, Kur'ân-ı Kerîm'i ezberleme ve okuma ödülünü kazanan sensin."],"r":null,"s":32},
{"k":"أَنْتَ","c":"أَنْتُم","m":"ضَميرُ رَفْعٍ مُنْفَصِلٌ لِلمُخاطَبِ(مذ) ، أَنتَ (ج) أَنْتُم ، وَالمُثَنّى أَنْتُما ، “أَنْتَ رَجُلٌ كَريمٌ” ، ﴿ أَأَنْتَ قُلْتَ لِلنَّاسِ اتَّخِذُوني وَأُمِّيَ إِلَهَيْنِ مِنْ دُونِ اللَّه ﴾ .","t":"ضَميرُ رَفْعٍ مُنْفَصِلٌ لِلمُخاطَبِ ، وَالمُثَنّى أَنْتُما","o":["أَنْتَ رَجُلٌ كَريمٌ","﴿ أَأَنْتَ قُلْتَ لِلنَّاسِ اتَّخِذُوني وَأُمِّيَ إِلَهَيْنِ مِنْ دُونِ اللَّه ﴾"],"b":["أَنْتَ رَجُلٌ كَريمٌ","أَنْتَ"],"tr":"sen (eril)","ttr":"İkinci tekil şahıs eril için ayrık merfû zamir; ikili: entumâ, çoğul: entum.","otr":["Sen cömert bir adamsın.","İnsanlara “Beni ve annemi Allah'tan başka iki ilah edinin” diyen sen misin?"],"r":null,"s":32},
{"k":"أَنْتَجَ","c":"","m":"يُنْتِجُ إِنْتاجاً : ( ١ ) وَلَدَتْ وَظَهَرَ نِتاجُها ، “أَنْتَجَتِ الشّاةُ ذُكوراً وَإِناثاً” . ( ٢ ) أَثْمَرَ ، “أَنْتَجَتِ النَّخْلَةُ كَثيراً مِنَ التَّمرِ” . ( ٣ ) صَنَّعَ ، “يُنتِجُ المَصْنَعُ الصابونَ وَالعُطورَ” ، “زادَ إِنْتاجُ البِلادِ الصِّناعيّ” .","t":"( ١ ) وَلَدَتْ وَظَهَرَ نِتاجُها ( ٢ ) أَثْمَرَ ( ٣ ) صَنَّعَ","o":["أَنْتَجَتِ الشّاةُ ذُكوراً وَإِناثاً","أَنْتَجَتِ النَّخْلَةُ كَثيراً مِنَ التَّمرِ","يُنتِجُ المَصْنَعُ الصابونَ وَالعُطورَ","زادَ إِنْتاجُ البِلادِ الصِّناعيّ"],"b":["يُنتِجُ المَصْنَعُ الصابونَ وَالعُطورَ","يُنتِجُ"],"tr":"üretmek","ttr":"(1) (Hayvan) doğurmak, yavrusu ortaya çıkmak. (2) Meyve vermek. (3) İmal etmek, üretmek.","otr":["Koyun erkek ve dişi yavrular doğurdu.","Hurma ağacı çok hurma verdi.","Fabrika sabun ve parfüm üretir.","Ülkenin sanayi üretimi arttı."],"r":null,"s":32,"y":[["مصدر","إِنْتاج"]],"f":"يُنْتِجُ إِنْتاجاً"},
{"k":"أَنْجَبَ","c":"","m":"يُنْجِبُ إِنْجاباً : وَلَدَ ، “أَنْجَبَتِ الأُمُّ مَوْلوداً جَميلاً” .","t":"وَلَدَ","o":["أَنْجَبَتِ الأُمُّ مَوْلوداً جَميلاً"],"b":["أَنْجَبَتِ الأُمُّ مَوْلوداً جَميلاً","أَنْجَبَتِ"],"tr":"çocuk doğurmak","ttr":"Doğurmak, evlat sahibi olmak.","otr":["Anne güzel bir bebek dünyaya getirdi."],"r":null,"s":32,"f":"يُنْجِبُ إِنْجاباً"},
{"k":"أَنْجَحَ","c":"","m":"يُنْجِحُ إِنْجاحاً : جَعَلَهُ يَنْجَحُ ، “أَنْجَحَهُ في حَياتِه ، اعْتِمادُهُ عَلَى اللهِ ، ثُمَّ عَلَى نَفْسِهِ” .","t":"جَعَلَهُ يَنْجَحُ","o":["أَنْجَحَهُ في حَياتِه ، اعْتِمادُهُ عَلَى اللهِ ، ثُمَّ عَلَى نَفْسِهِ"],"b":["أَنْجَحَهُ في حَياتِه ، اعْتِمادُهُ عَلَى اللهِ ، ثُمَّ عَلَى نَفْسِهِ","أَنْجَحَهُ"],"tr":"başarılı kılmak","ttr":"Birini başarılı kılmak.","otr":["Onu hayatında başarılı kılan, önce Allah'a sonra kendine güvenmesiydi."],"r":null,"s":32,"f":"يُنْجِحُ إِنْجاحاً"},
{"k":"أَنْجَدَ","c":"","m":"يُنْجِدُ إِنْجاداً : نَصَرَ ، أَعانَ ، “اسْتَغاثَ الغَريقُ ، فَأَنْجَدَهُ سَبّاحٌ ماهِرٌ” ، “أَنْجَدَتْ سَيّارَةُ الإِسْعافِ المَريضَ” .","t":"نَصَرَ ، أَعانَ","o":["اسْتَغاثَ الغَريقُ ، فَأَنْجَدَهُ سَبّاحٌ ماهِرٌ","أَنْجَدَتْ سَيّارَةُ الإِسْعافِ المَريضَ"],"b":["اسْتَغاثَ الغَريقُ ، فَأَنْجَدَهُ سَبّاحٌ ماهِرٌ","فَأَنْجَدَهُ"],"tr":"yardımına koşmak, kurtarmak","ttr":"Yardım etmek, imdadına yetişmek.","otr":["Boğulmak üzere olan kişi yardım istedi, usta bir yüzücü onun imdadına yetişti.","Ambulans hastanın yardımına yetişti."],"r":"p32_3","s":32,"f":"يُنْجِدُ إِنْجاداً"},
{"k":"أَنْجَزَ","c":"","m":"يُنْجِزُ إِنْجازاً : أَتَمَّ ، أَكْمَلَ ، “أَنْجَزَ طارِقٌ ما كُلِّفَ بِهِ مِنْ عَمَلٍ” ، “أَنْجَزَ العامِلُ عَمَلَهُ في الوَقْتِ المُحَدَّدِ” .","t":"أَتَمَّ ، أَكْمَلَ","o":["أَنْجَزَ طارِقٌ ما كُلِّفَ بِهِ مِنْ عَمَلٍ","أَنْجَزَ العامِلُ عَمَلَهُ في الوَقْتِ المُحَدَّدِ"],"b":["أَنْجَزَ العامِلُ عَمَلَهُ في الوَقْتِ المُحَدَّدِ","أَنْجَزَ"],"tr":"tamamlamak, bitirmek","ttr":"Tamamlamak, bitirmek.","otr":["Tarık kendisine verilen işi tamamladı.","İşçi işini belirlenen vakitte bitirdi."],"r":null,"s":32,"y":[["مصدر","إِنْجاز"]],"f":"يُنْجِزُ إِنْجازاً"},
{"k":"إِنْجيل","c":"أَناجيل","m":"(ج) أَناجيل : الكِتابُ الَّذي أَنْزَلَهُ اللهُ - عَزَّ وَجَلَّ - عَلى نَبِيِّهِ عيسَى بْنِ مَرْيَمَ عَلَيْهِ السَّلامُ ، ﴿ ثُمَّ قَفَّيْنا عَلى آثارِهِمْ بِرُسُلِنا وَقَفَّيْنا بِعيسَى ابْنِ مَرْيَمَ وَآتَيْناهُ الإِنْجيلَ ﴾ .","t":"الكِتابُ الَّذي أَنْزَلَهُ اللهُ - عَزَّ وَجَلَّ - عَلى نَبِيِّهِ عيسَى بْنِ مَرْيَمَ عَلَيْهِ السَّلامُ","o":["﴿ ثُمَّ قَفَّيْنا عَلى آثارِهِمْ بِرُسُلِنا وَقَفَّيْنا بِعيسَى ابْنِ مَرْيَمَ وَآتَيْناهُ الإِنْجيلَ ﴾"],"b":["ثُمَّ قَفَّيْنا عَلى آثارِهِمْ بِرُسُلِنا وَقَفَّيْنا بِعيسَى ابْنِ مَرْيَمَ وَآتَيْناهُ الإِنْجيلَ","الإِنْجيلَ"],"tr":"İncil","ttr":"Allah'ın (azze ve celle) peygamberi Meryem oğlu İsa'ya (a.s.) indirdiği kitap.","otr":["Sonra onların izleri üzerinde peşlerinden peygamberlerimizi gönderdik; Meryem oğlu İsa'yı da arkalarından gönderdik ve ona İncil'i verdik."],"r":null,"s":32},
{"k":"إِنْذار","c":"","m":"تَهْديد ، تَخْويف ، “جاءَهُ إِنْذارٌ بِالفَصْلِ مِنَ العَمَلِ” .","t":"تَهْديد ، تَخْويف","o":["جاءَهُ إِنْذارٌ بِالفَصْلِ مِنَ العَمَلِ"],"b":["جاءَهُ إِنْذارٌ بِالفَصْلِ مِنَ العَمَلِ","إِنْذارٌ"],"tr":"uyarı, ihtar","ttr":"Tehdit, korkutma.","otr":["İşten çıkarılacağına dair bir ihtar aldı."],"r":null,"s":33},
{"k":"آنَذاكَ","c":"","m":"في ذَلِكَ الوَقْتِ أَو في ذلِكَ الحينِ وَالزَّمانِ ، “عِنْدَما انْدَلَعَتِ الحَرْبُ ، كانَ عُمْري آنَذاكَ سِتَّ سِنينَ” .","t":"في ذَلِكَ الوَقْتِ أَو في ذلِكَ الحينِ وَالزَّمانِ","o":["عِنْدَما انْدَلَعَتِ الحَرْبُ ، كانَ عُمْري آنَذاكَ سِتَّ سِنينَ"],"b":["عِنْدَما انْدَلَعَتِ الحَرْبُ ، كانَ عُمْري آنَذاكَ سِتَّ سِنينَ","آنَذاكَ"],"tr":"o zaman, o sıralar","ttr":"O vakit, o sırada ve o zamanda.","otr":["Savaş çıktığında o sıralar altı yaşındaydım."],"r":null,"s":33},
{"k":"أَنْذَرَ","c":"","m":"يُنْذِرُ إِنْذاراً : حَذَّرَ ، وَأَعْلَمَ بِلَهْجَةٍ فيها تَهْديدٌ وَوَعيدٌ ، في المَثَلِ : “مَنْ أَنْذَرَ فَقَدْ أَعْذَرَ” ، ﴿ وَأَنْذِرِ النَّاسَ يَوْمَ يَأْتيهِمُ العَذابُ ﴾ .","t":"حَذَّرَ ، وَأَعْلَمَ بِلَهْجَةٍ فيها تَهْديدٌ وَوَعيدٌ","o":["مَنْ أَنْذَرَ فَقَدْ أَعْذَرَ","﴿ وَأَنْذِرِ النَّاسَ يَوْمَ يَأْتيهِمُ العَذابُ ﴾"],"b":["مَنْ أَنْذَرَ فَقَدْ أَعْذَرَ","أَنْذَرَ"],"tr":"uyarmak, ihtar etmek","ttr":"Sakındırmak; tehdit içeren bir dille bildirmek.","otr":["Atasözü: Önceden uyaran, mazeretini ortaya koymuş olur.","İnsanları, azabın kendilerine geleceği gün hakkında uyar."],"r":null,"s":33,"f":"يُنْذِرُ إِنْذاراً"},
{"k":"أَنْزَلَ","c":"","m":"يُنْزِلُ ، إِنْزالاً : ( ١ ) جَعَلَهُ يَنْزِلُ . “أَنْزَلَ الحَمّالُ الحَقائِبَ مِنَ السَّيّارَةِ” . ( ٢ ) أَوْحَى ، ﴿ هُوَ الَّذي أَنْزَلَ عَلَيْكَ الْكِتابَ مِنْهُ آياتٌ مُحْكَماتٌ ﴾ .","t":"( ١ ) جَعَلَهُ يَنْزِلُ ( ٢ ) أَوْحَى","o":["أَنْزَلَ الحَمّالُ الحَقائِبَ مِنَ السَّيّارَةِ","﴿ هُوَ الَّذي أَنْزَلَ عَلَيْكَ الْكِتابَ مِنْهُ آياتٌ مُحْكَماتٌ ﴾"],"b":["أَنْزَلَ الحَمّالُ الحَقائِبَ مِنَ السَّيّارَةِ","أَنْزَلَ"],"tr":"indirmek","ttr":"(1) İndirmek. (2) Vahyetmek.","otr":["Hamal çantaları arabadan indirdi.","Sana Kitab'ı indiren O'dur; onun bazı ayetleri muhkemdir."],"r":"p33_1","s":33},
{"k":"آنَسَ","c":"","m":"يُؤانِسُ مُؤانَسَةً وَإيناساً : ( ١ ) لاطَفَ وَأَزالَ الوَحْشَةَ وَالخَوْفَ مِنَ الشَّخْصِ ، “آنَسْتُ الطِّفْلَ لَمّا أَحْسَسْتُ أَنَّهُ خائِفٌ مِنّي” . ( ٢ ) أَبْصَرَ وَشاهَدَ ، ﴿ فَلَمّا قَضى مُوسَى الأَجَلَ وَسارَ بِأَهْلِهِ آنَسَ مِنْ جانِبِ الطُّورِ ناراً قالَ لِأَهْلِهِ امْكُثُوا إِنّي آنَسْتُ ناراً لَعَلّي آتيكُمْ مِنْها بِخَبَرٍ ﴾ .","t":"( ١ ) لاطَفَ وَأَزالَ الوَحْشَةَ وَالخَوْفَ مِنَ الشَّخْصِ ( ٢ ) أَبْصَرَ وَشاهَدَ","o":["آنَسْتُ الطِّفْلَ لَمّا أَحْسَسْتُ أَنَّهُ خائِفٌ مِنّي","﴿ فَلَمّا قَضى مُوسَى الأَجَلَ وَسارَ بِأَهْلِهِ آنَسَ مِنْ جانِبِ الطُّورِ ناراً قالَ لِأَهْلِهِ امْكُثُوا إِنّي آنَسْتُ ناراً لَعَلّي آتيكُمْ مِنْها بِخَبَرٍ ﴾"],"b":["آنَسْتُ الطِّفْلَ لَمّا أَحْسَسْتُ أَنَّهُ خائِفٌ مِنّي","آنَسْتُ"],"tr":"gönlünü almak; fark etmek","ttr":"(1) Birine yumuşak davranıp yalnızlık ve korkusunu gidermek. (2) Görmek, fark etmek.","otr":["Çocuğun benden korktuğunu hissedince ona yakınlık gösterip korkusunu giderdim.","Musa süreyi doldurup ailesiyle yola çıkınca Tûr tarafında bir ateş gördü ve ailesine: “Bekleyin, ben bir ateş gördüm; belki oradan size bir haber getiririm” dedi."],"r":null,"s":33},
{"k":"أَنِسَ","c":"","m":"يَأْنَسُ أُنْساً : أَحَبَّ وَارْتاحَ ، “أَنِسْتُ لِكَلامِهِ اللَّطيفِ” .","t":"أَحَبَّ وَارْتاحَ","o":["أَنِسْتُ لِكَلامِهِ اللَّطيفِ"],"b":["أَنِسْتُ لِكَلامِهِ اللَّطيفِ","أَنِسْتُ"],"tr":"ısınmak, hoşlanmak","ttr":"Sevmek ve rahatlamak, huzur bulmak.","otr":["Onun nazik sözlerinden hoşlandım (onlarla huzur buldum)."],"r":null,"s":33,"f":"يَأْنَسُ أُنْساً"},
{"k":"إِنْسان","c":"أَناسِيّ وناس","m":"(ج) أَناسِيّ وَناس : أَحَدُ أَفْرادِ البَشَرِ خِلافُ الحَيَوانِ ، ﴿ أَيَحْسَبُ الإِنْسانُ أَنْ يُتْرَكَ سُدىً ﴾ .","t":"أَحَدُ أَفْرادِ البَشَرِ خِلافُ الحَيَوانِ","o":["﴿ أَيَحْسَبُ الإِنْسانُ أَنْ يُتْرَكَ سُدىً ﴾"],"b":["أَيَحْسَبُ الإِنْسانُ أَنْ يُتْرَكَ سُدىً","الإِنْسانُ"],"tr":"insan","ttr":"Hayvanın aksine, insan türünün fertlerinden biri.","otr":["İnsan, başıboş bırakılacağını mı sanır?"],"r":null,"s":33},
{"k":"إِنْسانِيَّة","c":"","m":"مَجْموعَةُ الصِّفاتِ الَّتي تُمَيِّزُ الإِنْسانَ ؛ خِلافُ الحَيَوانِيَّةِ وَالبَهيمِيَّةِ ، “شَنُّ الحَرْبِ عَلى الضُّعَفاءِ لَيْسَ مِنَ الإِنْسانِيَّةِ” .","t":"مَجْموعَةُ الصِّفاتِ الَّتي تُمَيِّزُ الإِنْسانَ ؛ خِلافُ الحَيَوانِيَّةِ وَالبَهيمِيَّةِ","o":["شَنُّ الحَرْبِ عَلى الضُّعَفاءِ لَيْسَ مِنَ الإِنْسانِيَّةِ"],"b":["شَنُّ الحَرْبِ عَلى الضُّعَفاءِ لَيْسَ مِنَ الإِنْسانِيَّةِ","الإِنْسانِيَّةِ"],"tr":"insanlık","ttr":"İnsanı ayırt eden özelliklerin bütünü; hayvanlık ve vahşiliğin zıddı.","otr":["Zayıflara savaş açmak insanlığa sığmaz."],"r":null,"s":33},
{"k":"أَنْسَى","c":"","m":"يُنْسي إِنْساءً : جَعَلَهُ يَنْسى الشَّيْءَ ، “أَنْسَتْهُ مَسْؤُولِيّاتُهُ الكَثيرَةُ أَوْلادَهُ” ، ﴿ وَما أَنْسانيهُ إِلّا الشَّيْطانُ أَنْ أَذْكُرَهُ ﴾ .","t":"جَعَلَهُ يَنْسى الشَّيْءَ","o":["أَنْسَتْهُ مَسْؤُولِيّاتُهُ الكَثيرَةُ أَوْلادَهُ","﴿ وَما أَنْسانيهُ إِلّا الشَّيْطانُ أَنْ أَذْكُرَهُ ﴾"],"b":["أَنْسَتْهُ مَسْؤُولِيّاتُهُ الكَثيرَةُ أَوْلادَهُ","أَنْسَتْهُ"],"tr":"unutturmak","ttr":"Birine bir şeyi unutturmak.","otr":["Çok sayıdaki sorumlulukları ona çocuklarını unutturdu.","Onu hatırlamamı bana ancak şeytan unutturdu."],"r":null,"s":33,"f":"يُنْسي إِنْساءً"},
{"k":"أَنْشَأَ","c":"","m":"يُنْشِئُ إِنْشاءً : ( ١ ) أَقامَ وَأَوْجَدَ وَأَحْدَثَ ، “أَنْشَأَتِ الدَّوْلَةُ كَثيراً مِنَ المُسْتَشْفَياتِ” . ( ٢ ) أَلَّفَ ، “أَنْشَأَ الكاتِبُ مَقالَةً جَيِّدَةً” . ( ٣ ) خَلَقَ ، ﴿ وَهُوَ الَّذي أَنْشَأَكُمْ مِنْ نَفْسٍ واحِدَةٍ ﴾ . ( ٤ ) الإِنْشاء : التَّعبيرُ الكِتابِيُّ ، “مادَّةُ الإِنْشاءِ مِنْ أَهَمِّ مَوادِّ اللُّغَةِ” .","t":"( ١ ) أَقامَ وَأَوْجَدَ وَأَحْدَثَ ( ٢ ) أَلَّفَ ( ٣ ) خَلَقَ ( ٤ ) الإِنْشاء : التَّعبيرُ الكِتابِيُّ","o":["أَنْشَأَتِ الدَّوْلَةُ كَثيراً مِنَ المُسْتَشْفَياتِ","أَنْشَأَ الكاتِبُ مَقالَةً جَيِّدَةً","﴿ وَهُوَ الَّذي أَنْشَأَكُمْ مِنْ نَفْسٍ واحِدَةٍ ﴾","مادَّةُ الإِنْشاءِ مِنْ أَهَمِّ مَوادِّ اللُّغَةِ"],"b":["أَنْشَأَتِ الدَّوْلَةُ كَثيراً مِنَ المُسْتَشْفَياتِ","أَنْشَأَتِ"],"tr":"kurmak, inşa etmek","ttr":"(1) Kurmak, var etmek, meydana getirmek. (2) (Yazı) kaleme almak. (3) Yaratmak. (4) el-İnşâ: yazılı anlatım, kompozisyon.","otr":["Devlet birçok hastane kurdu.","Yazar güzel bir makale kaleme aldı.","Sizi tek bir nefisten yaratan O'dur.","Kompozisyon dersi, dilin en önemli derslerindendir."],"r":null,"s":33,"y":[["مصدر","إِنْشاء"]],"f":"يُنْشِئُ إِنْشاءً"},
{"k":"أَنْشَدَ","c":"","m":"يُنْشِدُ إِنْشاداً : ( ١ ) غَنَّى شِعْراً ، “عِنْدَما دَخَلَ الرَّسولُ ﷺ المَدينَةَ ، أَنْشَدَ النّاسُ : ‹طَلَعَ البَدْرُ عَلَيْنا›” . ( ٢ ) قَرَأَ الشِّعْرَ بِصَوْتٍ مَسْموعٍ ، “أَنْشَدَ الشّاعِرُ عَدَداً مِنْ قَصائِدِهِ الجَديدَةِ في الحَفْلِ” .","t":"( ١ ) غَنَّى شِعْراً ( ٢ ) قَرَأَ الشِّعْرَ بِصَوْتٍ مَسْموعٍ","o":["عِنْدَما دَخَلَ الرَّسولُ ﷺ المَدينَةَ ، أَنْشَدَ النّاسُ : طَلَعَ البَدْرُ عَلَيْنا","أَنْشَدَ الشّاعِرُ عَدَداً مِنْ قَصائِدِهِ الجَديدَةِ في الحَفْلِ"],"b":["أَنْشَدَ الشّاعِرُ عَدَداً مِنْ قَصائِدِهِ الجَديدَةِ في الحَفْلِ","أَنْشَدَ"],"tr":"şiir okumak, ilahi söylemek","ttr":"(1) Şiiri ezgiyle söylemek. (2) Şiiri yüksek sesle okumak.","otr":["Resûlullah (s.a.v.) Medine'ye girdiğinde insanlar “Tala'al-bedru aleynâ” ilahisini söylediler.","Şair törende yeni kasidelerinden birkaçını okudu."],"r":null,"s":33,"y":[["مصدر","إِنْشاد"]],"f":"يُنْشِدُ إِنْشاداً"},
{"k":"أَنْصَتَ","c":"","m":"يُنْصِتُ إِنْصاتاً : أَحْسَنَ الاسْتِماعَ ، “يُنْصِتُ التَّلاميذُ إِلى المُعَلِّمِ ، إِذا تَحَدَّثَ” ، ﴿ وَإِذا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا لَعَلَّكُمْ تُرْحَمُونَ ﴾ .","t":"أَحْسَنَ الاسْتِماعَ","o":["يُنْصِتُ التَّلاميذُ إِلى المُعَلِّمِ ، إِذا تَحَدَّثَ","﴿ وَإِذا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا لَعَلَّكُمْ تُرْحَمُونَ ﴾"],"b":["يُنْصِتُ التَّلاميذُ إِلى المُعَلِّمِ ، إِذا تَحَدَّثَ","يُنْصِتُ"],"tr":"kulak vermek, dinlemek","ttr":"İyice dinlemek, kulak kesilmek.","otr":["Öğretmen konuştuğunda öğrenciler onu dikkatle dinler.","Kur'an okunduğu zaman onu dinleyin ve susun ki merhamet olunasınız."],"r":"p33_2","s":33,"f":"يُنْصِتُ إِنْصاتاً"},
{"k":"أَنْصَفَ","c":"","m":"يُنْصِفُ إِنْصافاً : عَدَلَ ، “أَنْصَفَ القاضي في حُكْمِهِ” .","t":"عَدَلَ","o":["أَنْصَفَ القاضي في حُكْمِهِ"],"b":["أَنْصَفَ القاضي في حُكْمِهِ","أَنْصَفَ"],"tr":"adil davranmak","ttr":"Adaletli davranmak.","otr":["Hâkim hükmünde adil davrandı."],"r":null,"s":33,"f":"يُنْصِفُ إِنْصافاً"},
{"k":"أَنْضَجَ","c":"","m":"يُنْضِجُ إِنْضاجاً : جَعَلَهُ ناضِجاً . “أَنْضَجَ الطّاهي اللَّحْمَ ، فَأَصْبَحَ صالِحاً لِلأَكْلِ” .","t":"جَعَلَهُ ناضِجاً","o":["أَنْضَجَ الطّاهي اللَّحْمَ ، فَأَصْبَحَ صالِحاً لِلأَكْلِ"],"b":["أَنْضَجَ الطّاهي اللَّحْمَ ، فَأَصْبَحَ صالِحاً لِلأَكْلِ","أَنْضَجَ"],"tr":"pişirmek, olgunlaştırmak","ttr":"Bir şeyi pişmiş/olgun hâle getirmek.","otr":["Aşçı eti pişirdi, et yenecek hâle geldi."],"r":null,"s":33,"f":"يُنْضِجُ إِنْضاجاً"},
{"k":"أَنْطَقَ","c":"","m":"يُنْطِقُ إِنْطاقاً : جَعَلَهُ يَنْطِقُ وَيَتَكَلَّمُ ، “لَمْ يُرِدِ اللِّصُّ أَنْ يَتَكَلَّمَ ، لكِنَّ القاضي أَنْطَقَهُ” . ﴿ وَقالُوا لِجُلُودِهِمْ لِمَ شَهِدْتُمْ عَلَيْنا قالُوا أَنْطَقَنا اللَّهُ الَّذي أَنْطَقَ كُلَّ شَيْءٍ ﴾ .","t":"جَعَلَهُ يَنْطِقُ وَيَتَكَلَّمُ","o":["لَمْ يُرِدِ اللِّصُّ أَنْ يَتَكَلَّمَ ، لكِنَّ القاضي أَنْطَقَهُ","﴿ وَقالُوا لِجُلُودِهِمْ لِمَ شَهِدْتُمْ عَلَيْنا قالُوا أَنْطَقَنا اللَّهُ الَّذي أَنْطَقَ كُلَّ شَيْءٍ ﴾"],"b":["لَمْ يُرِدِ اللِّصُّ أَنْ يَتَكَلَّمَ ، لكِنَّ القاضي أَنْطَقَهُ","أَنْطَقَهُ"],"tr":"konuşturmak","ttr":"Birini konuşturmak.","otr":["Hırsız konuşmak istemedi ama hâkim onu konuşturdu.","Derilerine “Niçin aleyhimize şahitlik ettiniz?” dediler. Onlar: “Her şeyi konuşturan Allah bizi konuşturdu” dediler."],"r":null,"s":33,"f":"يُنْطِقُ إِنْطاقاً"},
{"k":"أَنْعَمَ","c":"","m":"يُنْعِمُ إِنْعاماً : أَعْطَى وَأَحْسَنَ العَطاءَ ، “أَنْعَمَ اللهُ عَلَيْنا بِنِعَمٍ كَثيرَةٍ” ، ﴿ صِراطَ الَّذينَ أَنْعَمْتَ عَلَيْهِمْ ﴾ ، ﴿ وَإِذا أَنْعَمْنا عَلَى الإِنْسانِ أَعْرَضَ وَنَأَى بِجانِبِهِ ﴾ .","t":"أَعْطَى وَأَحْسَنَ العَطاءَ","o":["أَنْعَمَ اللهُ عَلَيْنا بِنِعَمٍ كَثيرَةٍ","﴿ صِراطَ الَّذينَ أَنْعَمْتَ عَلَيْهِمْ ﴾","﴿ وَإِذا أَنْعَمْنا عَلَى الإِنْسانِ أَعْرَضَ وَنَأَى بِجانِبِهِ ﴾"],"b":["أَنْعَمَ اللهُ عَلَيْنا بِنِعَمٍ كَثيرَةٍ","أَنْعَمَ"],"tr":"nimet vermek","ttr":"Vermek ve güzelce ihsan etmek.","otr":["Allah bize pek çok nimet verdi.","Kendilerine nimet verdiklerinin yoluna...","İnsana nimet verdiğimizde yüz çevirir ve yan çizer."],"r":null,"s":33,"f":"يُنْعِمُ إِنْعاماً"},
{"k":"أَنْف","c":"أُنوفٌ وآناف","m":"(ج) أُنوفٌ وَآناف : عُضْوُ التَّنَفُّسِ وَالشَّمِّ ، ﴿ وَكَتَبْنا عَلَيْهِمْ فيها أَنَّ النَّفْسَ بِالنَّفْسِ وَالْعَيْنَ بِالْعَيْنِ وَالأَنْفَ بِالأَنْفِ ﴾ .","t":"عُضْوُ التَّنَفُّسِ وَالشَّمِّ","o":["﴿ وَكَتَبْنا عَلَيْهِمْ فيها أَنَّ النَّفْسَ بِالنَّفْسِ وَالْعَيْنَ بِالْعَيْنِ وَالأَنْفَ بِالأَنْفِ ﴾"],"b":["وَكَتَبْنا عَلَيْهِمْ فيها أَنَّ النَّفْسَ بِالنَّفْسِ وَالْعَيْنَ بِالْعَيْنِ وَالأَنْفَ بِالأَنْفِ","وَالأَنْفَ"],"tr":"burun","ttr":"Solunum ve koklama organı.","otr":["Orada (Tevrat'ta) onlara cana can, göze göz, buruna burun ... diye yazdık."],"r":"p34_1","s":34,"y":[["جمع","آناف"],["جمع","أُنوف"]]},
{"k":"أَنْفَقَ","c":"","m":"يُنْفِقُ إِنْفاقاً : صَرَفَ المالَ ، “أَنْفَقَ أَبو بَكْرٍ مالَهُ كُلَّهُ في سَبيلِ اللهِ” ، ﴿ لا يَسْتَوي مِنْكُمْ مَنْ أَنْفَقَ مِنْ قَبْلِ الْفَتْحِ ﴾ ، ﴿ إِذاً لَأَمْسَكْتُمْ خَشْيَةَ الإِنْفاقِ ﴾ .","t":"صَرَفَ المالَ","o":["أَنْفَقَ أَبو بَكْرٍ مالَهُ كُلَّهُ في سَبيلِ اللهِ","﴿ لا يَسْتَوي مِنْكُمْ مَنْ أَنْفَقَ مِنْ قَبْلِ الْفَتْحِ ﴾","﴿ إِذاً لَأَمْسَكْتُمْ خَشْيَةَ الإِنْفاقِ ﴾"],"b":["أَنْفَقَ أَبو بَكْرٍ مالَهُ كُلَّهُ في سَبيلِ اللهِ","أَنْفَقَ"],"tr":"harcamak, infak etmek","ttr":"Mal harcamak.","otr":["Ebû Bekir bütün malını Allah yolunda harcadı.","Sizden, fetihten önce infak eden (ve savaşan) kimse (ötekilerle) bir değildir.","O zaman da harcamaktan korkarak elinizde tutardınız."],"r":null,"s":34,"y":[["مصدر","إِنْفاق"]],"f":"يُنْفِقُ إِنْفاقاً"},
{"k":"أَنْقاض","c":"","m":"ما تَبَقَّى مِنْ حِجارَةٍ وَغَيْرِها بَعْدَ هَدْمِ البِناءِ ، “بَعْدَ هَدْمِ البَيْتِ أُزيلَتِ الأَنْقاضُ” .","t":"ما تَبَقَّى مِنْ حِجارَةٍ وَغَيْرِها بَعْدَ هَدْمِ البِناءِ","o":["بَعْدَ هَدْمِ البَيْتِ أُزيلَتِ الأَنْقاضُ"],"b":["بَعْدَ هَدْمِ البَيْتِ أُزيلَتِ الأَنْقاضُ","الأَنْقاضُ"],"tr":"enkaz, moloz","ttr":"Bir bina yıkıldıktan sonra geriye kalan taş vb. kalıntılar.","otr":["Ev yıkıldıktan sonra enkaz kaldırıldı."],"r":"p34_2","s":34},
{"k":"أَنْقَذَ","c":"","m":"يُنْقِذُ إِنْقاذاً : خَلَّصَ وَنَجَّى ، “أَنْقَذَ أَخي الطِّفْلَ مِنَ الغَرَقِ” ، ﴿ وَكُنْتُمْ عَلَى شَفا حُفْرَةٍ مِنَ النّارِ فَأَنْقَذَكُمْ مِنْها ﴾ .","t":"خَلَّصَ وَنَجَّى","o":["أَنْقَذَ أَخي الطِّفْلَ مِنَ الغَرَقِ","﴿ وَكُنْتُمْ عَلَى شَفا حُفْرَةٍ مِنَ النّارِ فَأَنْقَذَكُمْ مِنْها ﴾"],"b":["أَنْقَذَ أَخي الطِّفْلَ مِنَ الغَرَقِ","أَنْقَذَ"],"tr":"kurtarmak","ttr":"Kurtarmak, selamete çıkarmak.","otr":["Kardeşim çocuğu boğulmaktan kurtardı.","Siz ateşten bir çukurun tam kenarındaydınız, O sizi oradan kurtardı."],"r":"p34_3","s":34,"f":"يُنْقِذُ إِنْقاذاً"},
{"k":"أَنْكَحَ","c":"","m":"يُنْكِحُ إِنْكاحاً : زَوَّجَ ، ﴿ وَأَنْكِحُوا الأَيامى مِنْكُمْ ﴾ .","t":"زَوَّجَ","o":["﴿ وَأَنْكِحُوا الأَيامى مِنْكُمْ ﴾"],"b":["وَأَنْكِحُوا الأَيامى مِنْكُمْ","وَأَنْكِحُوا"],"tr":"evlendirmek","ttr":"Evlendirmek.","otr":["İçinizdeki bekârları evlendirin."],"r":null,"s":34,"f":"يُنْكِحُ إِنْكاحاً"},
{"k":"أَنْكَرَ","c":"","m":"يُنْكِرُ إِنْكاراً : ( ١ ) جَحَدَ أَو ادَّعَى أَنَّهُ لا يَعْرِفُ ، “البَيِّنَةُ عَلى مَنِ ادَّعَى ، وَاليَمينُ عَلَى مَنْ أَنْكَرَ” ، ﴿ يَعْرِفُونَ نِعْمَتَ اللَّهِ ثُمَّ يُنْكِرُونَها ﴾ . ( ٢ ) عابَ ، “أَنْكَرْتُ ما فَعَلَهُ صَديقي مِنْ أَخْطاءٍ” .","t":"( ١ ) جَحَدَ أَو ادَّعَى أَنَّهُ لا يَعْرِفُ ( ٢ ) عابَ","o":["البَيِّنَةُ عَلى مَنِ ادَّعَى ، وَاليَمينُ عَلَى مَنْ أَنْكَرَ","﴿ يَعْرِفُونَ نِعْمَتَ اللَّهِ ثُمَّ يُنْكِرُونَها ﴾","أَنْكَرْتُ ما فَعَلَهُ صَديقي مِنْ أَخْطاءٍ"],"b":["أَنْكَرْتُ ما فَعَلَهُ صَديقي مِنْ أَخْطاءٍ","أَنْكَرْتُ"],"tr":"inkâr etmek; kınamak","ttr":"(1) İnkâr etmek ya da bilmediğini iddia etmek. (2) Ayıplamak, kınamak.","otr":["Delil getirmek iddia edene, yemin inkâr edene düşer.","Allah'ın nimetini bilirler, sonra onu inkâr ederler.","Arkadaşımın yaptığı hataları kınadım."],"r":null,"s":34,"f":"يُنْكِرُ إِنْكاراً"},
{"k":"أَنْمُلَة","c":"أَنامِل","m":"(ج) أَنامِل : طَرَفُ الإِصْبَعِ الَّذي يَحْتَوي عَلَى الظُّفُرِ ، ﴿ وَإِذا خَلَوْا عَضُّوا عَلَيْكُمُ الأَنامِلَ مِنَ الْغَيْظِ ﴾ .","t":"طَرَفُ الإِصْبَعِ الَّذي يَحْتَوي عَلَى الظُّفُرِ","o":["﴿ وَإِذا خَلَوْا عَضُّوا عَلَيْكُمُ الأَنامِلَ مِنَ الْغَيْظِ ﴾"],"b":["وَإِذا خَلَوْا عَضُّوا عَلَيْكُمُ الأَنامِلَ مِنَ الْغَيْظِ","الأَنامِلَ"],"tr":"parmak ucu","ttr":"Parmağın tırnağı taşıyan uç kısmı.","otr":["Kendi başlarına kaldıklarında size olan öfkelerinden parmak uçlarını ısırırlar."],"r":"p34_4","s":34},
{"k":"أَنْهى","c":"","m":"يُنْهي إِنْهاءً : ( ١ ) بَلَغَ الغايَةَ وَالنِّهايَةَ ، “أَنْهى قِراءَةَ الدَّرْسِ” . ( ٢ ) طَلَبَ الكَفَّ عَنْ فِعْلِ الشَّيْءِ ، “كُنْتُ أَنْهاهُ عَنْ شُرْبِ الخَمْرِ حَتّى تَرَكَها” ، ﴿ أَرَأَيْتَ الَّذي يَنْهى ، عَبْداً إِذا صَلّى ﴾ .","t":"( ١ ) بَلَغَ الغايَةَ وَالنِّهايَةَ ( ٢ ) طَلَبَ الكَفَّ عَنْ فِعْلِ الشَّيْءِ","o":["أَنْهى قِراءَةَ الدَّرْسِ","كُنْتُ أَنْهاهُ عَنْ شُرْبِ الخَمْرِ حَتّى تَرَكَها","﴿ أَرَأَيْتَ الَّذي يَنْهى ، عَبْداً إِذا صَلّى ﴾"],"b":["أَنْهى قِراءَةَ الدَّرْسِ","أَنْهى"],"tr":"bitirmek, sona erdirmek","ttr":"(1) Sona ulaşmak, bitirmek. (2) Bir şeyi yapmaktan vazgeçmesini istemek.","otr":["Dersi okumayı bitirdi.","Onu içki içmekten men ediyordum, sonunda bıraktı.","Gördün mü o engelleyeni, namaz kılan bir kulu?"],"r":null,"s":34,"f":"يُنْهي إِنْهاءً"},
{"k":"أَنيق","c":"","m":"صِفَةُ الشَّخْصِ أَوِ الشَّيْءِ حَسَنِ المَظْهَرِ وَالتَّرْتيبِ وَالتَّنْسيقِ ، “بَدا الأُسْتاذُ بِمَظْهَرٍ أَنيقٍ في سَيّارَةٍ أَنيقَةٍ” .","t":"صِفَةُ الشَّخْصِ أَوِ الشَّيْءِ حَسَنِ المَظْهَرِ وَالتَّرْتيبِ وَالتَّنْسيقِ","o":["بَدا الأُسْتاذُ بِمَظْهَرٍ أَنيقٍ في سَيّارَةٍ أَنيقَةٍ"],"b":["بَدا الأُسْتاذُ بِمَظْهَرٍ أَنيقٍ في سَيّارَةٍ أَنيقَةٍ","أَنيقٍ"],"tr":"şık, zarif","ttr":"Görünüşü, düzeni ve uyumu güzel olan kişi veya şeyin sıfatı.","otr":["Öğretmen şık bir arabada şık bir görünümle ortaya çıktı."],"r":"p34_5","s":34},
{"k":"أَهابَ","c":"","m":"يُهيبُ إِهابَةً : دَعا وَحَثَّ ، “أَهابَ بِصاحِبِهِ إِلى تَقْديمِ المُساعَدَةِ لِلآخَرينَ” .","t":"دَعا وَحَثَّ","o":["أَهابَ بِصاحِبِهِ إِلى تَقْديمِ المُساعَدَةِ لِلآخَرينَ"],"b":["أَهابَ بِصاحِبِهِ إِلى تَقْديمِ المُساعَدَةِ لِلآخَرينَ","أَهابَ"],"tr":"çağırmak, teşvik etmek","ttr":"Çağırmak ve teşvik etmek.","otr":["Arkadaşını başkalarına yardım etmeye çağırdı."],"r":null,"s":34,"f":"يُهيبُ إِهابَةً"},
{"k":"أَهاجَ","c":"","m":"يُهيجُ إِهاجَةً : حَرَّكَ وَأَثارَ وَبَعْثَرَ ، “أَهاجَتِ الرِّياحُ الأَمْواجَ” ، “أَهاجَ الشِّعْرُ حَنينَهُ إِلى وَطَنِهِ” .","t":"حَرَّكَ وَأَثارَ وَبَعْثَرَ","o":["أَهاجَتِ الرِّياحُ الأَمْواجَ","أَهاجَ الشِّعْرُ حَنينَهُ إِلى وَطَنِهِ"],"b":["أَهاجَتِ الرِّياحُ الأَمْواجَ","أَهاجَتِ"],"tr":"kabartmak, coşturmak","ttr":"Hareketlendirmek, kışkırtmak, dağıtmak.","otr":["Rüzgârlar dalgaları kabarttı.","Şiir onun vatan hasretini alevlendirdi."],"r":null,"s":34,"f":"يُهيجُ إِهاجَةً"},
{"k":"أَهازيج","c":"","m":"ما يُطْرِبُ مِنَ الأَلْحانِ ، “سَمِعْتُ أَهازيجَ الرُّعاةِ” .","t":"ما يُطْرِبُ مِنَ الأَلْحانِ","o":["سَمِعْتُ أَهازيجَ الرُّعاةِ"],"b":["سَمِعْتُ أَهازيجَ الرُّعاةِ","أَهازيجَ"],"tr":"neşeli ezgiler, türküler","ttr":"İnsanı coşturan ezgiler.","otr":["Çobanların türkülerini duydum."],"r":null,"s":34},
{"k":"أَهانَ","c":"","m":"يُهينُ إِهانَةً : احْتَقَرَ ، أَذَلَّ ، “أَهانَ المُسْتَعْمِرُ المُواطِنينَ فَثاروا” .","t":"احْتَقَرَ ، أَذَلَّ","o":["أَهانَ المُسْتَعْمِرُ المُواطِنينَ فَثاروا"],"b":["أَهانَ المُسْتَعْمِرُ المُواطِنينَ فَثاروا","أَهانَ"],"tr":"aşağılamak, hakaret etmek","ttr":"Hor görmek, zelil etmek.","otr":["Sömürgeci vatandaşları aşağıladı, onlar da ayaklandı."],"r":null,"s":34,"f":"يُهينُ إِهانَةً"},
{"k":"أَهْبَل","c":"هُبْل","m":"(ج) هُبْل : ضَعيفُ العَقْلِ ، “لا تُصَدِّقْ هذا الأَهْبَلَ” .","t":"ضَعيفُ العَقْلِ","o":["لا تُصَدِّقْ هذا الأَهْبَلَ"],"b":["لا تُصَدِّقْ هذا الأَهْبَلَ","الأَهْبَلَ"],"tr":"budala, ahmak","ttr":"Aklı zayıf olan.","otr":["Bu budalaya inanma."],"r":null,"s":34},
{"k":"أَهْتَم","c":"هُتْم","m":"(مؤ) هَتْماء ، (ج) هُتْم : مَنْ تَكَسَّرَتْ ثَناياهُ ، “بَعْدَ أَنْ خُلِعَتْ ثَنِيَّتا أَبي عُبَيْدَةَ صارَ أَهْتَمَ” .","t":"مَنْ تَكَسَّرَتْ ثَناياهُ","o":["بَعْدَ أَنْ خُلِعَتْ ثَنِيَّتا أَبي عُبَيْدَةَ صارَ أَهْتَمَ"],"b":["بَعْدَ أَنْ خُلِعَتْ ثَنِيَّتا أَبي عُبَيْدَةَ صارَ أَهْتَمَ","أَهْتَمَ"],"tr":"ön dişleri kırık","ttr":"Ön dişleri kırılmış kimse. Dişili: hetmâ.","otr":["Ebû Ubeyde'nin iki ön dişi söküldükten sonra ön dişsiz kaldı."],"r":"p34_6","s":34}];
